#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Studio Room Walkthrough  (Python + PyOpenGL + pygame)

 - 1 หน่วยใน OpenGL = 1 เมตรจริง
 - เดินด้วย W A S D, หมุนกล้องด้วยเมาส์ (หรือปุ่มลูกศร)
 - สเกลทั้งหมดอ้างอิงจากตัวเลขที่วัดไว้ใน Studio.pdf

ติดตั้ง:   pip install pygame PyOpenGL numpy
รัน:       python studio.py

ปุ่ม:
  W A S D     เดินหน้า / ซ้าย / ถอยหลัง / ขวา
  Mouse       หมุนกล้อง (หรือใช้ปุ่มลูกศร)
  Shift       วิ่ง
  C           เปิด/ปิดการชนกับของในห้อง
  TAB         ปล่อย/จับเมาส์
  H           ซ่อน/แสดงข้อความช่วยเหลือ
  R           กลับไปจุดเริ่มต้น
  F12         บันทึกภาพหน้าจอ (screenshot_x.png)
  Esc         ออก
"""
import math  # เรียกใช้ชุดเครื่องมือคณิตศาสตร์ (sin, cos, รากที่สอง, พาย)
import random  # เรียกใช้ตัวสุ่มตัวเลข (ไฟล์นี้ยังไม่ได้ใช้ แต่เตรียมไว้)
import sys  # เรียกใช้เครื่องมือจัดการตัวโปรแกรม เช่น สั่งปิดโปรแกรม (ยังไม่ได้ใช้ในไฟล์นี้)
import numpy as np  # เรียกใช้ชุดคำนวณตัวเลขจำนวนมาก ตั้งชื่อย่อว่า np
import pygame  # เรียกใช้ชุดทำเกม (เปิดหน้าต่าง รับคีย์บอร์ดและเมาส์)
from pygame.locals import *  # ดึงค่าคงที่ของ pygame ทั้งหมดมาใช้ได้ตรง ๆ
from OpenGL.GL import *  # ดึงคำสั่งวาดภาพ 3 มิติ (ตัวหลัก) มาใช้
from OpenGL.GLU import *  # ดึงคำสั่งเสริมของ OpenGL เช่น การตั้งมุมกล้อง
 
# =====================================================================
# 1) ขนาดห้อง (เมตร)   X = ซ้าย->ขวา (ตะวันตก->ตะวันออก)
#                       Y = ความสูง
#                       Z = เหนือ(หน้าต่าง) -> ใต้(ประตู)
# =====================================================================
INCH = 0.0254  # 1 นิ้ว เท่ากับ 0.0254 เมตร (ใช้แปลงหน่วย)
W = 305 * INCH      # 7.75 m  ความกว้างผนังประตู / ผนังหน้าต่าง  # ความกว้างห้อง 305 นิ้ว แปลงเป็นเมตร
D = 355 * INCH      # 9.02 m  ความยาวผนังผ้าม่าน / ผนังไวท์บอร์ด  # ความยาวห้อง 355 นิ้ว แปลงเป็นเมตร
H = 130 * INCH      # 3.30 m  ความสูงเพดาน  # ความสูงเพดาน 130 นิ้ว แปลงเป็นเมตร
 
EYE_HEIGHT = 1.60   # ระดับสายตา  # กล้องอยู่สูง 1.60 เมตร เหมือนสายตาคน
PLAYER_RADIUS = 0.16   # ครึ่งหนึ่งของความกว้างตัวคน (เล็กลง = เดินแทรกที่แคบได้ง่ายขึ้น)  # ความ "อ้วน" ของผู้เดิน ใช้ตอนเช็กการชน
WALK_SPEED = 1.5    # m/s  # ความเร็วเดิน 1.5 เมตรต่อวินาที
RUN_SPEED = 3.2  # ความเร็วตอนวิ่ง 3.2 เมตรต่อวินาที
START_POS = (W / 2, 8.4)   # จุดเริ่ม: ตรงหน้าประตู  # จุดเริ่มต้น: กลางห้องตามแนวกว้าง และอยู่ใกล้ประตู
START_YAW = 0.0            # 0 = หันไปทางผนังหน้าต่าง (-Z)  # ทิศที่หันหน้าตอนเริ่ม (0 = หันไปทางหน้าต่าง)
CABINET_H = 1.90         # ความสูงตัวตู้เหล็ก (ไม่รวมกล่องขาวด้านบน) ปรับตรงนี้ได้  # ความสูงตู้เหล็ก 1.90 เมตร
DESK_SHIFT_X = -0.125      # เลื่อนของบนโต๊ะไปทางซ้าย (-x) 12.5 ซม. ให้เว้นขอบโต๊ะซ้าย-ขวาเท่ากัน  # ปรับกึ่งกลางแนวซ้าย-ขวา
DESK_SHIFT_Z = 0.05        # เลื่อนของบนโต๊ะถอยเข้าหาจอ (+z) 5 ซม. ให้เว้นขอบโต๊ะหน้า-หลังเท่ากัน  # ปรับกึ่งกลางแนวหน้า-หลัง
BLACK_TABLE_Z = 1.50       # ตำแหน่งโต๊ะดำ (ระยะจากผนังหน้าต่าง) ของฝั่งคอมทั้งชุดอิงค่านี้ ลดลง = ชิดหน้าต่างมากขึ้น  # โต๊ะดำอยู่ห่างผนังหน้าต่าง 1.50 เมตร
ROW_GAP = 0.65            # ช่องว่างระหว่างแถวโต๊ะขาว (เท่ากันทุกช่อง) ที่เหลือจะเป็นพื้นที่โล่งตรงประตู  # ช่องว่างระหว่างแถวโต๊ะ 0.65 เมตร
BEAM_HANG = 0.60            # คานดำห้อยลงมาจากเพดานกี่เมตร (ลดลง = คานยกสูงขึ้น ไม่ชนกรอบกระจกเหนือประตู)  # คานห้อยลงจากเพดาน 0.60 เมตร
GLASS_ALPHA = 0.16        # ความทึบของกระจกตู้ (0 = ใสสนิท, 1 = ทึบ) ยิ่งน้อยยิ่งใส  # ความทึบกระจก ยิ่งน้อยยิ่งใส
 
# ---- สีที่ใช้บ่อย ----
WALL_GREY = (0.53, 0.55, 0.60)  # สีเทาของผนัง (ตัวเลข 3 ค่า = แดง, เขียว, น้ำเงิน ช่วง 0-1)
BLACK = (0.04, 0.04, 0.05)  # สีดำ (ไม่ดำสนิท ให้ดูมีมิติ)
WHITE = (0.92, 0.92, 0.92)  # สีขาวนวล
WOOD = (0.86, 0.72, 0.52)  # สีไม้อ่อน
CURTAIN = (0.27, 0.29, 0.35)  # สีผ้าม่าน (เทาเข้ม)
STEEL = (0.78, 0.80, 0.82)  # สีเหล็ก (เทาอ่อน)
 
COLLIDERS = []      # กล่องชน (x0, z0, x1, z1)  # สมุดจดของที่เดินทะลุไม่ได้ เริ่มต้นว่างเปล่า
 
 
# =====================================================================
# 2) ฟังก์ชันวาดพื้นฐาน
# =====================================================================
SHADE_TOP, SHADE_BOT = 1.00, 0.55  # ความสว่างด้านบน (เต็ม) และด้านล่าง (มืดลง)
SHADE_N, SHADE_S, SHADE_E, SHADE_W = 0.80, 0.90, 0.93, 0.72   # ไม่ใช้ไฟจริง ใช้เฉดสีหลอกแทน  # ความสว่างด้านเหนือ ใต้ ตะวันออก ตะวันตก
 
 
def box(x0, y0, z0, x1, y1, z1, c, solid=False, flat=False):  # สร้างสูตรวาดกล่อง รับมุมกล่อง 2 มุม สี และตัวเลือกอีก 2 อย่าง
    """กล่องสี่เหลี่ยม (มุมต่ำ -> มุมสูง) solid=True คือให้เดินชนได้"""
    if solid:  # ถ้ากล่องนี้ต้องเดินชนได้
        COLLIDERS.append((min(x0, x1), min(z0, z1), max(x0, x1), max(z0, z1)))  # จดพื้นที่ของกล่อง (มองจากด้านบน) ลงสมุดสิ่งกีดขวาง
    r, g, b = c  # แยกสีเป็น 3 ค่า แดง เขียว น้ำเงิน
    k = (1, 1, 1, 1, 1, 1) if flat else (SHADE_TOP, SHADE_BOT, SHADE_N, SHADE_S, SHADE_W, SHADE_E)  # เลือกค่าความสว่างของแต่ละด้าน (ถ้า flat ทุกด้านเท่ากัน)
    glBegin(GL_QUADS)  # บอกการ์ดจอว่าจะวาดแผ่นสี่เหลี่ยมต่อไปนี้
    glColor3f(r * k[0], g * k[0], b * k[0])   # top  # เลือกสีของด้านบน
    glVertex3f(x0, y1, z0); glVertex3f(x1, y1, z0); glVertex3f(x1, y1, z1); glVertex3f(x0, y1, z1)  # ระบุ 4 มุมของด้านบน
    glColor3f(r * k[1], g * k[1], b * k[1])   # bottom  # เลือกสีของด้านล่าง
    glVertex3f(x0, y0, z0); glVertex3f(x1, y0, z0); glVertex3f(x1, y0, z1); glVertex3f(x0, y0, z1)  # ระบุ 4 มุมของด้านล่าง
    glColor3f(r * k[2], g * k[2], b * k[2])   # north (-z)  # เลือกสีของด้านเหนือ
    glVertex3f(x0, y0, z0); glVertex3f(x1, y0, z0); glVertex3f(x1, y1, z0); glVertex3f(x0, y1, z0)  # ระบุ 4 มุมของด้านเหนือ
    glColor3f(r * k[3], g * k[3], b * k[3])   # south (+z)  # เลือกสีของด้านใต้
    glVertex3f(x0, y0, z1); glVertex3f(x1, y0, z1); glVertex3f(x1, y1, z1); glVertex3f(x0, y1, z1)  # ระบุ 4 มุมของด้านใต้
    glColor3f(r * k[4], g * k[4], b * k[4])   # west (-x)  # เลือกสีของด้านตะวันตก
    glVertex3f(x0, y0, z0); glVertex3f(x0, y0, z1); glVertex3f(x0, y1, z1); glVertex3f(x0, y1, z0)  # ระบุ 4 มุมของด้านตะวันตก
    glColor3f(r * k[5], g * k[5], b * k[5])   # east (+x)  # เลือกสีของด้านตะวันออก
    glVertex3f(x1, y0, z0); glVertex3f(x1, y0, z1); glVertex3f(x1, y1, z1); glVertex3f(x1, y1, z0)  # ระบุ 4 มุมของด้านตะวันออก
    glEnd()  # บอกการ์ดจอว่าวาดเสร็จแล้ว
 
 
def cbox(cx, y0, cz, sx, sy, sz, c, solid=False, flat=False):  # ทางลัดวาดกล่อง โดยบอกจุดกึ่งกลางกับขนาด แทนการบอกมุม
    """กล่องแบบระบุจุดกึ่งกลาง (x,z) + ขนาด"""
    box(cx - sx / 2, y0, cz - sz / 2, cx + sx / 2, y0 + sy, cz + sz / 2, c, solid, flat)  # คำนวณมุมทั้งสองจากจุดกลางและขนาด แล้วเรียกฟังก์ชัน box
 
 
def cylinder(cx, y0, cz, r, h, c, seg=18, solid=False):  # สร้างสูตรวาดทรงกระบอก (ตำแหน่ง รัศมี ความสูง สี จำนวนด้าน)
    if solid:  # ถ้าต้องเดินชนได้
        COLLIDERS.append((cx - r, cz - r, cx + r, cz + r))  # จดพื้นที่สี่เหลี่ยมที่ครอบทรงกระบอกลงสมุดสิ่งกีดขวาง
    rr, gg, bb = c  # แยกสีเป็น 3 ค่า
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม (ผนังข้างของกระบอก)
    for i in range(seg):  # วนซ้ำทีละด้านของกระบอก
        a0 = 2 * math.pi * i / seg  # มุมเริ่มต้นของแผ่นนี้ (หน่วยเรเดียน)
        a1 = 2 * math.pi * (i + 1) / seg  # มุมสิ้นสุดของแผ่นนี้
        s = 0.75 + 0.25 * math.cos(a0 - 0.8)  # คำนวณความสว่าง ให้ด้านหนึ่งสว่างกว่าอีกด้าน
        glColor3f(rr * s, gg * s, bb * s)  # เลือกสีของแผ่นนี้
        glVertex3f(cx + r * math.cos(a0), y0, cz + r * math.sin(a0))  # มุมล่างซ้ายของแผ่น
        glVertex3f(cx + r * math.cos(a1), y0, cz + r * math.sin(a1))  # มุมล่างขวาของแผ่น
        glVertex3f(cx + r * math.cos(a1), y0 + h, cz + r * math.sin(a1))  # มุมบนขวาของแผ่น
        glVertex3f(cx + r * math.cos(a0), y0 + h, cz + r * math.sin(a0))  # มุมบนซ้ายของแผ่น
    glEnd()  # วาดผนังข้างเสร็จ
    glColor3f(rr, gg, bb)  # เลือกสีเต็มสำหรับฝาด้านบน
    glBegin(GL_TRIANGLE_FAN)  # เริ่มวาดแบบพัด (สามเหลี่ยมหลายอันที่มีจุดร่วมกันตรงกลาง)
    glVertex3f(cx, y0 + h, cz)  # จุดกึ่งกลางฝา
    for i in range(seg + 1):  # วนรอบขอบฝาให้ครบ 1 รอบ
        a = 2 * math.pi * i / seg  # มุมของจุดบนขอบ
        glVertex3f(cx + r * math.cos(a), y0 + h, cz + r * math.sin(a))  # จุดบนขอบฝา
    glEnd()  # วาดฝาเสร็จ
 
 
def dome(cx, cz, r, ca, cb, squash=0.78, seg=20, rings=6, solid=True):  # สร้างสูตรวาดโดมครึ่งทรงกลมสลับสี 2 สี
    """ซอฟต์บ็อกซ์ทรงโดม (ครึ่งทรงกลม) ใช้สลับสีเป็นซี่ๆ ให้เหมือนโครงร่ม"""
    if solid:  # ถ้าต้องเดินชนได้
        COLLIDERS.append((cx - r, cz - r, cx + r, cz + r))  # จดพื้นที่ของโดมลงสมุดสิ่งกีดขวาง
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยมเล็ก ๆ บนผิวโดม
    for i in range(seg):  # วนทีละซี่ (แนวรอบโดม)
        a0 = 2 * math.pi * i / seg  # มุมเริ่มของซี่
        a1 = 2 * math.pi * (i + 1) / seg  # มุมจบของซี่
        col = ca if i % 2 == 0 else cb  # ซี่เลขคู่ใช้สีแรก ซี่เลขคี่ใช้สีสอง
        for k in range(rings):  # วนทีละวงจากขอบขึ้นไปยอด
            t0 = (math.pi / 2) * k / rings  # มุมเงยของขอบล่างของแผ่น
            t1 = (math.pi / 2) * (k + 1) / rings  # มุมเงยของขอบบนของแผ่น
            s = 0.6 + 0.4 * math.sin((t0 + t1) / 2)  # ความสว่าง ยิ่งใกล้ยอดยิ่งสว่าง
            glColor3f(col[0] * s, col[1] * s, col[2] * s)  # เลือกสีแผ่นนี้
            for (a, t) in ((a0, t0), (a1, t0), (a1, t1), (a0, t1)):  # วนทั้ง 4 มุมของแผ่น
                glVertex3f(cx + r * math.cos(t) * math.cos(a), r * squash * math.sin(t),  # ตำแหน่งแกน x และแกน y ของมุม
                           cz + r * math.cos(t) * math.sin(a))  # ตำแหน่งแกน z ของมุม
    glEnd()  # วาดผิวโดมเสร็จ
    cylinder(cx, r * squash - 0.01, cz, 0.07, 0.05, STEEL, 12)  # วาดแท่งเหล็กสั้น ๆ ที่ยอดโดมเป็นตัวยึด
 
 
def ball(cx, cy, cz, r, c, seg=12, rings=8):  # สร้างสูตรวาดลูกบอลทรงกลม
    """ทรงกลม (ใส่เฉดสีหลอกให้ดูมีมิติ)"""
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยมเล็ก ๆ ปะเป็นลูกบอล
    for k in range(rings):  # วนทีละวงจากหัวถึงท้ายลูกบอล
        t0, t1 = math.pi * k / rings, math.pi * (k + 1) / rings  # มุมของขอบบนและขอบล่างของวงนี้
        for i in range(seg):  # วนทีละชิ้นรอบลูกบอล
            a0, a1 = 2 * math.pi * i / seg, 2 * math.pi * (i + 1) / seg  # มุมเริ่มและมุมจบของชิ้นนี้
            tm, am = (t0 + t1) / 2, (a0 + a1) / 2  # มุมตรงกลางของแผ่น
            nx, ny, nz = math.sin(tm) * math.cos(am), math.cos(tm), math.sin(tm) * math.sin(am)  # ทิศที่ผิวตรงนี้หันไป
            sh = 0.55 + 0.45 * max(0.0, 0.35 * nx + 0.8 * ny + 0.45 * nz)  # ความสว่าง: หันเข้าหาแสงสมมติยิ่งสว่าง ต่ำสุด 55%
            glColor3f(c[0] * sh, c[1] * sh, c[2] * sh)  # เลือกสีแผ่นนี้
            for (t, a) in ((t0, a0), (t0, a1), (t1, a1), (t1, a0)):  # วนทั้ง 4 มุมของแผ่น
                glVertex3f(cx + r * math.sin(t) * math.cos(a), cy + r * math.cos(t),  # ตำแหน่งแกน x และแกน y ของมุม
                           cz + r * math.sin(t) * math.sin(a))  # ตำแหน่งแกน z ของมุม
    glEnd()  # วาดลูกบอลเสร็จ
 
 
def mic(x, y, z, yaw):  # สร้างสูตรวาดไมค์ (ตำแหน่ง x y z และมุมหมุน)
    """ไมค์ไร้สายแบบมือถือ (แบบ JBL ในรูป) วางนอนบนโต๊ะ ยาวประมาณ 25 cm
    ก่อนหมุนหัวไมค์ชี้ไปทาง +X  yaw = หมุนรอบแกนตั้ง (องศา)"""
    glPushMatrix()  # เซฟตำแหน่งและมุมปัจจุบันไว้ก่อน (เหมือนกดเซฟเกม)
    glTranslatef(x, y, z)  # ย้ายจุดอ้างอิงไปยังตำแหน่งที่จะวางไมค์
    glRotatef(yaw, 0, 1, 0)  # หมุนไมค์รอบแกนตั้ง ให้ชี้ไปทิศที่ต้องการ
    glRotatef(-90, 0, 0, 1)                                          # ให้แกนความยาวชี้ไปทาง +X  # ล้มไมค์ลงมานอน
    cylinder(0, 0.000, 0, 0.0175, 0.130, (0.07, 0.07, 0.08), 14)      # ด้ามจับ  # วาดด้ามจับสีดำ
    cylinder(0, 0.130, 0, 0.0185, 0.045, (0.12, 0.12, 0.13), 14)      # ส่วนต่อหัว  # วาดส่วนที่ต่อกับหัวไมค์
    cylinder(0, 0.055, 0, 0.0185, 0.012, (0.95, 0.45, 0.10), 14)      # แถบสีส้ม (ป้ายแบรนด์)  # วาดแถบสีส้มคาดที่ด้าม
    cylinder(0, 0.175, 0, 0.0245, 0.012, (0.60, 0.62, 0.65), 14)      # วงแหวนโลหะ  # วาดวงแหวนโลหะใต้หัวไมค์
    ball(0, 0.215, 0, 0.034, (0.30, 0.31, 0.33))                      # หัวไมค์ตะแกรง  # วาดหัวไมค์เป็นลูกบอลสีเทา
    glPopMatrix()  # กลับไปยังตำแหน่งที่เซฟไว้ เพื่อไม่ให้กระทบสิ่งอื่นที่จะวาดต่อ
 
 
def _ac_profile(wd, ht, r_top, r_bot, seg=5):  # สร้างรูปหน้าตัดของแอร์ (สี่เหลี่ยมมุมมน) คืนค่าเป็นรายการจุด
    """หน้าตัดแอร์ (z, y) เป็นสี่เหลี่ยมมุมมน เรียงทวนเข็มนาฬิกา"""
    pts = []  # รายการจุดเริ่มต้นว่างเปล่า
 
    def arc(cz, cy, r, a0, a1):  # ฟังก์ชันย่อย: เพิ่มจุดที่เรียงเป็นส่วนโค้งหนึ่งมุม
        for k in range(seg + 1):  # วนตามจำนวนจุดต่อ 1 มุม
            a = math.radians(a0 + (a1 - a0) * k / seg)  # คำนวณมุมของจุดนี้ แล้วแปลงองศาเป็นเรเดียน
            pts.append((cz + r * math.cos(a), cy + r * math.sin(a)))  # เพิ่มจุดลงรายการ
    arc(r_bot, r_bot, r_bot, 180, 270)                 # ล่าง-หลัง  # มุมมนล่างด้านหลัง
    arc(wd - r_bot, r_bot, r_bot, 270, 360)            # ล่าง-หน้า  # มุมมนล่างด้านหน้า
    arc(wd - r_top, ht - r_top, r_top, 0, 90)          # บน-หน้า  # มุมมนบนด้านหน้า
    arc(r_top, ht - r_top, r_top, 90, 180)             # บน-หลัง  # มุมมนบนด้านหลัง
    return pts  # ส่งรายการจุดกลับไปให้ผู้เรียกใช้
 
 
def aircon(cx, z0, y0, length=1.47, wd=0.65, ht=0.25):  # สร้างสูตรวาดแอร์ (ตำแหน่ง ความยาว ความลึก ความสูง)
    """แอร์แขวนเพดาน (ceiling suspended) ตัวเครื่องมุมมนสีครีม
    ด้านหน้า (+Z) มีช่องลมออก + แผงแสดงผล  ด้านล่างมีกริลดูดลมและป้ายเหลือง"""
    x0, x1 = cx - length / 2, cx + length / 2  # ปลายซ้ายและปลายขวาของตัวเครื่อง
    prof = _ac_profile(wd, ht, 0.05, 0.06)  # สร้างรูปหน้าตัดมุมมนของแอร์
    cream = (0.93, 0.91, 0.84)  # สีครีมของตัวแอร์
    n = len(prof)  # นับจำนวนจุดของหน้าตัด
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยมของตัวเครื่อง
    for i in range(n):  # วนทีละช่วงของขอบหน้าตัด
        (za, ya), (zb, yb) = prof[i], prof[(i + 1) % n]  # จุดเริ่มและจุดถัดไป (จุดสุดท้ายวนกลับไปจุดแรก)
        dz, dy = zb - za, yb - ya  # ระยะห่างระหว่างสองจุด
        ln = math.hypot(dz, dy) or 1.0  # ความยาวของช่วงนี้ (กันไม่ให้เป็นศูนย์)
        nz, ny = dy / ln, -dz / ln                      # เวกเตอร์ตั้งฉากของขอบ  # ทิศที่ผิวช่วงนี้หันไป
        sh = 0.60 + 0.40 * max(0.0, 0.85 * ny + 0.5 * nz)  # ความสว่าง ด้านที่หันขึ้นบนสว่างกว่า
        glColor3f(cream[0] * sh, cream[1] * sh, cream[2] * sh)  # เลือกสีของแผ่นนี้
        glVertex3f(x0, y0 + ya, z0 + za); glVertex3f(x1, y0 + ya, z0 + za)  # สองมุมแรกของแผ่น (ซ้ายและขวา)
        glVertex3f(x1, y0 + yb, z0 + zb); glVertex3f(x0, y0 + yb, z0 + zb)  # สองมุมหลังของแผ่น
    glEnd()  # วาดตัวเครื่องเสร็จ
    for xx, sh in ((x0, 0.78), (x1, 0.88)):               # ฝาปิดหัวท้าย  # วนทำฝาปิดทั้งปลายซ้ายและปลายขวา
        glColor3f(cream[0] * sh, cream[1] * sh, cream[2] * sh)  # เลือกสีของฝา
        glBegin(GL_POLYGON)  # เริ่มวาดรูปหลายเหลี่ยมเดียว
        for (zz, yy) in prof:  # วนทุกจุดของหน้าตัด
            glVertex3f(xx, y0 + yy, z0 + zz)  # ใส่จุดนั้นเป็นมุมของฝา
        glEnd()  # วาดฝาเสร็จ
    zf = z0 + wd + 0.004                                  # หน้าแอร์  # ระนาบหน้าแอร์ (ขยับออก 4 มม. กันภาพทับกันจนกะพริบ)
    dark = (0.10, 0.10, 0.11)  # สีเข้มสำหรับช่องลม
    gquad([(cx - 0.55, y0 + 0.075, zf), (cx + 0.55, y0 + 0.075, zf),  # เรียกฟังก์ชันวาดสี่เหลี่ยม (gquad อยู่ในไฟล์ส่วนอื่น) สองมุมล่าง
           (cx + 0.55, y0 + 0.115, zf), (cx - 0.55, y0 + 0.115, zf)], [dark] * 4)           # ช่องลมออก  # สองมุมบน และกำหนดให้ทั้ง 4 มุมเป็นสีเข้ม
    gquad([(cx - 0.70, y0 + 0.150, zf), (cx + 0.70, y0 + 0.150, zf),  # วาดแถบบาง ๆ สองมุมล่าง
           (cx + 0.70, y0 + 0.153, zf), (cx - 0.70, y0 + 0.153, zf)], [(0.72, 0.70, 0.64)] * 4)  # รอยต่อฝา  # สองมุมบน สีเทาครีม เป็นรอยต่อฝา
    gquad([(cx + 0.58, y0 + 0.125, zf), (cx + 0.68, y0 + 0.125, zf),  # วาดหน้าจอแสดงผล สองมุมล่าง
           (cx + 0.68, y0 + 0.180, zf), (cx + 0.58, y0 + 0.180, zf)], [(0.12, 0.13, 0.15)] * 4)  # หน้าจอแสดงผล  # สองมุมบน สีเข้ม
    gquad([(cx + 0.595, y0 + 0.145, zf + 0.001), (cx + 0.615, y0 + 0.145, zf + 0.001),  # วาดไฟสถานะดวงเล็ก สองมุมล่าง
           (cx + 0.615, y0 + 0.160, zf + 0.001), (cx + 0.595, y0 + 0.160, zf + 0.001)],  # สองมุมบน (ยื่นออกมา 1 มม. ให้อยู่เหนือหน้าจอ)
          [(0.25, 0.85, 0.35)] * 4)                       # ไฟสถานะ  # สีเขียว
    yb = y0 - 0.003                                       # ด้านล่าง: กริลดูดลม  # ระดับใต้ท้องแอร์
    for k in range(9):  # วนวาดแถบกริล 9 แถบ
        zz = z0 + 0.13 + k * 0.048  # ตำแหน่งของแถบที่ k (ห่างกันทุก 4.8 ซม.)
        gquad([(cx - 0.62, yb, zz), (cx + 0.40, yb, zz), (cx + 0.40, yb, zz + 0.022), (cx - 0.62, yb, zz + 0.022)],  # วาดแถบยาวหนึ่งแถบ
              [(0.20, 0.20, 0.21)] * 4)  # สีเทาเข้ม
    gquad([(cx + 0.50, yb, z0 + 0.20), (cx + 0.62, yb, z0 + 0.20), (cx + 0.62, yb, z0 + 0.30), (cx + 0.50, yb, z0 + 0.30)],  # วาดป้ายสติกเกอร์ใต้ท้องแอร์
          [(0.95, 0.80, 0.20)] * 4)                       # ป้ายเหลือง  # สีเหลือง
 
 
LIGHT_DIR = (0.35, 0.80, 0.45)  # ทิศทางแสงสมมติ (ขวา บน หน้า) ใช้คำนวณความสว่าง
 
 
def tube(p0, p1, r, c, seg=8):  # สร้างสูตรวาดท่อกลมจากจุด p0 ไปจุด p1 (ท่อเอียงได้)
    """ท่อกลมระหว่างจุด p0 -> p1 (ใช้ทำขา C-stand ที่โค้งงอ)"""
    d = (p1[0] - p0[0], p1[1] - p0[1], p1[2] - p0[2])  # ทิศจากจุดเริ่มไปจุดจบ
    L = math.sqrt(d[0] ** 2 + d[1] ** 2 + d[2] ** 2) or 1.0  # ความยาวท่อ (กันไม่ให้เป็นศูนย์)
    d = (d[0] / L, d[1] / L, d[2] / L)  # ทำทิศให้มีความยาวเป็น 1
    ref = (0, 1, 0) if abs(d[1]) < 0.9 else (1, 0, 0)  # เลือกแกนอ้างอิงที่ไม่ขนานกับท่อ
    u = (d[1] * ref[2] - d[2] * ref[1], d[2] * ref[0] - d[0] * ref[2], d[0] * ref[1] - d[1] * ref[0])  # หาแกนที่ตั้งฉากกับท่อ (ด้วย cross product)
    ul = math.sqrt(u[0] ** 2 + u[1] ** 2 + u[2] ** 2) or 1.0  # ความยาวของแกนนั้น
    u = (u[0] / ul, u[1] / ul, u[2] / ul)  # ทำแกนให้มีความยาวเป็น 1
    v = (d[1] * u[2] - d[2] * u[1], d[2] * u[0] - d[0] * u[2], d[0] * u[1] - d[1] * u[0])  # หาแกนที่สองที่ตั้งฉากกับทั้งท่อและแกนแรก
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยมรอบท่อ
    for i in range(seg):  # วนทีละด้านของท่อ
        a0, a1 = 2 * math.pi * i / seg, 2 * math.pi * (i + 1) / seg  # มุมเริ่มและมุมจบของด้านนี้
        am = (a0 + a1) / 2  # มุมตรงกลางของด้านนี้
        n = (math.cos(am) * u[0] + math.sin(am) * v[0], math.cos(am) * u[1] + math.sin(am) * v[1],  # ทิศที่ผิวด้านนี้หันไป (ส่วน x และ y)
             math.cos(am) * u[2] + math.sin(am) * v[2])  # ทิศที่ผิวด้านนี้หันไป (ส่วน z)
        sh = 0.55 + 0.45 * max(0.0, n[0] * LIGHT_DIR[0] + n[1] * LIGHT_DIR[1] + n[2] * LIGHT_DIR[2])  # ความสว่าง ยิ่งหันเข้าหาแสงยิ่งสว่าง
        glColor3f(c[0] * sh, c[1] * sh, c[2] * sh)  # เลือกสีของด้านนี้
        for (a, p) in ((a0, p0), (a1, p0), (a1, p1), (a0, p1)):  # วนทั้ง 4 มุมของแผ่น (สองมุมที่ปลายเริ่ม สองมุมที่ปลายจบ)
            ca, sa = math.cos(a), math.sin(a)  # ค่า cos และ sin ของมุมนี้
            glVertex3f(p[0] + r * (ca * u[0] + sa * v[0]),  # ตำแหน่งแกน x ของมุม
                       p[1] + r * (ca * u[1] + sa * v[1]),  # ตำแหน่งแกน y ของมุม
                       p[2] + r * (ca * u[2] + sa * v[2]))  # ตำแหน่งแกน z ของมุม
    glEnd()  # วาดท่อเสร็จ
 
 
def dome_para(cx, cz, d=0.762, h=0.42, ribs=True, seg=16, rings=14, solid=True):  # สร้างสูตรวาดซอฟต์บ็อกซ์ทรงโดมกลม (เส้นผ่านศูนย์กลาง d สูง h)
    """ซอฟต์บ็อกซ์ทรงโดมกลม (ครึ่งวงรี) Ø d  สูง h  วางคว่ำหน้าลงพื้น speed ring อยู่ด้านบน
    ปรับให้กลมขึ้น: h ยิ่งใกล้ d/2 ยิ่งเป็นครึ่งทรงกลม (ค่าเดิม 0.635 สูงและแหลมกว่า)
    ribs=True = ซี่สีขาว (แบบ Nanlite)  ribs=False = ซี่สีดำเหมือนผ้า"""
    r = d / 2  # รัศมี = ครึ่งหนึ่งของเส้นผ่านศูนย์กลาง
    th_top = math.acos(min(0.99, 0.085 / r))          # ตัดยอดตรงขนาด speed ring  # มุมที่ตัดยอดโดมทิ้ง ให้เหลือขนาดเท่าวงแหวนด้านบน
    if solid:  # ถ้าต้องเดินชนได้
        COLLIDERS.append((cx - r, cz - r, cx + r, cz + r))  # จดพื้นที่ของโดมลงสมุดสิ่งกีดขวาง
    body = (0.045, 0.045, 0.05)  # สีผ้าดำของโดม
    rib = (0.90, 0.90, 0.92) if ribs else (0.15, 0.15, 0.16)  # สีซี่: ขาวถ้า ribs เป็น True ไม่งั้นเป็นดำ
    delta = 0.03  # ความกว้างของซี่ (หน่วยมุม)
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยมบนผิวโดม
    for k in range(rings):  # วนทีละวงจากขอบขึ้นยอด
        ta, tb = th_top * k / rings, th_top * (k + 1) / rings  # มุมเงยของขอบล่างและขอบบนของวงนี้
        rha, rhb = r * math.cos(ta), r * math.cos(tb)  # รัศมีแนวราบของขอบล่างและขอบบน
        ya, yb = h * math.sin(ta), h * math.sin(tb)  # ความสูงของขอบล่างและขอบบน
        tm = (ta + tb) / 2  # มุมตรงกลางของวงนี้
        nx, ny = math.cos(tm) / r, math.sin(tm) / h   # เวกเตอร์ตั้งฉากของวงรี  # ทิศที่ผิวหันไป (ตามสูตรวงรี)
        nl = math.hypot(nx, ny)  # ความยาวของทิศนั้น
        nh, nv = nx / nl, ny / nl  # ทำให้ยาว 1: แนวราบ (nh) และแนวตั้ง (nv)
        for i in range(seg):  # วนทีละช่วงรอบโดม
            a0, a1 = 2 * math.pi * i / seg, 2 * math.pi * (i + 1) / seg  # มุมเริ่มและมุมจบของช่วงนี้
            for (col, p, q) in ((body, a0 + delta, a1 - delta), (rib, a1 - delta, a1 + delta)):  # วาด 2 ชิ้นต่อช่วง: ผ้าดำ และซี่คั่น
                am = (p + q) / 2  # มุมตรงกลางของชิ้นนี้
                sh = 0.50 + 0.50 * max(0.0, 0.35 * nh * math.cos(am) + 0.8 * nv + 0.45 * nh * math.sin(am))  # ความสว่างตามทิศที่ผิวหัน
                glColor3f(col[0] * sh, col[1] * sh, col[2] * sh)  # เลือกสีชิ้นนี้
                for (aa, rho, yy) in ((p, rha, ya), (q, rha, ya), (q, rhb, yb), (p, rhb, yb)):  # วนทั้ง 4 มุมของชิ้น
                    glVertex3f(cx + rho * math.cos(aa), yy, cz + rho * math.sin(aa))  # ใส่ตำแหน่งมุมนั้น
    glEnd()  # วาดผิวโดมเสร็จ
    y_top = h * math.sin(th_top)  # ความสูงที่ยอดโดมที่ถูกตัด
    cylinder(cx, y_top - 0.01, cz, 0.09, 0.035, (0.68, 0.70, 0.73), 16)     # วงแหวน speed ring  # วาดวงแหวนโลหะสีเทาที่ยอด
    cylinder(cx, y_top + 0.022, cz, 0.062, 0.010, (0.05, 0.05, 0.06), 16)   # ช่องกลางสีดำ  # วาดช่องกลางสีดำบนวงแหวน


def softbox_rect(cx, cz, yaw, w=0.991, d=0.686, h=0.457, solid=True):  # สร้างสูตรวาดซอฟต์บ็อกซ์สี่เหลี่ยม (ตำแหน่ง มุมหมุน กว้าง ลึก สูง)
    """ซอฟต์บ็อกซ์สี่เหลี่ยม (Godox) หน้าเปิด 39 x 27 inch ลึก 18 inch วางคว่ำหน้าลงพื้น
    ด้านยาว (w) ขนานแกน X ก่อนหมุน  yaw = หมุนรอบแกนตั้ง (องศา)"""
    a = 0.085  # ครึ่งหนึ่งของด้านสี่เหลี่ยมเล็กที่ยอด (ตรงที่ติดกับตัวยึดไฟ)
    B = [(-w / 2, 0, -d / 2), (w / 2, 0, -d / 2), (w / 2, 0, d / 2), (-w / 2, 0, d / 2)]  # มุมทั้ง 4 ของฐานใหญ่ (ที่ติดพื้น) นับจากจุดกึ่งกลาง
    T = [(-a, h, -a), (a, h, -a), (a, h, a), (-a, h, a)]  # มุมทั้ง 4 ของยอดเล็ก (ที่อยู่สูงจากพื้น h)
    if solid:  # ถ้าต้องเดินชนได้
        th = math.radians(yaw)  # แปลงมุมหมุนจากองศาเป็นเรเดียน
        cs, sn = math.cos(th), math.sin(th)  # ค่า cos และ sin ของมุมหมุน (ใช้คำนวณการหมุน)
        xs = [cx + p[0] * cs + p[2] * sn for p in B]  # ตำแหน่งแกน x ของมุมฐานทั้ง 4 หลังหมุนแล้ว
        zs = [cz - p[0] * sn + p[2] * cs for p in B]  # ตำแหน่งแกน z ของมุมฐานทั้ง 4 หลังหมุนแล้ว
        COLLIDERS.append((min(xs), min(zs), max(xs), max(zs)))  # จดสี่เหลี่ยมที่ครอบรอยฐานไว้ในสมุดสิ่งกีดขวาง
    glPushMatrix()  # เซฟตำแหน่งและมุมปัจจุบันไว้ก่อน
    glTranslatef(cx, 0, cz)  # ย้ายจุดอ้างอิงไปที่ตำแหน่งวางซอฟต์บ็อกซ์
    glRotatef(yaw, 0, 1, 0)  # หมุนรอบแกนตั้งตามมุมที่กำหนด
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม
    for i in range(4):  # วนทีละด้านข้างของซอฟต์บ็อกซ์ (มี 4 ด้าน)
        j = (i + 1) % 4  # มุมถัดไป (มุมสุดท้ายวนกลับไปมุมแรก)
        e1 = (B[j][0] - B[i][0], B[j][1] - B[i][1], B[j][2] - B[i][2])  # เส้นตามขอบฐานของด้านนี้
        e2 = (T[i][0] - B[i][0], T[i][1] - B[i][1], T[i][2] - B[i][2])  # เส้นเอียงจากฐานขึ้นไปยอด
        n = (e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2], e1[0] * e2[1] - e1[1] * e2[0])  # หาทิศที่ผิวด้านนี้หันไป (cross product ของเส้นสองเส้นข้างบน)
        mx = (B[i][0] + B[j][0]) / 2  # จุดกึ่งกลางของขอบฐาน (แกน x)
        mz = (B[i][2] + B[j][2]) / 2  # จุดกึ่งกลางของขอบฐาน (แกน z)
        if n[0] * mx + n[2] * mz < 0:  # ตรวจว่าทิศนี้หันเข้าด้านในหรือเปล่า
            n = (-n[0], -n[1], -n[2])  # ถ้าหันเข้าด้านใน กลับทิศให้หันออกนอก
        nl = math.sqrt(n[0] ** 2 + n[1] ** 2 + n[2] ** 2) or 1.0  # ความยาวของทิศ (กันไม่ให้เป็นศูนย์)
        sh = 0.55 + 0.45 * max(0.0, (n[0] * LIGHT_DIR[0] + n[1] * LIGHT_DIR[1] + n[2] * LIGHT_DIR[2]) / nl)  # ความสว่าง ยิ่งผิวหันเข้าหาแสงสมมติยิ่งสว่าง ต่ำสุด 55%
        glColor3f(0.10 * sh, 0.10 * sh, 0.11 * sh)  # เลือกสีผ้าดำ คูณด้วยความสว่าง
        glVertex3f(*B[i]); glVertex3f(*B[j]); glVertex3f(*T[j]); glVertex3f(*T[i])  # วาดด้านข้างโดยใช้ 4 มุม (ฐานสองมุม ยอดสองมุม) เครื่องหมาย * คือกระจายตัวเลข 3 ค่าออกมาใช้
    glColor3f(0.08, 0.08, 0.09)  # เลือกสีดำสำหรับฝาด้านบน
    for p in T:  # วนทั้ง 4 มุมของยอด
        glVertex3f(*p)  # ใส่เป็นมุมของฝาบน
    glEnd()  # วาดผิวเสร็จ
    white = (0.90, 0.90, 0.92)                                                 # ขอบผ้าสีขาวรอบหน้าเปิด  # สีขาวของขอบ
    box(-w / 2, 0, -d / 2, w / 2, 0.025, -d / 2 + 0.02, white)  # ขอบขาวแถบที่ 1 (ด้านเหนือ)
    box(-w / 2, 0, d / 2 - 0.02, w / 2, 0.025, d / 2, white)  # ขอบขาวแถบที่ 2 (ด้านใต้)
    box(-w / 2, 0, -d / 2, -w / 2 + 0.02, 0.025, d / 2, white)  # ขอบขาวแถบที่ 3 (ด้านตะวันตก)
    box(w / 2 - 0.02, 0, -d / 2, w / 2, 0.025, d / 2, white)  # ขอบขาวแถบที่ 4 (ด้านตะวันออก)
    cylinder(0, h - 0.005, 0, 0.075, 0.035, (0.68, 0.70, 0.73), 16)           # speed ring  # วงแหวนโลหะสีเทาที่ยอด (ตัวยึดกับขาไฟ)
    cylinder(0, h + 0.022, 0, 0.050, 0.010, (0.05, 0.05, 0.06), 16)  # ช่องกลางสีดำบนวงแหวน
    glPopMatrix()  # กลับไปยังตำแหน่งที่เซฟไว้ เพื่อไม่ให้กระทบสิ่งอื่นที่จะวาดต่อ


def c_stand(cx, cz, hub_h, yaw0=0):  # สร้างสูตรวาดขาตั้งไฟ C-stand (ตำแหน่ง ความสูงของฮับขา มุมเริ่มของขา)
    """C-stand ตามสเปคในรูป: สูง 150 cm เสา Ø35 -> Ø30 -> Ø25 mm ปลอกยางดำ
    ขา Ø25 mm 3 ขา ห่าง 120° กางรวม ~74 cm  ขาโค้งลงถึงพื้น  hub_h = ความสูงของฮับขา"""
    steel, dark = STEEL, (0.06, 0.06, 0.07)  # ตั้งชื่อสีเหล็กกับสีดำที่ใช้ซ้ำ
    cylinder(cx, hub_h - 0.05, cz, 0.0175, 1.035 - (hub_h - 0.05), steel, 12)   # Ø35 mm  # เสาท่อนล่างสุด (ใหญ่สุด) จากฮับขึ้นไปถึง 1.035 เมตร
    cylinder(cx, 1.035, cz, 0.0195, 0.123, dark, 12)                             # ปลอกยางดำ  # ปลอกยางสีดำคาดตรงกลางเสา
    cylinder(cx, 1.158, cz, 0.0150, 0.162, steel, 12)                            # Ø30 mm  # เสาท่อนกลาง (เล็กลง)
    cylinder(cx, 1.320, cz, 0.0125, 0.140, steel, 12)                            # Ø25 mm  # เสาท่อนบน (เล็กสุด)
    cylinder(cx, 1.460, cz, 0.0080, 0.040, steel, 10)                            # หัวสตัดบนสุด (รวมสูง 1.50 m)  # หัวเสาเล็ก ๆ บนสุด รวมความสูง 1.50 เมตร
    cylinder(cx, 1.150, cz, 0.0185, 0.015, steel, 12)                            # ปลอกต่อท่อ  # ข้อต่อระหว่างท่อนล่างกับท่อนกลาง
    cylinder(cx, 1.312, cz, 0.0165, 0.015, steel, 12)  # ข้อต่อระหว่างท่อนกลางกับท่อนบน
    cylinder(cx, hub_h - 0.04, cz, 0.030, 0.08, steel, 12)                       # ฮับขา  # ตัวฮับ (จุดที่ขาทั้ง 3 ข้างต่อเข้ามา)
    cylinder(cx + 0.035, hub_h - 0.015, cz, 0.012, 0.035, dark, 8)               # น็อบล็อก  # ลูกบิดสีดำสำหรับขันล็อก
    for k in range(3):  # วนทำขา 3 ขา
        a = math.radians(yaw0 + 120 * k)  # มุมของขาแต่ละขา ห่างกัน 120 องศา แล้วแปลงเป็นเรเดียน
        ux, uz = math.cos(a), -math.sin(a)  # ทิศที่ขานี้ยื่นออกไปบนพื้น
        p0 = (cx, hub_h, cz)  # จุดเริ่มของขา: ที่ฮับ
        p1 = (cx + 0.28 * ux, hub_h, cz + 0.28 * uz)           # แขนแนวนอน 28 cm  # จุดปลายแขนแนวนอน (ห่างจากฮับ 28 ซม.)
        p2 = (cx + 0.43 * ux, 0.02, cz + 0.43 * uz)            # ปลายขาลาดลงพื้น (รัศมี 43 cm)  # จุดปลายขาที่ลาดลงถึงพื้น (ห่างจากฮับ 43 ซม.)
        tube(p0, p1, 0.0125, steel, 8)  # วาดท่อแนวนอนจากฮับไปจุดข้อศอก
        ball(p1[0], p1[1], p1[2], 0.0125, steel, 8, 6)  # วาดลูกบอลที่ข้อศอกเพื่อปิดรอยต่อให้ดูเรียบ
        tube(p1, p2, 0.0125, steel, 8)  # วาดท่อลาดลงจากข้อศอกไปถึงพื้น
        cylinder(p2[0], 0.0, p2[2], 0.0145, 0.04, dark, 8)     # ยางรองขา  # วาดยางสีดำรองปลายขา


def tquad(tex, pts, uvs, tint=(1, 1, 1)):  # สร้างสูตรวาดสี่เหลี่ยมที่แปะรูปลาย (เท็กซ์เจอร์) รับรูป จุดมุม ตำแหน่งในรูป และสีเคลือบ
    glEnable(GL_TEXTURE_2D)  # เปิดโหมดแปะรูปลาย
    glBindTexture(GL_TEXTURE_2D, tex)  # เลือกรูปลายที่จะใช้
    glColor3f(*tint)  # ตั้งสีเคลือบทับรูป (1,1,1 = ไม่เปลี่ยนสี ค่าน้อยกว่า = มืดลง)
    glBegin(GL_QUADS)  # เริ่มวาดสี่เหลี่ยม
    for p, uv in zip(pts, uvs):  # วนทีละมุม โดยจับคู่ตำแหน่งในห้องกับตำแหน่งในรูป
        glTexCoord2f(*uv)  # บอกว่ามุมนี้ตรงกับจุดไหนของรูปลาย
        glVertex3f(*p)  # บอกตำแหน่งของมุมนี้ในห้อง
    glEnd()  # วาดเสร็จ
    glDisable(GL_TEXTURE_2D)  # ปิดโหมดแปะรูปลาย เพื่อไม่ให้กระทบสิ่งอื่นที่จะวาดต่อ


def gquad(pts, cols):  # สร้างสูตรวาดสี่เหลี่ยมที่แต่ละมุมสีไม่เท่ากัน (ฟังก์ชันที่แอร์ในไฟล์ก่อนหน้าเรียกใช้)
    """สี่เหลี่ยมไล่สีที่แต่ละมุม (ใช้ทำท้องฟ้านอกหน้าต่าง)"""
    glBegin(GL_QUADS)  # เริ่มวาดสี่เหลี่ยม
    for p, c in zip(pts, cols):  # วนทีละมุม จับคู่ตำแหน่งกับสี
        glColor3f(*c)  # ตั้งสีของมุมนี้
        glVertex3f(*p)  # ตั้งตำแหน่งของมุมนี้ (การ์ดจอจะไล่สีระหว่างมุมให้เอง)
    glEnd()  # วาดเสร็จ


# ---------- กระจกใสของหน้าต่าง (เพิ่มใหม่) ----------
GLASS_QUADS = []  # สมุดจดแผ่นกระจกใสทั้งหมด (แต่ละแผ่นคือรายการมุม 4 จุด) เอาไว้วาดทีเดียวตอนท้ายสุด เพราะของโปร่งใสต้องวาดหลังของทึบทุกอย่าง
WINDOW_GLASS_ALPHA = 0.14  # ความทึบของกระจกหน้าต่าง (0 = ใสสนิทมองไม่เห็นกระจก, 1 = ทึบ) ยิ่งน้อยยิ่งใส ปรับตรงนี้ได้
WINDOW_GLASS_TINT = (0.70, 0.86, 0.92)  # สีเคลือบของกระจก (ฟ้าอ่อนจางๆ) ตัวเลข 3 ค่า = แดง เขียว น้ำเงิน ช่วง 0-1


def glass_quad(pts):  # ประกาศสูตร "จดแผ่นกระจกใส" รับมุม 4 จุดของแผ่นกระจก
    """ไม่วาดทันที แค่จดไว้ในสมุด GLASS_QUADS แล้ว draw_window_glass() จะวาดให้ทีเดียวหลังสุด"""  # คำอธิบาย: ถ้าวาดทันที ของที่วาดทีหลังจะทับกระจกจนกลายเป็นกระจกทึบ
    GLASS_QUADS.append(pts)  # เอาแผ่นกระจกนี้ไปต่อท้ายสมุดจด


def draw_window_glass():  # ประกาศสูตร "วาดกระจกหน้าต่างทั้งหมดแบบโปร่งใส" (เรียกครั้งเดียวตอนท้ายของ build_scene)
    glDepthMask(GL_FALSE)  # ปิดการจดความลึก เพื่อให้กระจกไม่บังของที่อยู่ข้างหลังมัน
    glEnable(GL_BLEND)  # เปิดโหมดผสมสี (ทำให้โปร่งใสได้)
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)  # ตั้งสูตรผสมสีแบบโปร่งใสมาตรฐาน
    glColor4f(WINDOW_GLASS_TINT[0], WINDOW_GLASS_TINT[1], WINDOW_GLASS_TINT[2], WINDOW_GLASS_ALPHA)  # เลือกสีกระจก พร้อมค่าความทึบเป็นตัวที่สี่
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม
    for pts in GLASS_QUADS:  # วนทีละแผ่นกระจกที่จดไว้ในสมุด
        for p in pts:  # วนทีละมุมของแผ่นนั้น
            glVertex3f(*p)  # ปักมุมนั้นลงไป (เครื่องหมาย * คือกระจายเลข 3 ค่า x y z ออกมาใช้)
    glEnd()  # จบการวาดแผ่นกระจกทั้งหมด
    glDisable(GL_BLEND)  # ปิดโหมดผสมสี คืนค่าเดิม
    glDepthMask(GL_TRUE)  # เปิดการจดความลึกกลับคืน


def wall_pieces(x0, x1, y0, y1, holes):  # ประกาศสูตร "ตัดผนังเป็นชิ้นสี่เหลี่ยม โดยเว้นช่องเจาะ" รับขอบผนัง (ซ้าย ขวา ล่าง บน) และรายการช่องเจาะ
    """คืนรายการ (xa, xb, ya, yb) ของชิ้นผนังทึบ ที่เหลือหลังเจาะช่อง holes (แต่ละช่อง = (x ซ้าย, x ขวา, y ล่าง, y บน))
    ใช้ทำให้กระจกหน้าต่างใสได้จริง เพราะต้องมีช่องทะลุที่ผนัง ไม่งั้นมองทะลุกระจกก็เจอผนังทึบ"""  # คำอธิบาย: ผนังที่ไม่มีรูจะทำให้กระจกใสแค่ไหนก็มองไม่เห็นอีกฝั่ง
    ys = sorted({y0, y1} | {v for h in holes for v in (h[2], h[3])})  # รวบรวมระดับความสูงที่เป็นขอบของช่องเจาะทุกช่อง แล้วเรียงจากต่ำไปสูง ใช้แบ่งผนังเป็นแถบแนวนอน
    pieces = []  # รายการชิ้นผนังที่จะส่งคืน เริ่มต้นว่างเปล่า
    for ya, yb in zip(ys[:-1], ys[1:]):  # วนทีละแถบแนวนอน (จับคู่ระดับที่ติดกัน)
        cuts = sorted((h[0], h[1]) for h in holes if h[2] <= ya and h[3] >= yb)  # หาช่องเจาะที่ทะลุผ่านแถบนี้ทั้งแถบ แล้วเรียงจากซ้ายไปขวา
        cur = x0  # ตัวนับตำแหน่งแนวนอน เริ่มที่ขอบซ้ายของผนัง
        for (ca, cb) in cuts:  # วนทีละช่องเจาะในแถบนี้
            if ca > cur:  # ถ้าก่อนถึงช่องเจาะยังมีผนังทึบเหลืออยู่
                pieces.append((cur, ca, ya, yb))  # เก็บชิ้นผนังทึบช่วงนั้นไว้
            cur = max(cur, cb)  # ข้ามช่องเจาะ ขยับตัวนับไปที่ขอบขวาของช่อง
        if cur < x1:  # ถ้าหลังช่องเจาะสุดท้ายยังมีผนังทึบเหลือถึงขอบขวา
            pieces.append((cur, x1, ya, yb))  # เก็บชิ้นผนังช่วงท้ายไว้
    return pieces  # ส่งรายการชิ้นผนังกลับไปให้ผู้เรียก


# =====================================================================
# 3) สร้างเท็กซ์เจอร์ด้วยโค้ด (ไม่ต้องใช้ไฟล์รูป)
# =====================================================================
def upload_texture(arr):  # สร้างสูตรส่งรูปลาย (ตารางตัวเลข) ไปให้การ์ดจอเก็บไว้
    h, w, _ = arr.shape  # อ่านความสูงและความกว้างของรูป (ตัวแปรสุดท้ายคือจำนวนสี ไม่ได้ใช้)
    tid = glGenTextures(1)  # ขอหมายเลขช่องเก็บรูปจากการ์ดจอ 1 ช่อง
    glBindTexture(GL_TEXTURE_2D, tid)  # เลือกช่องนั้นเป็นช่องที่กำลังทำงาน
    glPixelStorei(GL_UNPACK_ALIGNMENT, 1)  # บอกการ์ดจอว่าข้อมูลรูปเรียงแบบไม่มีช่องว่างคั่น
    gluBuild2DMipmaps(GL_TEXTURE_2D, GL_RGB, w, h, GL_RGB, GL_UNSIGNED_BYTE, arr.tobytes())  # ส่งรูปให้การ์ดจอ พร้อมสร้างรูปย่อหลายขนาด (ไว้ใช้ตอนมองไกล ภาพจะได้ไม่เป็นเม็ด)
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_REPEAT)  # ถ้าลายถูกใช้เกินแนวนอน ให้เรียงซ้ำต่อกันไป
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_REPEAT)  # ถ้าลายถูกใช้เกินแนวตั้ง ให้เรียงซ้ำต่อกันไป
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR_MIPMAP_LINEAR)  # ตอนมองไกล (รูปถูกย่อ) ให้ผสมสีให้เนียน
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR)  # ตอนมองใกล้ (รูปถูกขยาย) ให้ผสมสีให้เนียน
    return tid  # ส่งหมายเลขช่องเก็บรูปกลับไป เพื่อเอาไปใช้แปะภายหลัง


def tex_floor():  # สร้างสูตรทำลายพื้นไม้
    """พื้นลายไม้ 1 แผ่น = 0.15 m  ภาพหนึ่งใบ = 1.2 m x 1.2 m"""
    s, n = 512, 8  # ขนาดรูป 512 x 512 จุด และมีไม้ปูพื้น 8 แถบ
    rng = np.random.default_rng(1)  # ตัวสุ่มตัวเลข (ใส่เลข 1 เพื่อให้ได้ผลสุ่มเหมือนเดิมทุกครั้ง)
    img = np.zeros((s, s, 3))  # สร้างรูปเปล่า สีดำทั้งภาพ (ตาราง s x s จุด จุดละ 3 สี)
    pw = s // n  # ความกว้างของไม้แต่ละแถบ (จำนวนจุด)
    base = np.array([0.80, 0.74, 0.66])  # สีไม้พื้นฐาน (น้ำตาลอ่อน)
    for i in range(n):  # วนทีละแถบไม้
        j = int(rng.integers(80, 430))  # สุ่มตำแหน่งรอยต่อของแผ่นไม้ในแถบนี้
        for ya, yb in ((0, j), (j, s)):  # วนทีละท่อนไม้ (ท่อนบนก่อนรอยต่อ และท่อนล่างหลังรอยต่อ)
            img[ya:yb, i * pw:(i + 1) * pw] = base * (1 + rng.uniform(-0.06, 0.06))  # ทาสีไม้ท่อนนี้ โดยสุ่มให้เข้มหรืออ่อนกว่าฐานเล็กน้อย (±6%)
        img[:, i * pw:i * pw + 2] *= 0.80  # ทำให้ขอบซ้ายของแถบมืดลง 20% เป็นเส้นร่องระหว่างแถบ
        img[j - 1:j + 1, i * pw:(i + 1) * pw] *= 0.80  # ทำให้เส้นรอยต่อของท่อนไม้มืดลง 20%
    img += rng.normal(0, 0.012, (s, s, 1))  # โรยจุดสุ่มละเอียดทั้งภาพ ให้พื้นดูเป็นเนื้อไม้ ไม่เรียบเกินไป
    return (np.clip(img, 0, 1) * 255).astype(np.uint8)  # จำกัดค่าให้อยู่ในช่วง 0-1 แล้วแปลงเป็นเลข 0-255 (รูปแบบที่การ์ดจอต้องการ)


def tex_wall():  # สร้างสูตรทำลายผนัง
    """ผนังสีเทา แบ่งแผ่นทุก 1.2 m"""
    s = 256  # ขนาดรูป 256 x 256 จุด
    rng = np.random.default_rng(2)  # ตัวสุ่ม (เลข 2 = ผลเหมือนเดิมทุกครั้ง)
    img = np.ones((s, s, 3)) * np.array(WALL_GREY)  # สร้างรูปที่ทุกจุดเป็นสีเทาผนัง
    img += rng.normal(0, 0.01, (s, s, 1))  # โรยจุดสุ่มจาง ๆ ให้ผนังดูมีเนื้อ
    img[:, :2] *= 0.78  # ทำแถบมืดที่ขอบซ้าย 2 จุด เป็นรอยต่อแผ่นผนัง
    img[:2, :] *= 0.78  # ทำแถบมืดที่ขอบบน 2 จุด เป็นรอยต่อแผ่นผนัง
    return (np.clip(img, 0, 1) * 255).astype(np.uint8)  # จำกัดค่าแล้วแปลงเป็นเลข 0-255


def tex_ceiling():  # สร้างสูตรทำลายฝ้าเพดาน
    """ฝ้าแผ่นดำ 0.6 x 0.6 m"""
    s = 128  # ขนาดรูป 128 x 128 จุด
    rng = np.random.default_rng(3)  # ตัวสุ่ม (เลข 3 = ผลเหมือนเดิมทุกครั้ง)
    img = np.ones((s, s, 3)) * np.array([0.12, 0.12, 0.13])  # สร้างรูปที่ทุกจุดเป็นสีดำเทา
    img += rng.normal(0, 0.02, (s, s, 1))  # โรยจุดสุ่มให้ฝ้าดูมีผิวสัมผัส
    img[:, :3] *= 0.45  # ทำแถบมืดที่ขอบซ้าย เป็นร่องระหว่างแผ่นฝ้า
    img[:3, :] *= 0.45  # ทำแถบมืดที่ขอบบน เป็นร่องระหว่างแผ่นฝ้า
    return (np.clip(img, 0, 1) * 255).astype(np.uint8)  # จำกัดค่าแล้วแปลงเป็นเลข 0-255


# =====================================================================
# 4) ตัวห้อง: พื้น เพดาน ผนัง คาน ไฟ แอร์
# =====================================================================
def room_shell(tex):  # สร้างสูตรวาดตัวห้อง (พื้น เพดาน ผนังทั้งสี่ด้าน และบัวขอบล่าง)
    floor, wall, ceil = tex  # แยกรูปลาย 3 ใบที่ส่งมาเป็น พื้น ผนัง เพดาน
    t = 1.2  # ขนาดจริงของรูปลาย 1 ใบ = 1.2 เมตร (ใช้คำนวณว่าต้องปูซ้ำกี่ใบ)
    tquad(floor, [(0, 0, 0), (W, 0, 0), (W, 0, D), (0, 0, D)],  # วาดพื้น: 4 มุมของพื้นห้อง (สูง 0)
          [(0, 0), (W / t, 0), (W / t, D / t), (0, D / t)])  # บอกว่าต้องปูรูปลายซ้ำเท่าไร ตามขนาดห้องหารขนาดรูป
    tquad(ceil, [(0, H, 0), (W, H, 0), (W, H, D), (0, H, D)],  # วาดเพดาน: 4 มุมของเพดาน (สูง H)
          [(0, 0), (W / 0.6, 0), (W / 0.6, D / 0.6), (0, D / 0.6)])  # ปูซ้ำตามขนาดแผ่นฝ้า 0.6 เมตร
    # ผนังเหนือ (หน้าต่าง) / ใต้ (ประตู) / ตะวันตก (ไวท์บอร์ด) / ตะวันออก (ผ้าม่าน)
    tquad(wall, [(0, 0, 0), (W, 0, 0), (W, H, 0), (0, H, 0)],  # วาดผนังเหนือ (ฝั่งหน้าต่าง)
          [(0, 0), (W / t, 0), (W / t, H / t), (0, H / t)], (0.95,) * 3)  # ปูลายซ้ำตามขนาด และเคลือบสี 95% (มืดลงนิดหน่อย)
    for (xa, xb, ya, yb) in wall_pieces(0, W, 0.0, H, WALL_HOLES):  # ผนังใต้ตัดเป็นหลายชิ้น เว้นช่องประตู ช่องแสงเหนือประตู และหน้าต่างแถบ (เจาะทะลุจริง กระจกจะได้ใสมองเห็นอีกฝั่ง)
        tquad(wall, [(xa, ya, D), (xb, ya, D), (xb, yb, D), (xa, yb, D)],  # วาดผนังใต้ชิ้นนี้ที่ระนาบ z = D
              [(xa / t, ya / t), (xb / t, ya / t), (xb / t, yb / t), (xa / t, yb / t)], (1.0,) * 3)  # ปูลายตามขนาดจริง ไม่เคลือบสี (ลายต่อเนื่องกันทุกชิ้น)
    tquad(wall, [(0, 0, 0), (0, 0, D), (0, H, D), (0, H, 0)],  # วาดผนังตะวันตก (ฝั่งไวท์บอร์ด)
          [(0, 0), (D / t, 0), (D / t, H / t), (0, H / t)], (0.85,) * 3)  # ปูลายซ้ำ เคลือบสี 85% (มืดกว่า เพื่อให้ผนังแต่ละด้านสว่างไม่เท่ากัน ดูมีมิติ)
    tquad(wall, [(W, 0, 0), (W, 0, D), (W, H, D), (W, H, 0)],  # วาดผนังตะวันออก (ฝั่งผ้าม่าน)
          [(0, 0), (D / t, 0), (D / t, H / t), (0, H / t)], (0.90,) * 3)  # ปูลายซ้ำ เคลือบสี 90%
    # ขอบล่าง (บัว) รอบห้อง สูง 9 cm ตามรูปหน้า 5
    skirt = (0.42, 0.44, 0.48)  # สีบัวขอบล่าง (เทาเข้มกว่าผนัง)
    box(0, 0, 0, W, 0.09, 0.02, skirt)  # บัวด้านเหนือ สูง 9 ซม. หนา 2 ซม.
    box(0, 0, D - 0.02, DOOR_A, 0.09, D, skirt)  # บัวด้านใต้ ท่อนซ้ายของประตู
    box(DOOR_B, 0, D - 0.02, W, 0.09, D, skirt)  # บัวด้านใต้ ท่อนขวาของประตู (เว้นช่องประตูไว้)
    box(0, 0, 0, 0.02, 0.09, D, skirt)  # บัวด้านตะวันตก
    box(W - 0.02, 0, 0, W, 0.09, D, skirt)  # บัวด้านตะวันออก


def ceiling_fixtures():  # สร้างสูตรวาดของที่ติดเพดาน (คาน หลอดไฟ สปอตไลท์ แอร์)
    # คานดำกลางห้อง กว้าง 37 cm ห้อยลงมา 75 cm (ก้นคานที่ 2.55 m)
    bw = 0.37  # ความกว้างคาน 37 เซนติเมตร
    box(W / 2 - bw / 2, H - BEAM_HANG, 0, W / 2 + bw / 2, H, D, (0.07, 0.07, 0.08))  # วาดคานดำกลางห้อง ยาวตลอดความยาวห้อง ห้อยลงจากเพดานตามค่า BEAM_HANG
    # หลอดไฟยาว 1.2 m กว้าง 20 cm  2 แถว ข้างคาน
    for x in (1.9, 5.85):  # วนสองแถว ตำแหน่งแกน x ของแต่ละแถว (ซ้ายและขวาของคาน)
        for k in range(5):  # วนแถวละ 5 หลอด
            z = 1.0 + k * 1.75  # ตำแหน่งตามความยาวห้อง เริ่มที่ 1 เมตร ห่างกันหลอดละ 1.75 เมตร
            box(x - 0.10, H - 0.07, z - 0.6, x + 0.10, H, z + 0.6, (0.95, 0.97, 1.0), flat=True)  # วาดหลอดไฟสีขาวอมฟ้า กว้าง 20 ซม. ยาว 1.2 เมตร (flat=True คือไม่ใส่เฉดสี ให้ดูสว่างเหมือนเปิดไฟ)
    # สปอตไลท์สีดำตามแนวคาน
    for x in (3.0, 4.75):  # วนสองแถว ข้างคานทั้งสองฝั่ง
        for k in range(4):  # วนแถวละ 4 ดวง
            cylinder(x, H - 0.16, 1.6 + k * 1.9, 0.05, 0.16, (0.05, 0.05, 0.05), 10)  # วาดสปอตไลท์เป็นกระบอกสีดำเล็ก ๆ ห้อยจากเพดาน ห่างกัน 1.9 เมตร
    # แอร์แขวนเพดาน 2 เครื่อง ขนาด 1.47 x 0.65 m
    for x in (1.75, 6.0):  # วนสองเครื่อง ตำแหน่งแกน x ของแต่ละเครื่อง
        aircon(x, 0.55, H - 0.40)  # วาดแอร์ (ใช้ฟังก์ชัน aircon ที่เขียนไว้) ห้อยลงจากเพดาน 40 ซม.
        for dx in (-0.6, 0.6):  # วนสองข้างของแอร์ (ซ้ายและขวา)
            cylinder(x + dx, H - 0.15, 0.88, 0.012, 0.15, STEEL, 6)  # วาดแท่งเหล็กเล็ก ๆ ที่ยึดแอร์ไว้กับเพดาน


def sky_glass(x0, x1, y0, y1, z, blind_bottom):  # สร้างสูตรวาดกระจกหน้าต่าง (รับขอบซ้ายขวา ขอบล่างบน ตำแหน่ง z และระดับที่ม่านม้วนห้อยลงมา)
    """กระจกหน้าต่าง: ท้องฟ้าด้านล่าง + ม่านม้วนสีเทาด้านบน"""
    gquad([(x0, y0, z), (x1, y0, z), (x1, blind_bottom, z), (x0, blind_bottom, z)],  # วาดส่วนท้องฟ้า: จากขอบล่างของกระจกขึ้นไปถึงชายม่าน
          [(0.58, 0.64, 0.60), (0.58, 0.64, 0.60), (0.80, 0.85, 0.90), (0.80, 0.85, 0.90)])  # สีของ 4 มุม: สองมุมล่างเขียวอมเทา (ต้นไม้ไกล ๆ) สองมุมบนฟ้าอ่อน แล้วการ์ดจอไล่สีให้เนียน
    gquad([(x0, blind_bottom, z), (x1, blind_bottom, z), (x1, y1, z), (x0, y1, z)],  # วาดส่วนม่านม้วน: จากชายม่านขึ้นไปถึงขอบบนของกระจก
          [(0.40, 0.41, 0.44)] * 4)  # ทุกมุมเป็นสีเทาเข้ม (เครื่องหมาย * 4 คือซ้ำสีเดิม 4 ครั้ง)


def window_wall():  # สร้างสูตรวาดผนังฝั่งหน้าต่าง (ผนังเหนือ)
    """ผนังเหนือ z=0: หน้าต่าง 2 ช่วง ช่วงละ 3.42 m  กระจกสูง 1.93 m ขอบล่าง 0.78 m"""
    sill, top = 0.78, 0.78 + 1.93  # ขอบล่างกระจกสูง 0.78 เมตร ขอบบนสูง 0.78 + 1.93 เมตร
    pier = (0.49, 0.51, 0.55)  # สีของเสาปูน (เทา)
    secs = [(0.255, 0.255 + 3.42), (W - 0.255 - 3.42, W - 0.255)]  # ตำแหน่งซ้าย-ขวาของหน้าต่างสองช่วง (ช่วงละ 3.42 เมตร เว้นขอบผนังไว้ 0.255 เมตร)
    for (a, b) in secs:  # วนทำหน้าต่างทีละช่วง (a = ขอบซ้าย, b = ขอบขวา)
        sky_glass(a, b, sill, top, 0.012, 1.55)  # วาดกระจก มีท้องฟ้าด้านล่างและม่านม้วนด้านบน (ม่านห้อยลงมาถึงความสูง 1.55 เมตร)
        n = 6  # แบ่งหน้าต่างเป็น 6 บาน
        for i in range(n + 1):             # เสากลางบานกระจก  # วนวางเสากั้นบาน (6 บานต้องมี 7 เสา รวมสองข้าง)
            x = a + (b - a) * i / n  # คำนวณตำแหน่งของเสาแต่ละต้น ให้ห่างเท่า ๆ กัน
            box(x - 0.02, sill, 0.0, x + 0.02, top, 0.06, (0.30, 0.32, 0.35))  # วาดเสากั้นบาน กว้าง 4 ซม. สีเทาเข้ม จากขอบล่างถึงขอบบนของกระจก
        box(a, top, 0.0, b, top + 0.04, 0.06, (0.30, 0.32, 0.35))  # วาดกรอบบนของหน้าต่าง หนา 4 ซม.
        box(a - 0.02, sill - 0.04, 0.0, b + 0.02, sill, 0.16, (0.86, 0.87, 0.88))   # ขอบหน้าต่าง  # วาดขอบหน้าต่างล่าง (ขอบที่ยื่นออกมาเป็นชั้นวางของเล็ก ๆ) สีขาว ยื่นเข้าห้อง 16 ซม.
    # เสากลาง 40 cm และเสามุม (ยื่นออกมาเล็กน้อย)
    box(W / 2 - 0.20, 0, 0, W / 2 + 0.20, H, 0.10, pier)  # วาดเสากลางผนัง กว้าง 40 ซม. สูงจากพื้นถึงเพดาน ยื่นเข้าห้อง 10 ซม.
    box(0, 0, 0, 0.255, H, 0.10, pier)  # วาดเสามุมซ้าย
    box(W - 0.255, 0, 0, W, H, 0.10, pier)  # วาดเสามุมขวา


def door_wall():  # สร้างสูตรวาดผนังฝั่งประตู (ผนังใต้)
    """ผนังใต้ z=D: ประตูกระจกบานคู่กว้าง 1.14 m สูง 2.0 m + ช่องแสงด้านบน + หน้าต่างแถบ"""
    z = D - 0.02  # ตำแหน่งระนาบที่วาดประตู (ห่างจากผนังเข้ามา 2 ซม. กันภาพทับกันจนกะพริบ)
    fr = (0.90, 0.90, 0.90)  # สีกรอบประตู (ขาวเทา)
    # หน้าต่างแถบ: บานละ 1.15 x 0.48 m ที่ความสูง 2.10 - 2.58 m
    for (a, b) in ((0.48, 2.78), (5.22, 7.52)):  # วนทำหน้าต่างแถบ 2 ชุด ซ้ายและขวาของประตู (ระบุขอบซ้าย-ขวาของแต่ละชุด)
        for i in range(3):  # วนวางเสากั้น 3 ต้น (ซ้าย กลาง ขวา)
            x = a + (b - a) * i / 2  # คำนวณตำแหน่งเสาให้ห่างเท่ากัน
            box(x - 0.025, 2.08, z - 0.03, x + 0.025, 2.60, D, (0.28, 0.30, 0.33))  # วาดเสากั้นสีเทาเข้ม สูงจาก 2.08 ถึง 2.60 เมตร
        box(a, 2.08, z - 0.03, b, 2.12, D, (0.28, 0.30, 0.33))  # วาดกรอบล่างของหน้าต่างแถบ
        box(a, 2.56, z - 0.03, b, 2.60, D, (0.28, 0.30, 0.33))  # วาดกรอบบนของหน้าต่างแถบ
    # ฝาผนังกระจกประตู
    ga, gb = 2.85, 4.93  # ขอบซ้ายและขอบขวาของส่วนกระจกประตูใหญ่
    for x in (ga, gb):  # วนวางเสากรอบข้างประตู 2 ต้น (ขอบซ้าย ขอบขวา) ส่วนเสากลางเอาออกเพื่อให้เดินผ่านได้
        box(x - 0.025, 0, z - 0.04, x + 0.025, 2.60, D, fr)  # วาดเสากรอบสีขาวเทา กว้าง 5 ซม. จากพื้นถึง 2.60 เมตร
    for x in (3.32, W / 2, 4.46):  # วนวางเสากั้นเฉพาะช่องแสงด้านบน 3 ต้น
        box(x - 0.025, DOOR_OPEN_H, z - 0.04, x + 0.025, 2.60, D, fr)  # วาดเสาสั้น ๆ จากคานประตูถึง 2.60 เมตร
    box(ga, DOOR_OPEN_H, z - 0.04, gb, DOOR_OPEN_H + 0.05, D, fr)  # วาดคานกรอบที่ความสูง 2.0 เมตร (เป็นเส้นแบ่งระหว่างบานประตูกับช่องแสงด้านบน)
    box(ga, 2.56, z - 0.04, gb, 2.60, D, fr)  # วาดกรอบบนสุดของกระจกประตู
    # ราวม่าน + ม่านสองข้าง (รวบไปอยู่ข้างประตู ไม่บังช่องทางเดิน)
    box(2.20, 2.0, z - 0.08, 5.58, 2.03, z - 0.05, STEEL)  # วาดราวแขวนม่านเป็นแท่งเหล็กบาง ๆ ยาวคลุมสองข้างประตู
    for (a, b) in ((2.23, DOOR_A - 0.03), (DOOR_B + 0.03, 5.55)):  # วนทำม่านสองผืนที่รวบอยู่ข้างซ้ายและข้างขวาของประตู
        n = 6  # แบ่งม่านแต่ละผืนเป็น 6 ริ้ว (ให้เป็นลอนผ้า)
        for i in range(n):  # วนทำทีละริ้ว
            x0 = a + (b - a) * i / n  # ขอบซ้ายของริ้วนี้
            x1 = a + (b - a) * (i + 1) / n  # ขอบขวาของริ้วนี้
            s = 1.0 if i % 2 == 0 else 0.82  # ริ้วเลขคู่สีปกติ ริ้วเลขคี่มืดลง 18% ให้เห็นเป็นลอน
            d = 0.10 if i % 2 == 0 else 0.07  # ริ้วเลขคู่ยื่นออกมา 10 ซม. ริ้วเลขคี่ยื่น 7 ซม. (ทำให้เป็นสันและร่อง)
            box(x0, 0.03, z - d, x1, 2.0, z - 0.04, tuple(v * s for v in CURTAIN))  # วาดริ้วม่าน จากพื้นถึงราว โดยปรับสีตามค่า s


def east_wall():  # สร้างสูตรวาดผนังฝั่งตะวันออก (ผ้าม่านยาวตลอดผนัง)
    """ผนังตะวันออก: ม่านยาวตลอดผนัง สูง 2.36 m + แถบเหนือม่านสูง 16 cm"""
    n = 60  # แบ่งม่านเป็น 60 ริ้วตลอดความยาวห้อง
    for i in range(n):  # วนทำทีละริ้ว
        z0 = D * i / n  # ตำแหน่งเริ่มของริ้วนี้ตามความยาวห้อง
        z1 = D * (i + 1) / n  # ตำแหน่งจบของริ้วนี้
        s = 1.0 if i % 2 == 0 else 0.80  # ริ้วเลขคู่สีปกติ ริ้วเลขคี่มืดลง 20% (ให้เป็นลอน)
        d = 0.14 if i % 2 == 0 else 0.09  # ริ้วเลขคู่ยื่นออกมา 14 ซม. ริ้วเลขคี่ยื่น 9 ซม.
        box(W - d, 0.03, z0, W - 0.02, 2.36, z1, tuple(v * s for v in CURTAIN))  # วาดริ้วม่านสูง 2.36 เมตร ปรับสีตามค่า s
    box(W - 0.12, 2.36, 0, W - 0.02, 2.52, D, (0.30, 0.32, 0.35))  # วาดแถบเทาเข้มเหนือม่าน (กล่องบังราว) สูง 16 ซม. ยาวตลอดผนัง
    box(W - 0.05, 2.34, 0, W - 0.02, 2.36, D, STEEL)  # วาดราวเหล็กบาง ๆ ที่ขอบบนของม่าน


def west_wall():  # สร้างสูตรวาดผนังฝั่งตะวันตก (ไวท์บอร์ด)
    """ผนังตะวันตก: ไวท์บอร์ด ยาว 4.8 m สูง 47.5 inch (1.21 m) ขอบล่าง ~1.05 m
    ตามรูปจริง: กรอบน้ำตาลเข้ม แบ่ง 2 แผง ขายึดใต้ถาด ถาดมีขอบกั้น แจกันดอกไม้ ปากกา
    กล่องกระดาษวางบนกรอบ และรอยเขียนจางๆ บนบอร์ด"""
    z0, z1 = 2.3, 7.1  # ปลายทั้งสองข้างของไวท์บอร์ดตามความยาวห้อง (ยาว 4.8 เมตร)
    zm = (z0 + z1) / 2  # จุดกึ่งกลางของบอร์ด (ตรงรอยต่อสองแผง)
    y0 = 1.05  # ขอบล่างของบอร์ดสูงจากพื้น 1.05 เมตร
    y1 = y0 + 47.5 * INCH  # ขอบบนของบอร์ด (สูง 47.5 นิ้ว จากขอบล่าง)
    ytop = y1 + 0.10  # ระดับบนสุดของกรอบบน (ใช้เป็นพื้นวางกล่องกระดาษ)
    brown = (0.20, 0.11, 0.08)  # สีน้ำตาลเข้มของกรอบ
    dark = (0.12, 0.07, 0.05)  # สีน้ำตาลเข้มมากของขายึด
    kraft = (0.72, 0.56, 0.38)  # สีกระดาษคราฟท์ (น้ำตาลอ่อน)
    box(0.0, y0, z0, 0.03, y1, z1, (0.94, 0.95, 0.96))                      # แผ่นบอร์ด  # วาดแผ่นบอร์ดสีขาว บางติดผนัง
    box(0.0, y1, z0 - 0.04, 0.09, y1 + 0.10, z1 + 0.04, brown)              # กรอบบน  # วาดกรอบด้านบนสีน้ำตาล
    box(0.0, y0 - 0.06, z0 - 0.04, 0.12, y0, z1 + 0.04, brown)               # ถาดล่าง  # วาดถาดรองปากกาด้านล่างบอร์ด
    box(0.10, y0 - 0.06, z0 - 0.04, 0.12, y0 + 0.015, z1 + 0.04, brown)      # ขอบกั้นหน้าถาด  # วาดขอบกั้นเล็ก ๆ ที่ขอบหน้าถาด กันของกลิ้งตก
    box(0.0, y0, z0 - 0.04, 0.04, y1, z0, brown)                             # เสาข้าง  # วาดกรอบข้างด้านหนึ่งของบอร์ด
    box(0.0, y0, z1, 0.04, y1, z1 + 0.04, brown)  # วาดกรอบข้างอีกด้านหนึ่ง
    box(0.0, y0, zm - 0.005, 0.031, y1, zm + 0.005, (0.7, 0.7, 0.7))         # รอยต่อ 2 แผง  # วาดเส้นเทาบาง ๆ กลางบอร์ด เป็นรอยต่อระหว่างสองแผง
    # ขายึดใต้ถาด
    for z in (z0 + 0.45, z0 + 1.55, zm, z1 - 1.55, z1 - 0.45):  # วนวางขายึด 5 ตัวใต้ถาด (ตำแหน่งตามความยาว)
        box(0.0, y0 - 0.14, z - 0.02, 0.05, y0 - 0.06, z + 0.02, dark)  # วาดส่วนตั้งของขายึด (ติดผนัง)
        box(0.0, y0 - 0.14, z - 0.02, 0.10, y0 - 0.11, z + 0.02, dark)  # วาดส่วนนอนของขายึด (รองใต้ถาด)
    # กล่องกระดาษคราฟท์ยาววางบนกรอบบน + ชิ้นเล็กทางซ้าย
    box(0.0, ytop, 4.70, 0.14, ytop + 0.075, 6.04, kraft)  # วาดกล่องกระดาษใบยาววางบนกรอบบน
    box(0.0, ytop, 3.26, 0.14, ytop + 0.075, 4.66, tuple(v * 0.94 for v in kraft))  # วาดกล่องอีกใบวางต่อกัน สีเข้มกว่าเดิมเล็กน้อย (คูณ 0.94)
    box(0.0, ytop + 0.075, 4.70, 0.14, ytop + 0.079, 6.04, (0.82, 0.68, 0.50))   # แผ่นฝากล่อง  # วาดฝากล่องบาง ๆ สีอ่อนกว่า วางบนกล่องใบแรก
    box(0.0, ytop, 6.62, 0.06, ytop + 0.045, 6.95, (0.55, 0.40, 0.25))  # วาดกล่องชิ้นเล็กทางซ้ายสุด สีเข้มกว่า
    # แจกันดอกไม้บนถาด (ซ้ายสุดของบอร์ดเมื่อมองจากหน้าห้อง)
    vz = 6.72  # ตำแหน่งวางแจกันตามความยาวห้อง
    cylinder(0.06, y0, vz, 0.028, 0.10, (0.82, 0.88, 0.93), 14)  # วาดตัวแจกันสีฟ้าอ่อน
    cylinder(0.06, y0 + 0.07, vz, 0.024, 0.02, (0.55, 0.70, 0.82), 14)  # วาดแถบสีฟ้าเข้มคาดที่คอแจกัน
    green = (0.20, 0.50, 0.22)  # สีเขียวของก้านดอก
    tube((0.06, y0 + 0.10, vz), (0.075, y0 + 0.27, vz - 0.03), 0.003, green, 6)  # วาดก้านดอกที่ 1 เป็นท่อบาง เอียงออกจากปากแจกัน
    tube((0.06, y0 + 0.10, vz), (0.045, y0 + 0.24, vz + 0.035), 0.003, green, 6)  # วาดก้านดอกที่ 2 เอียงไปอีกทาง
    ball(0.075, y0 + 0.28, vz - 0.03, 0.03, (0.88, 0.28, 0.38), 10, 6)  # วาดดอกที่ 1 เป็นลูกบอลสีแดงชมพูที่ปลายก้าน
    ball(0.045, y0 + 0.25, vz + 0.035, 0.026, (0.95, 0.85, 0.88), 10, 6)  # วาดดอกที่ 2 เป็นลูกบอลสีชมพูอ่อน
    # ของจิ๋วบนถาด: ปากกา/ที่ลบ
    box(0.04, y0, 6.18, 0.07, y0 + 0.02, 6.26, (0.15, 0.15, 0.16))  # วาดปากกาหรือที่ลบสีดำเล็ก ๆ วางบนถาด
    box(0.045, y0, 3.28, 0.07, y0 + 0.022, 3.50, (0.06, 0.06, 0.07))  # วาดที่ลบกระดานสีดำ (ตัวใหญ่ขึ้น) วางบนถาดอีกจุด
    box(0.045, y0 + 0.022, 3.28, 0.07, y0 + 0.026, 3.34, (0.70, 0.72, 0.75))  # วาดแถบสีเทาบาง ๆ บนที่ลบ (ส่วนที่เป็นสักหลาด)
    # สติกเกอร์ส้มบนผนังข้างบอร์ด
    gquad([(0.003, 1.45, 7.25), (0.003, 1.45, 7.31), (0.003, 1.52, 7.31), (0.003, 1.52, 7.25)],  # วาดสี่เหลี่ยมเล็ก ๆ ติดผนังข้างบอร์ด (ระบุ 4 มุม)
          [(0.95, 0.55, 0.15)] * 4)  # ทาสีส้มเหมือนกันทั้ง 4 มุม
    # รอยเขียนจางๆ บนบอร์ด
    sm = (0.80, 0.82, 0.85)  # สีเทาจางของรอยเขียนที่ลบไม่หมด
    for (za, zb, ya, yb) in ((3.05, 3.55, 1.55, 1.58), (3.15, 3.45, 1.50, 1.52),  # รายการรอยเขียน: แต่ละรอยบอกตำแหน่งซ้าย-ขวา (za, zb) และล่าง-บน (ya, yb) (สองรอยแรก)
                             (3.70, 3.95, 1.62, 1.65), (3.25, 3.60, 1.40, 1.42)):  # (อีกสองรอย)
        gquad([(0.0315, ya, za), (0.0315, ya, zb), (0.0315, yb, zb), (0.0315, yb, za)], [sm] * 4)  # วาดรอยเป็นแถบบาง ๆ ลอยเหนือแผ่นบอร์ดเล็กน้อย (0.0315 เทียบกับบอร์ด 0.03) สีเทาจาง


def _roll_z(zc, xo, cy, r, length, col):  # สร้างสูตรวางม้วนฉากกระดาษนอนตามแนวผนัง (ฟังก์ชันช่วยภายใน)
    """ม้วนฉากกระดาษวางนอนตามแนวผนังตะวันตก (ตามแนวแกน Z)  xo = ระยะจากผนัง"""
    glPushMatrix()  # เซฟตำแหน่งและมุมปัจจุบันไว้ก่อน
    glTranslatef(0, 0, zc)  # ย้ายจุดอ้างอิงไปตามความยาวห้อง ถึงตำแหน่งกึ่งกลางม้วน
    glRotatef(90, 0, 1, 0)  # หมุนแกนไป 90 องศา เพื่อให้ฟังก์ชันวาดม้วนที่วาดตามแกน X กลายเป็นวางตามแกน Z
    paper_roll(-length / 2, length / 2, cy, xo, r, col)  # เรียกฟังก์ชัน paper_roll วาดม้วนกระดาษ (ฟังก์ชันนี้ไม่ได้อยู่ในไฟล์ที่ได้รับ ต้องอยู่ในไฟล์ส่วนอื่น)
    glPopMatrix()  # กลับไปยังตำแหน่งที่เซฟไว้ เพื่อไม่ให้กระทบสิ่งอื่นที่จะวาดต่อ


def wall_paper_rolls():  # สร้างสูตรวางม้วนฉากกระดาษทั้งหมดใต้ไวท์บอร์ด
    """ม้วนฉากกระดาษใต้ไวท์บอร์ด (เขียว/ขาว/ชมพู/คราฟท์) วางบนพื้นชิดผนังตะวันตก"""
    COLLIDERS.append((0.0, 2.78, 0.36, 5.86))  # จดพื้นที่ที่ม้วนกระดาษครอบครองไว้ในสมุดสิ่งกีดขวาง (เดินทะลุไม่ได้)
    L = 1.36  # ความยาวของแต่ละม้วน 1.36 เมตร
    _roll_z(5.10, 0.085, 0.070, 0.070, L, (0.25, 0.60, 0.30))     # เขียว  # วางม้วนสีเขียว ติดผนัง
    _roll_z(5.05, 0.225, 0.065, 0.065, L, (0.95, 0.95, 0.94))     # ขาว  # วางม้วนสีขาว ห่างผนังมากกว่าม้วนเขียว
    _roll_z(3.55, 0.085, 0.070, 0.070, L, (0.95, 0.55, 0.65))     # ชมพู  # วางม้วนสีชมพู ติดผนัง
    _roll_z(3.55, 0.225, 0.065, 0.065, L, (0.74, 0.57, 0.36))     # คราฟท์  # วางม้วนสีคราฟท์ ห่างผนังมากกว่าม้วนชมพู
    _roll_z(3.60, 0.155, 0.180, 0.060, L, (0.93, 0.93, 0.92))     # ขาววางพาดด้านบน  # วางม้วนสีขาวอีกม้วน พาดอยู่ด้านบนระหว่างสองม้วนข้างล่าง (cy = 0.18 จึงลอยสูงกว่า)

# =====================================================================
# 5) ของในห้อง
# =====================================================================
def perforated_panel(x0, y0, z0, x1, y1, z1, col, rows=4, slot_w=0.042, slot_h=0.017, px=0.062, py=0.058):  # สร้างสูตรวาดแผงเจาะรู (มุมแผง สี จำนวนแถวรู ขนาดรู ระยะห่างรู)
    """แผงหน้าโต๊ะเจาะรูสี่เหลี่ยมผืนผ้าเรียงเป็นตาราง (ทะลุจริง มองเห็นด้านหลังผ่านรูได้)
    rows = จำนวนแถวของรู, slot_w/slot_h = ขนาดรู (m), px/py = ระยะห่างจุดกึ่งกลางรูแนวนอน/แนวตั้ง
    สร้างจากแถบเต็มความกว้างสลับกับแถวของ "เสา" คั่นระหว่างรู จัดตารางรูให้อยู่กึ่งกลางแผง"""
    L = x1 - x0  # ความกว้างของแผง
    nx = int((L - 0.10 - slot_w) / px) + 1                 # จำนวนรูต่อแถว (เว้นขอบซ้ายขวา >= 5 cm)  # คำนวณว่าใน 1 แถวใส่รูได้กี่รู
    gx0 = x0 + (L - ((nx - 1) * px + slot_w)) / 2  # ตำแหน่งเริ่มของรูแรก โดยจัดให้ตารางรูอยู่กึ่งกลางแผงตามแนวนอน
    gy0 = y0 + ((y1 - y0) - ((rows - 1) * py + slot_h)) / 2  # ตำแหน่งเริ่มของแถวรูแรก โดยจัดให้อยู่กึ่งกลางแผงตามแนวตั้ง
    yc = y0  # ตัวนับความสูงที่วาดมาถึง เริ่มจากขอบล่างของแผง
    for r in range(rows):  # วนทีละแถวของรู
        ys0 = gy0 + r * py  # ขอบล่างของรูในแถวนี้
        ys1 = ys0 + slot_h  # ขอบบนของรูในแถวนี้
        box(x0, yc, z0, x1, ys0, z1, col)                  # แถบทึบใต้แถวรู  # วาดแถบทึบเต็มความกว้าง จากที่วาดมาถึงตอนนี้จนถึงขอบล่างของรู
        xc = x0  # ตัวนับตำแหน่งแนวนอน เริ่มจากขอบซ้ายของแผง
        for i in range(nx):                                # เสาคั่นระหว่างรู  # วนทีละรูในแถว
            sx0 = gx0 + i * px  # ตำแหน่งขอบซ้ายของรูที่ i
            box(xc, ys0, z0, sx0, ys1, z1, col)  # วาดเสาทึบที่คั่นอยู่ก่อนถึงรูนี้ (ช่องว่างที่เหลือคือรู)
            xc = sx0 + slot_w  # ขยับตัวนับไปที่ขอบขวาของรู
        box(xc, ys0, z0, x1, ys1, z1, col)  # วาดเสาทึบสุดท้ายจากรูสุดท้ายถึงขอบขวาของแผง
        yc = ys1  # ขยับตัวนับความสูงขึ้นไปที่ขอบบนของแถวรู
    box(x0, yc, z0, x1, y1, z1, col)                       # แถบทึบบนสุด  # วาดแถบทึบบนสุดของแผง


def training_table(x0, z0, length=1.8, depth=0.6):  # สร้างสูตรวาดโต๊ะพับ 1 ตัว (ตำแหน่งมุม ความยาว ความลึก)
    """โต๊ะพับ 1.8 x 0.6 m สูง 0.75 m (29.5 inch) มีแผงขาวเจาะรูด้านใต้โต๊ะ"""
    box(x0, 0.72, z0, x0 + length, 0.75, z0 + depth, WOOD)  # วาดแผ่นหน้าโต๊ะสีไม้ หนา 3 ซม. อยู่สูง 0.72-0.75 เมตร
    for x in (x0 + 0.12, x0 + length - 0.12):  # วนทำขาโต๊ะสองข้าง (ซ้ายและขวา ห่างจากปลายโต๊ะ 12 ซม.)
        box(x - 0.02, 0.06, z0 + 0.04, x + 0.02, 0.72, z0 + 0.08, WHITE)  # วาดขาด้านหน้า (ตั้งจากพื้นถึงใต้โต๊ะ)
        box(x - 0.02, 0.06, z0 + depth - 0.08, x + 0.02, 0.72, z0 + depth - 0.04, WHITE)  # วาดขาด้านหลัง
        box(x - 0.02, 0.03, z0 + 0.03, x + 0.02, 0.07, z0 + depth - 0.03, WHITE)  # วาดคานเท้าที่เชื่อมขาหน้ากับขาหลังตรงใกล้พื้น
    perforated_panel(x0 + 0.05, 0.36, z0 + 0.03, x0 + length - 0.05, 0.69, z0 + 0.05, (0.88, 0.88, 0.90))   # แผงเจาะรูฝั่งเหนือ (หันไปทางคอมพิวเตอร์)  # วาดแผงขาวเจาะรูใต้โต๊ะ สูง 0.36-0.69 เมตร ด้านที่หันไปทางคอมพิวเตอร์


UNDER_RNG = random.Random(7)     # เปลี่ยนเลข seed เพื่อสุ่มตำแหน่งสตูลใต้โต๊ะใหม่  # ตัวสุ่มตัวเลข (เลข 7 ทำให้ผลสุ่มเหมือนเดิมทุกครั้ง เปลี่ยนเลขก็ได้ตำแหน่งใหม่)


def training_rows():  # สร้างสูตรวางโต๊ะฝึกอบรมทั้งหมดเป็นแถว
    """โต๊ะ 4 แถว ช่องว่างเท่ากันหมด (ROW_GAP): โต๊ะดำ -> แถว 1 -> 2 -> 3 -> 4
    ชิดไปทางผนังหน้าต่าง ที่เหลือฝั่งประตูเป็นพื้นที่โล่งไว้เดินสำรวจ
    คนนั่งอยู่ฝั่งใต้ของโต๊ะ หันหน้าไปทางคอมพิวเตอร์/ทีวี"""
    n, depth, length, per_row = 4, 0.6, 1.8, 3  # มี 4 แถว โต๊ะลึก 0.6 ม. ยาว 1.8 ม. แถวละ 3 ตัว
    z_start = BLACK_TABLE_Z + 23.5 * INCH / 2          # ขอบหน้าของโต๊ะดำ  # ตำแหน่งขอบหน้าของโต๊ะดำ (จุดเริ่มนับระยะแถวแรก)
    x0 = (W - per_row * length) / 2                    # จัดกึ่งกลางห้อง  # ตำแหน่งเริ่มด้านซ้าย เพื่อให้แถวโต๊ะอยู่กลางห้อง
    for r in range(n):  # วนทีละแถว
        zr = z_start + ROW_GAP + r * (depth + ROW_GAP)  # ตำแหน่งของแถวนี้ตามความยาวห้อง (เว้นช่องว่างเท่ากันทุกแถว)
        for i in range(per_row):  # วนทีละโต๊ะในแถว
            training_table(x0 + i * length, zr, length, depth)  # วางโต๊ะตัวที่ i วางต่อกันไปทางขวา
        COLLIDERS.append((x0, zr, x0 + per_row * length, zr + depth))  # จดพื้นที่ของทั้งแถวไว้ในสมุดสิ่งกีดขวาง
        # สตูลสุ่มเก็บไว้ใต้โต๊ะ (หลบขาโต๊ะ/แผงหน้าโต๊ะ) ไม่ต้องเพิ่ม collider เพราะโต๊ะกันไว้แล้ว
        for i in range(per_row):  # วนทีละช่วงโต๊ะอีกรอบ เพื่อวางสตูล
            if UNDER_RNG.random() < 0.55:  # สุ่ม โดยมีโอกาส 55% ที่ช่วงนี้จะมีสตูลเก็บอยู่ใต้โต๊ะ
                sx = x0 + i * length + UNDER_RNG.uniform(0.50, 1.30)  # สุ่มตำแหน่งแนวนอนของสตูลใต้โต๊ะตัวนี้ (ไม่ชนขาโต๊ะ)
                sz = zr + UNDER_RNG.uniform(0.34, 0.50)  # สุ่มความลึกของสตูล (ไม่ชนแผงหน้าโต๊ะ)
                stool(sx, 0.0, sz, dots=True)  # วางสตูลที่ตำแหน่งนั้น (ฟังก์ชัน stool ไม่ได้อยู่ในไฟล์นี้ ต้องอยู่ในไฟล์ส่วนอื่น)


def keyboard(cx, y0, cz, w=0.279, d=0.115):  # สร้างสูตรวาดคีย์บอร์ด Apple (ตำแหน่ง กว้าง ลึก)
    """คีย์บอร์ดแบบ Apple Magic Keyboard ขนาดจริง 279 x 115 mm ตัวเอียงสูง 10.8 -> 4.1 mm
    แถวฟังก์ชันอยู่ไกลตัว (z น้อย) แถวสเปซบาร์อยู่ใกล้ตัว (z มาก)  แต่ละปุ่มมีสัญลักษณ์เล็กๆ บนหน้าปุ่ม"""
    x0, x1 = cx - w / 2, cx + w / 2  # ขอบซ้ายและขวาของคีย์บอร์ด
    z0, z1 = cz - d / 2, cz + d / 2  # ขอบหลังและขอบหน้าของคีย์บอร์ด
    hb, hf = 0.0108, 0.0041  # ความสูงด้านหลัง 10.8 มม. และด้านหน้า 4.1 มม. (ตัวเครื่องเป็นรูปลิ่ม)
    silver, keyc, leg = (0.82, 0.82, 0.84), (0.97, 0.97, 0.98), (0.13, 0.13, 0.15)  # สีตัวเครื่องอะลูมิเนียม สีปุ่ม และสีตัวอักษรบนปุ่ม

    def top_y(z):  # ฟังก์ชันย่อย: บอกความสูงของผิวคีย์บอร์ด ณ ตำแหน่ง z
        return y0 + hb + (hf - hb) * (z - z0) / d  # ไล่ความสูงจากด้านหลัง (สูง) ไปด้านหน้า (ต่ำ) ตามสัดส่วน

    glBegin(GL_QUADS)                                                # ตัวเครื่องอะลูมิเนียมทรงลิ่ม  # เริ่มวาดตัวเครื่องแบบลิ่ม
    glColor3f(*silver)  # เลือกสีเงินเต็มสำหรับด้านบน
    glVertex3f(x0, y0 + hb, z0); glVertex3f(x1, y0 + hb, z0); glVertex3f(x1, y0 + hf, z1); glVertex3f(x0, y0 + hf, z1)  # วาดด้านบน (ลาดเอียงจากหลังลงหน้า)
    glColor3f(silver[0] * 0.85, silver[1] * 0.85, silver[2] * 0.85)  # สีเงินมืดลง 15% สำหรับด้านหน้า
    glVertex3f(x0, y0, z1); glVertex3f(x1, y0, z1); glVertex3f(x1, y0 + hf, z1); glVertex3f(x0, y0 + hf, z1)  # วาดด้านหน้า (ด้านใกล้ตัว)
    glColor3f(silver[0] * 0.70, silver[1] * 0.70, silver[2] * 0.70)  # สีเงินมืดลง 30% สำหรับด้านหลัง
    glVertex3f(x0, y0, z0); glVertex3f(x1, y0, z0); glVertex3f(x1, y0 + hb, z0); glVertex3f(x0, y0 + hb, z0)  # วาดด้านหลัง (สูงกว่าด้านหน้า)
    glColor3f(silver[0] * 0.75, silver[1] * 0.75, silver[2] * 0.75)  # สีเงินมืดลง 25% สำหรับด้านซ้าย
    glVertex3f(x0, y0, z0); glVertex3f(x0, y0, z1); glVertex3f(x0, y0 + hf, z1); glVertex3f(x0, y0 + hb, z0)  # วาดด้านซ้าย (เป็นรูปสี่เหลี่ยมคางหมู)
    glColor3f(silver[0] * 0.90, silver[1] * 0.90, silver[2] * 0.90)  # สีเงินมืดลง 10% สำหรับด้านขวา
    glVertex3f(x1, y0, z0); glVertex3f(x1, y0, z1); glVertex3f(x1, y0 + hf, z1); glVertex3f(x1, y0 + hb, z0)  # วาดด้านขวา
    glEnd()  # วาดตัวเครื่องเสร็จ

    # (ความกว้างปุ่มเป็นหน่วย u, ชนิด)  ชนิด: None ปกติ / 'sp' สเปซบาร์ / 'ud' ลูกศรขึ้น-ลง (ครึ่งความสูง)
    n = lambda k: [(1.0, None)] * k  # ฟังก์ชันลัด: สร้างรายการปุ่มปกติ k ปุ่ม (กว้าง 1 หน่วย)
    rows = [  # รายการแถวปุ่ม แต่ละแถวบอกความสูงแถว และปุ่มที่อยู่ในแถว
        (0.0115, [(1.5, None)] + n(13)),  # แถวบนสุด (ปุ่มฟังก์ชัน เตี้ยกว่าแถวอื่น) ปุ่ม esc กว้าง 1.5 แล้วตามด้วยปุ่มปกติ 13 ปุ่ม
        (0.0185, n(13) + [(1.5, None)]),  # แถวตัวเลข ปุ่มปกติ 13 ปุ่ม แล้วปุ่ม delete กว้าง 1.5
        (0.0185, [(1.5, None)] + n(13)),  # แถว Tab ปุ่ม Tab กว้าง 1.5 แล้วปุ่มปกติ 13 ปุ่ม
        (0.0185, [(1.75, None)] + n(11) + [(1.75, None)]),  # แถว Caps Lock ปุ่มกว้างที่ปลายทั้งสองข้าง
        (0.0185, [(2.25, None)] + n(10) + [(2.25, None)]),  # แถว Shift ปุ่มกว้างที่ปลายทั้งสองข้าง
        (0.0185, [(1.0, None)] * 3 + [(1.25, None), (5.0, 'sp'), (1.25, None), (1.0, None),  # แถวล่างสุด: ปุ่มปกติ 3 ปุ่ม ปุ่ม cmd สเปซบาร์ (กว้าง 5) ปุ่ม cmd อีกปุ่ม และปุ่มปกติ
                                      (1.0, None), (1.0, 'ud'), (1.0, None)]),  # ปุ่มลูกศรซ้าย ลูกศรขึ้น-ลง (แบ่งครึ่งความสูง) ลูกศรขวา
    ]
    xa0 = x0 + 0.005  # จุดเริ่มวางปุ่มแนวนอน (เว้นขอบซ้าย 5 มม.)
    u = (w - 0.010) / 14.5  # ความกว้าง 1 หน่วยปุ่ม (คีย์บอร์ดกว้างรวม 14.5 หน่วย เว้นขอบสองข้าง)
    gap = 0.0016  # ช่องว่างระหว่างปุ่ม 1.6 มม.
    zc = z0 + 0.0055  # จุดเริ่มวางแถวแรกตามแนวลึก (เว้นขอบหลัง 5.5 มม.)
    for (rh, keys) in rows:  # วนทีละแถว (rh = ความสูงแถว)
        xc = xa0  # ตัวนับตำแหน่งแนวนอน เริ่มต้นที่ซ้ายสุด
        for (kw, kind) in keys:  # วนทีละปุ่มในแถว (kw = ความกว้าง kind = ชนิดปุ่ม)
            ka, kb = xc + gap / 2, xc + kw * u - gap / 2  # ขอบซ้ายและขวาของปุ่ม (หักช่องว่างออก)
            xc += kw * u  # ขยับตัวนับไปทางขวา เตรียมวางปุ่มถัดไป
            cells = [(zc + gap / 2, zc + rh - gap / 2)]  # ช่วงความลึกของปุ่ม (ปกติมี 1 ช่วง)
            if kind == 'ud':                                          # ลูกศรขึ้น/ลง แบ่งครึ่ง  # ถ้าเป็นปุ่มลูกศรขึ้น-ลง
                mid = zc + rh / 2  # จุดกึ่งกลางความสูงแถว
                cells = [(zc + gap / 2, mid - gap / 4), (mid + gap / 4, zc + rh - gap / 2)]  # แบ่งเป็น 2 ปุ่มซ้อนกัน (ลูกศรขึ้นและลง) ปุ่มละครึ่ง
            for (za, zb) in cells:  # วนทีละปุ่ม (ส่วนใหญ่มี 1 ปุ่ม ลูกศรขึ้น-ลงมี 2)
                yb = min(top_y(za), top_y(zb)) - 0.0008  # ระดับก้นปุ่ม (จมลงในตัวเครื่องนิดหน่อย)
                yt = max(top_y(za), top_y(zb)) + 0.0032  # ระดับหน้าปุ่ม (สูงกว่าตัวเครื่อง 3.2 มม.)
                box(ka, yb, za, kb, yt, zb, keyc)  # วาดตัวปุ่มสีขาว
                if kind != 'sp':                                      # สัญลักษณ์บนปุ่ม  # ถ้าไม่ใช่สเปซบาร์ ให้วาดสัญลักษณ์เล็ก ๆ บนปุ่ม
                    mx, mz = (ka + kb) / 2, (za + zb) / 2  # จุดกึ่งกลางของปุ่ม
                    if kw < 1.2:  # ถ้าเป็นปุ่มเล็ก (กว้างไม่ถึง 1.2 หน่วย)
                        sx, sz = 0.0022, 0.0022  # สัญลักษณ์เป็นจุดสี่เหลี่ยมเล็ก ๆ ครึ่งขนาด 2.2 มม.
                        lx0, lz0 = mx - sx, mz - sz  # วางสัญลักษณ์ไว้กลางปุ่ม
                    else:  # ถ้าเป็นปุ่มใหญ่ (เช่น shift, tab)
                        sx, sz = 0.0036, 0.0016  # สัญลักษณ์เป็นแถบยาวกว่า
                        lx0, lz0 = ka + 0.0025, zb - 0.0045  # วางสัญลักษณ์ไว้มุมล่างซ้ายของปุ่ม (เหมือนตัวอักษรชื่อปุ่ม)
                    gquad([(lx0, yt + 0.0004, lz0), (lx0 + 2 * sx, yt + 0.0004, lz0),  # วาดสัญลักษณ์ (ลอยเหนือปุ่ม 0.4 มม. ไม่ให้ภาพทับกัน) สองมุมแรก
                           (lx0 + 2 * sx, yt + 0.0004, lz0 + 2 * sz), (lx0, yt + 0.0004, lz0 + 2 * sz)],  # สองมุมหลัง
                          [leg] * 4)  # ทาสีเข้มทั้ง 4 มุม
        zc += rh  # ขยับลงไปแถวถัดไป


def apple_logo(cx, cy, zface, size, facing=1, col=(0.50, 0.51, 0.53), bg=(0.88, 0.88, 0.90)):  # สร้างสูตรวาดโลโก้ Apple บนผิวตั้ง (ตำแหน่ง ขนาด ทิศที่หัน สีโลโก้ สีพื้น)
    """โลโก้ Apple แปะบนผิวเรียบ (วาดจากวงกลมซ้อนกัน + วงกัด + ใบ)
    cx, cy = จุดกึ่งกลาง  zface = ตำแหน่ง z ของผิว  size = ความสูงโลโก้ (เมตร)
    facing = +1 หันไปทาง +Z (หน้าจอ)  -1 หันไปทาง -Z (ด้านหลัง)
    bg = สีดิบของตัวเครื่อง (ก่อนหรี่เฉด) ฟังก์ชันจะคูณเฉดของด้านนั้นให้เอง รอยกัดจึงกลืนกับตัวเครื่องทั้งด้านหน้า/หลัง"""
    k = size / 1.13  # ตัวคูณปรับขนาด (โลโก้ที่ออกแบบไว้สูง 1.13 หน่วย ปรับให้เท่ากับขนาดที่ต้องการ)
    shade = SHADE_S if facing > 0 else SHADE_N          # เฉดเดียวกับที่ box() ใช้ทาหน้า +Z / -Z  # เลือกเฉดความสว่างให้ตรงกับด้านที่โลโก้แปะอยู่
    bg = (bg[0] * shade, bg[1] * shade, bg[2] * shade)  # ปรับสีพื้นให้เข้ากับเฉดนั้น (รอยกัดจะได้กลืนกับตัวเครื่อง)

    def disc(ox, oy, r, rx, ry, rot, color, off, n=28):  # ฟังก์ชันย่อย: วาดวงกลมหรือวงรี 1 วง (ตำแหน่ง รัศมี มุมหมุน สี ระยะลอยเหนือผิว)
        a = math.radians(rot)  # แปลงมุมหมุนจากองศาเป็นเรเดียน
        glColor3f(*color)  # เลือกสี
        glBegin(GL_TRIANGLE_FAN)  # เริ่มวาดแบบพัด (สามเหลี่ยมหลายอันที่มีจุดร่วมที่กลางวง)
        glVertex3f(cx + facing * (ox * k), cy + oy * k, zface + facing * off)  # จุดกึ่งกลางวง
        for i in range(n + 1):  # วนรอบขอบวงให้ครบ 1 รอบ
            t = 2 * math.pi * i / n  # มุมของจุดบนขอบ
            ex, ey = rx * math.cos(t), ry * math.sin(t)  # ตำแหน่งจุดบนวงรี (ก่อนหมุน)
            px = ox + ex * math.cos(a) - ey * math.sin(a)  # หมุนจุดตามมุม rot แล้วเลื่อนไปตำแหน่งวง (แกนนอน)
            py = oy + ex * math.sin(a) + ey * math.cos(a)  # เช่นเดียวกัน (แกนตั้ง)
            glVertex3f(cx + facing * (px * k), cy + py * k, zface + facing * off)  # ใส่จุดนั้นเป็นขอบของวง
        glEnd()  # วาดวงเสร็จ

    disc(-0.15, -0.02, 0, 0.34, 0.34, 0, col, 0.0006)    # ตัวแอปเปิ้ล (บนซ้าย/ขวา)  # วงกลมซ้ายบนของตัวแอปเปิ้ล
    disc(0.15, -0.02, 0, 0.34, 0.34, 0, col, 0.0006)  # วงกลมขวาบนของตัวแอปเปิ้ล (ทับซ้อนกับวงซ้ายเป็นรูปหัวใจ)
    disc(-0.14, -0.27, 0, 0.26, 0.26, 0, col, 0.0006)    # ก้นแอปเปิ้ล  # วงกลมซ้ายล่าง (ก้นแอปเปิ้ล)
    disc(0.14, -0.27, 0, 0.26, 0.26, 0, col, 0.0006)  # วงกลมขวาล่าง
    disc(0.47, 0.02, 0, 0.17, 0.17, 0, bg, 0.0012)       # รอยกัด  # วงกลมสีพื้นทับที่ด้านขวา ทำให้ดูเหมือนแอปเปิ้ลถูกกัด
    disc(0.10, 0.50, 0, 0.19, 0.08, 38, col, 0.0006)     # ใบ  # วงรีเอียง 38 องศาด้านบน เป็นใบไม้


def apple_logo_flat(cx, y, cz, size, col=(0.52, 0.53, 0.56), bg=(0.86, 0.86, 0.88)):  # สร้างสูตรวาดโลโก้ Apple บนผิวแนวนอน (เช่น หลังเมาส์)
    """โลโก้ Apple แปะบนผิวแนวนอน (มองจากด้านบน ยอดใบชี้ไปทาง -Z = ไกลตัว)
    cx, cz = จุดกึ่งกลาง  y = ความสูงผิว  size = ความสูงโลโก้ (เมตร)  bg = สีพื้นไว้เติมรอยกัด"""
    k = size / 1.13  # ตัวคูณปรับขนาด (เหมือนฟังก์ชันก่อนหน้า)

    def disc(ox, oy, rx, ry, rot, color, off, n=24):  # ฟังก์ชันย่อย: วาดวงกลมหรือวงรี 1 วง บนพื้นผิวแนวนอน
        a = math.radians(rot)  # แปลงมุมหมุนเป็นเรเดียน
        glColor3f(*color)  # เลือกสี
        glBegin(GL_TRIANGLE_FAN)  # เริ่มวาดแบบพัด
        glVertex3f(cx + ox * k, y + off, cz - oy * k)  # จุดกึ่งกลางวง (ใช้ -oy เพราะ "ด้านบนของโลโก้" ชี้ไปทาง -Z)
        for i in range(n + 1):  # วนรอบขอบวงให้ครบ 1 รอบ
            t = 2 * math.pi * i / n  # มุมของจุดบนขอบ
            ex, ey = rx * math.cos(t), ry * math.sin(t)  # ตำแหน่งจุดบนวงรี (ก่อนหมุน)
            px = ox + ex * math.cos(a) - ey * math.sin(a)  # หมุนจุดแล้วเลื่อนไปตำแหน่งวง (แกนนอน)
            py = oy + ex * math.sin(a) + ey * math.cos(a)  # เช่นเดียวกัน (อีกแกน)
            glVertex3f(cx + px * k, y + off, cz - py * k)  # ใส่จุดนั้นเป็นขอบของวง
        glEnd()  # วาดวงเสร็จ

    disc(-0.15, -0.02, 0.34, 0.34, 0, col, 0.0003)       # ตัวแอปเปิ้ล  # วงกลมซ้ายบนของตัวแอปเปิ้ล
    disc(0.15, -0.02, 0.34, 0.34, 0, col, 0.0003)  # วงกลมขวาบนของตัวแอปเปิ้ล
    disc(-0.14, -0.27, 0.26, 0.26, 0, col, 0.0003)       # ก้นแอปเปิ้ล  # วงกลมซ้ายล่าง
    disc(0.14, -0.27, 0.26, 0.26, 0, col, 0.0003)  # วงกลมขวาล่าง
    disc(0.47, 0.02, 0.17, 0.17, 0, bg, 0.0006)          # รอยกัด  # วงสีพื้นทับด้านขวา ให้ดูเหมือนถูกกัด
    disc(0.10, 0.50, 0.19, 0.08, 38, col, 0.0003)        # ใบ  # วงรีเอียงเป็นใบไม้


def magic_mouse(cx, y0, cz, yaw=0.0, L=5 * INCH, Wd=2 * INCH, Hm=0.0216):  # สร้างสูตรวาดเมาส์ Apple Magic Mouse (ตำแหน่ง มุมหมุน ยาว กว้าง สูง)
    """Apple Magic Mouse ขนาด 5 x 2 inch (ตามที่วัด) สูงประมาณ 2.2 cm ตัวโค้งมนสีขาว มีโลโก้ Apple บนหลังเมาส์
    ปลายด้านหน้า (ปลายนิ้ว) หันไปทาง -Z (ทางหน้าจอ)  yaw = หมุนรอบแกนตั้ง (องศา)"""
    N, M = 16, 12  # แบ่งตัวเมาส์เป็น 16 ท่อนตามความยาว และ 12 ชิ้นรอบหน้าตัด (ยิ่งเยอะยิ่งโค้งเนียน)
    hw = Wd / 2  # ครึ่งหนึ่งของความกว้าง
    peak = 0.62                                        # จุดสูงสุดอยู่ค่อนไปทางท้ายเมาส์  # จุดที่เมาส์นูนสูงสุด อยู่ที่ 62% ของความยาว (ค่อนไปทางท้าย)

    def prof(v):  # ฟังก์ชันย่อย: บอกความกว้างและความสูงของเมาส์ ณ ตำแหน่ง v (0 = ปลายหนึ่ง 1 = อีกปลาย)
        t = 2 * v - 1  # แปลง v ให้อยู่ในช่วง -1 ถึง 1
        w = hw * math.sqrt(max(0.0, 1 - abs(t) ** 3.2))       # ความกว้างตามแปลน (ปลายมน)  # ความกว้าง: กว้างสุดตรงกลาง แคบลงที่ปลายทั้งสองข้างแบบมน
        u = (v - peak) / (peak if v < peak else (1 - peak))   # ระยะห่างจากจุดสูงสุด (ปรับให้อยู่ช่วง -1 ถึง 1)
        h = Hm * math.sqrt(max(0.0, 1 - u * u))               # ความสูงตามแนวยาว  # ความสูง: สูงสุดที่จุด peak ลาดลงไปทั้งสองปลาย
        return w, h  # ส่งค่าความกว้างและความสูงกลับไป

    def pt(k, m):  # ฟังก์ชันย่อย: คำนวณตำแหน่งจุดบนผิวเมาส์ (ท่อนที่ k ชิ้นที่ m)
        v = k / N  # ตำแหน่งตามความยาว (0 ถึง 1)
        w, h = prof(v)  # ความกว้างและความสูง ณ ตำแหน่งนั้น
        ph = math.pi * m / M  # มุมรอบหน้าตัด (ครึ่งวงกลม ซ้ายผ่านบนไปขวา)
        return (w * math.cos(ph), h * (math.sin(ph) ** 0.55), -L / 2 + v * L)  # ตำแหน่งจุด (แกน x แกน y แกน z) ยกกำลัง 0.55 ทำให้หลังเมาส์ป้านขึ้น

    glPushMatrix()  # เซฟตำแหน่งและมุมปัจจุบันไว้ก่อน
    glTranslatef(cx, y0, cz)  # ย้ายไปยังตำแหน่งที่วางเมาส์
    glRotatef(yaw, 0, 1, 0)  # หมุนรอบแกนตั้งตามมุม yaw
    body = (0.95, 0.95, 0.97)  # สีขาวของตัวเมาส์
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยมเล็ก ๆ ปะเป็นผิวเมาส์
    for k in range(N):  # วนทีละท่อนตามความยาว
        for m in range(M):  # วนทีละชิ้นรอบหน้าตัด
            p00, p01, p11, p10 = pt(k, m), pt(k, m + 1), pt(k + 1, m + 1), pt(k + 1, m)  # หา 4 มุมของแผ่นนี้
            e1 = (p01[0] - p00[0], p01[1] - p00[1], p01[2] - p00[2])  # เส้นขอบแผ่นเส้นที่ 1
            e2 = (p10[0] - p00[0], p10[1] - p00[1], p10[2] - p00[2])  # เส้นขอบแผ่นเส้นที่ 2
            n = (e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2], e1[0] * e2[1] - e1[1] * e2[0])  # หาทิศที่ผิวหันไป (cross product)
            ctr = ((p00[0] + p11[0]) / 2, (p00[1] + p11[1]) / 2 - 0.006, (p00[2] + p11[2]) / 2)  # จุดกลางแผ่น (ลดความสูงลง 6 มม. เทียบกับแกนกลางตัวเมาส์ ใช้ตัดสินว่าทิศหันเข้าหรือออก)
            if n[0] * ctr[0] + n[1] * ctr[1] + n[2] * ctr[2] < 0:  # ถ้าทิศที่ได้หันเข้าด้านใน
                n = (-n[0], -n[1], -n[2])  # กลับทิศให้หันออกนอก
            nl = math.sqrt(n[0] ** 2 + n[1] ** 2 + n[2] ** 2) or 1.0  # ความยาวของทิศ (กันไม่ให้เป็นศูนย์)
            sh = 0.55 + 0.45 * max(0.0, (n[0] * LIGHT_N[0] + n[1] * LIGHT_N[1] + n[2] * LIGHT_N[2]) / nl)  # ความสว่างตามทิศที่ผิวหันเข้าหาแสง (LIGHT_N คือทิศแสง ซึ่งไม่ได้นิยามไว้ในไฟล์ที่ส่งมา)
            glColor3f(body[0] * sh, body[1] * sh, body[2] * sh)  # เลือกสีแผ่นนี้
            glVertex3f(*p00); glVertex3f(*p01); glVertex3f(*p11); glVertex3f(*p10)  # วาดแผ่นด้วย 4 มุม
    glEnd()  # วาดผิวเมาส์เสร็จ
    vz = 0.58                                           # ตำแหน่งโลโก้ตามความยาว (ค่อนไปทางท้าย)  # ตำแหน่งโลโก้ ที่ 58% ของความยาวเมาส์
    apple_logo_flat(0.0, prof(vz)[1] + 0.0004, -L / 2 + vz * L, 0.016)  # แปะโลโก้ Apple ขนาด 1.6 ซม. บนหลังเมาส์ (ลอยเหนือผิว 0.4 มม.)
    glPopMatrix()  # กลับไปยังตำแหน่งที่เซฟไว้


def _strip_x(path, ht, x0, x1, col):  # สร้างสูตรวาดแผ่นโลหะบางโค้งตามเส้นทาง (ใช้ทำแขนโค้งของ iMac)
    """แผ่นโลหะบางโค้งตามเส้นทาง (y, z) ในพิกัดโลก ยืดตามแกน X จาก x0 ถึง x1  ht = ครึ่งหนึ่งของความหนา"""
    n = len(path)  # จำนวนจุดบนเส้นทาง
    pts = []  # รายการเก็บขอบบนและขอบล่างของแผ่น ณ แต่ละจุด
    for i in range(n):  # วนทีละจุดบนเส้นทาง
        a, b = path[max(i - 1, 0)], path[min(i + 1, n - 1)]  # จุดก่อนหน้าและจุดถัดไป (จุดแรกและจุดสุดท้ายใช้จุดของตัวเอง)
        dy, dz = b[0] - a[0], b[1] - a[1]  # ทิศที่เส้นทางพุ่งไป ณ จุดนี้
        L = math.hypot(dy, dz) or 1.0  # ความยาวของทิศนั้น
        ny, nz = -dz / L, dy / L  # ทิศที่ตั้งฉากกับเส้นทาง (ใช้ดันขอบบนและขอบล่างออกจากเส้นกลาง)
        pts.append(((path[i][0] + ny * ht, path[i][1] + nz * ht),  # ขอบด้านหนึ่งของแผ่น (เส้นกลาง + ครึ่งความหนา)
                    (path[i][0] - ny * ht, path[i][1] - nz * ht), (ny, nz)))  # ขอบอีกด้านของแผ่น และทิศที่ผิวหัน
    r, g, b = col  # แยกสีเป็น 3 ค่า
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม
    for i in range(n - 1):  # วนทีละช่วงของเส้นทาง (จุด i ถึง i+1)
        for side, sg in ((0, 1.0), (1, -1.0)):  # วนวาดทั้งสองหน้าของแผ่น (หน้าแรก และหน้าตรงข้ามซึ่งกลับทิศ)
            ny, nz = pts[i][2][0] * sg, pts[i][2][1] * sg  # ทิศที่ผิวด้านนี้หันไป
            sh = 0.55 + 0.45 * max(0.0, ny * LIGHT_N[1] + nz * LIGHT_N[2])  # ความสว่างตามทิศที่ผิวหันเข้าหาแสง
            glColor3f(r * sh, g * sh, b * sh)  # เลือกสีหน้านี้
            (y0, z0), (y1, z1) = pts[i][side], pts[i + 1][side]  # ตำแหน่งขอบของด้านนี้ที่จุด i และจุด i+1
            glVertex3f(x0, y0, z0); glVertex3f(x1, y0, z0); glVertex3f(x1, y1, z1); glVertex3f(x0, y1, z1)  # วาดแผ่นยาวจากซ้าย (x0) ไปขวา (x1)
        for x, k in ((x0, SHADE_W), (x1, SHADE_E)):                       # ขอบข้างของแผ่น  # วนวาดปิดปลายซ้ายและปลายขวาของแผ่น
            glColor3f(r * k, g * k, b * k)  # เลือกสีตามเฉดด้านซ้ายหรือขวา
            glVertex3f(x, pts[i][0][0], pts[i][0][1]); glVertex3f(x, pts[i][1][0], pts[i][1][1])  # สองมุมแรกของแผ่นปิดปลาย
            glVertex3f(x, pts[i + 1][1][0], pts[i + 1][1][1]); glVertex3f(x, pts[i + 1][0][0], pts[i + 1][0][1])  # สองมุมหลังของแผ่นปิดปลาย
    glEnd()  # วาดเสร็จ


def imac(ix, ty, iz, iw, ih, tilt=8.0, lift=0.085):  # สร้างสูตรวาดคอมพิวเตอร์ iMac (ตำแหน่ง ความกว้าง ความสูงจอ มุมเอน ระยะยกจอ)
    """iMac ตามรูปด้านข้าง: จอแผ่นบางเอนไปด้านหลัง (tilt องศา) หลังจอป่องที่ปลายล่าง
    แขนโค้งโลหะจากหลังจอลงมาที่ฐานแบน ฐานยื่นไปด้านหลังและไปใต้จอ (หน้าจอหันไปทาง +Z)
    ix, iz = กึ่งกลางจอ  ty = ผิวโต๊ะ  iw, ih = กว้าง x สูงของแผ่นจอ  lift = ขอบล่างจอสูงจากโต๊ะ"""
    body = (0.88, 0.88, 0.90)  # สีตัวเครื่อง (เงินอ่อน)
    metal = (0.80, 0.80, 0.82)  # สีโลหะของแขนและฐาน
    t_top, t_bot = 0.008, 0.028                        # ความหนาแผ่นจอที่ปลายบน / ปลายล่าง  # ความหนาของจอ: ด้านบนบาง 8 มม. ด้านล่างหนา 28 มม. (หลังจอป่องที่ปลายล่าง)
    hw = iw / 2  # ครึ่งหนึ่งของความกว้างจอ
    th = math.radians(tilt)  # แปลงมุมเอนจากองศาเป็นเรเดียน

    def back_z(y):                                     # ผิวหลังจอ (พิกัดโลคัลของแผ่นจอ)  # ฟังก์ชันย่อย: บอกว่าผิวหลังจอที่ความสูง y อยู่ลึกไปเท่าไร
        return -(t_top + (t_bot - t_top) * (1 - y / ih))  # ไล่ความหนาจากบน (บาง) ถึงล่าง (หนา) ตามสัดส่วน

    def to_world(y, z):                                # โลคัล -> โลก (หมุนจอเอนหลัง tilt องศารอบจุดล่างหน้า)  # ฟังก์ชันย่อย: แปลงตำแหน่งบนตัวจอ ให้เป็นตำแหน่งจริงในห้อง (คำนวณมุมเอน)
        return (ty + lift + y * math.cos(th) + z * math.sin(th),  # ความสูงจริง
                iz - y * math.sin(th) + z * math.cos(th))  # ตำแหน่ง z จริง

    # ---------- ฐาน + แขน (วาดในพิกัดโลก) ----------
    fw, fh, fr = 0.15, 0.012, 0.075                    # ความกว้าง/หนา/รัศมีปลายมนของฐาน (สั้นพอไม่ให้เกินขอบโต๊ะ)  # ขนาดฐาน: กว้าง 15 ซม. หนา 1.2 ซม. ปลายมนรัศมี 7.5 ซม.
    zc = iz - 0.095                                    # จุดกึ่งกลางปลายมนด้านหลัง  # ตำแหน่งกึ่งกลางส่วนปลายมนของฐาน (อยู่หลังจอ)
    cylinder(ix, ty, zc, fr, fh, metal, 28)  # วาดส่วนปลายมนของฐานเป็นแผ่นกลมแบน
    box(ix - fr, ty, zc, ix + fr, ty + fh, iz + 0.10, metal)  # วาดส่วนสี่เหลี่ยมของฐานที่ยื่นไปใต้จอ (ต่อกับส่วนปลายมน)
    ay, az = to_world(0.46 * ih, back_z(0.46 * ih) + 0.010)      # จุดที่แขนยึดหลังจอ  # หาจุดที่แขนไปยึดที่หลังจอ (ที่ 46% ของความสูงจอ)
    p0 = (ty + fh * 0.5, zc - 0.035)  # จุดเริ่มของแขน (โคนแขนที่ฐาน)
    p1 = (p0[0] + 0.22 * (ay - p0[0]), p0[1])           # โค้งแคบๆ ที่โคนแล้วพาดเฉียงขึ้นหาหลังจอ  # จุดควบคุมความโค้ง ทำให้แขนตั้งขึ้นจากฐานก่อนแล้วค่อยเฉียงไปหาจอ
    path = []  # รายการจุดตามเส้นแขน เริ่มว่างเปล่า
    for i in range(17):  # วนสร้างจุด 17 จุดตามเส้นโค้ง
        t = i / 16  # ตำแหน่งตามเส้น 0 ถึง 1
        path.append(((1 - t) ** 2 * p0[0] + 2 * (1 - t) * t * p1[0] + t * t * ay,  # คำนวณความสูงของจุดบนเส้นโค้ง (สูตรเส้นโค้งเบซิเยร์)
                     (1 - t) ** 2 * p0[1] + 2 * (1 - t) * t * p1[1] + t * t * az))  # คำนวณตำแหน่ง z ของจุดบนเส้นโค้ง
    _strip_x(path, 0.009, ix - 0.05, ix + 0.05, metal)  # วาดแขนเป็นแผ่นโลหะบางกว้าง 10 ซม. ตามเส้นโค้งนั้น

    # ---------- แผ่นจอ (พิกัดโลคัล: เอนหลังรอบแกน X ที่ขอบล่างหน้า) ----------
    glPushMatrix()  # เซฟตำแหน่งและมุมปัจจุบันไว้ก่อน
    glTranslatef(ix, ty + lift, iz)  # ย้ายไปที่ขอบล่างของจอ
    glRotatef(-tilt, 1, 0, 0)  # เอนจอไปด้านหลังตามมุม tilt
    r, g, b = body  # แยกสีตัวเครื่องเป็น 3 ค่า
    bt, bb = back_z(ih), back_z(0)  # ตำแหน่งผิวหลังจอที่ขอบบน (bt) และขอบล่าง (bb)
    glBegin(GL_QUADS)  # เริ่มวาดตัวแผ่นจอ
    glColor3f(r * SHADE_S, g * SHADE_S, b * SHADE_S)             # หน้า (+Z)  # เลือกสีด้านหน้าจอ
    glVertex3f(-hw, 0, 0); glVertex3f(hw, 0, 0); glVertex3f(hw, ih, 0); glVertex3f(-hw, ih, 0)  # วาดด้านหน้า
    glColor3f(r * SHADE_N, g * SHADE_N, b * SHADE_N)             # หลัง (-Z) เป็นระนาบเอียงเล็กน้อย  # เลือกสีด้านหลังจอ
    glVertex3f(-hw, 0, bb); glVertex3f(hw, 0, bb); glVertex3f(hw, ih, bt); glVertex3f(-hw, ih, bt)  # วาดด้านหลัง (เอียงเพราะด้านล่างหนากว่าด้านบน)
    glColor3f(r * SHADE_TOP, g * SHADE_TOP, b * SHADE_TOP)       # ขอบบน  # เลือกสีขอบบน
    glVertex3f(-hw, ih, bt); glVertex3f(hw, ih, bt); glVertex3f(hw, ih, 0); glVertex3f(-hw, ih, 0)  # วาดขอบบน
    glColor3f(r * SHADE_BOT, g * SHADE_BOT, b * SHADE_BOT)       # ขอบล่าง  # เลือกสีขอบล่าง
    glVertex3f(-hw, 0, bb); glVertex3f(hw, 0, bb); glVertex3f(hw, 0, 0); glVertex3f(-hw, 0, 0)  # วาดขอบล่าง
    for x, k in ((-hw, SHADE_W), (hw, SHADE_E)):                  # ขอบข้าง  # วนวาดขอบข้างซ้ายและขวา
        glColor3f(r * k, g * k, b * k)  # เลือกสีตามเฉดด้านซ้ายหรือขวา
        glVertex3f(x, 0, bb); glVertex3f(x, 0, 0); glVertex3f(x, ih, 0); glVertex3f(x, ih, bt)  # วาดขอบข้าง (เป็นรูปสี่เหลี่ยมคางหมู)
    glEnd()  # วาดตัวแผ่นจอเสร็จ
    cbox(0, 0.055, 0.0006, iw - 0.03, ih - 0.075, 0.0006, (0.02, 0.02, 0.03), flat=True)   # หน้าจอ  # วาดพื้นจอสีดำเกือบสนิท เว้นขอบ 1.5 ซม. และเว้นคางด้านล่าง
    gquad([(-hw + 0.015, 0.055, 0.0016), (hw - 0.015, 0.055, 0.0016),  # วาดเงาสะท้อนบนจอ สองมุมล่าง
           (hw - 0.015, ih - 0.02, 0.0016), (-hw + 0.015, ih - 0.02, 0.0016)],  # สองมุมบน
          [(0.01, 0.01, 0.015), (0.01, 0.01, 0.015), (0.07, 0.08, 0.11), (0.03, 0.035, 0.05)])   # เงาสะท้อนบางๆ  # สีสี่มุมต่างกัน ด้านบนสว่างฟ้าจาง ๆ ให้ดูเหมือนกระจกสะท้อนแสง
    apple_logo(0.0, 0.027, 0.0, 0.026, facing=1)                  # โลโก้ Apple บนคางหน้าเครื่อง  # แปะโลโก้ Apple ที่คางด้านล่างของหน้าจอ
    glPushMatrix()                                                # โลโก้ด้านหลัง วางตามระนาบหลังที่เอียงนิดๆ  # เซฟตำแหน่งก่อนวางโลโก้ด้านหลัง
    glTranslatef(0.0, ih * 0.62, back_z(ih * 0.62))  # ย้ายไปที่ผิวหลังจอ ที่ 62% ของความสูง
    glRotatef(math.degrees(math.atan((t_bot - t_top) / ih)), 1, 0, 0)  # เอียงให้ขนานกับผิวหลังจอที่เอียงอยู่
    apple_logo(0.0, 0.0, 0.0, 0.060, facing=-1)  # แปะโลโก้ Apple ขนาด 6 ซม. ที่หลังจอ (หันไปด้านหลัง)
    glPopMatrix()  # กลับมายังตำแหน่งที่เซฟไว้ก่อนวางโลโก้หลัง
    glPopMatrix()  # กลับมายังตำแหน่งที่เซฟไว้ก่อนวาดแผ่นจอ


def black_table():  # สร้างสูตรวางโต๊ะผ้าดำพร้อมคอมพิวเตอร์ คีย์บอร์ด เมาส์ และไมค์
    """โต๊ะผ้าดำ 60 x 23.5 inch สูง 29.5 inch + iMac (หน้าจอหันมาทางเก้าอี้ = -Z) + คีย์บอร์ด + เมาส์ 5x2 inch"""
    cx, cz = 2.62, BLACK_TABLE_Z  # ตำแหน่งกึ่งกลางโต๊ะดำ (cz อิงจากค่าตั้งต้นที่ตอนต้นไฟล์ที่ 1)
    ty = 29.5 * INCH  # ความสูงผิวโต๊ะ 29.5 นิ้ว
    cbox(cx, 0, cz, 60 * INCH, ty, 23.5 * INCH, (0.05, 0.05, 0.06), solid=True)  # วาดตัวโต๊ะดำเป็นกล่องทึบ ขนาด 60 x 23.5 นิ้ว และให้เดินชนได้
    glPushMatrix()                                   # เซฟตำแหน่งไว้ก่อน เพื่อเลื่อนของบนโต๊ะทั้งชุดพร้อมกัน  # เริ่มกลุ่มของบนโต๊ะ
    glTranslatef(DESK_SHIFT_X, 0, DESK_SHIFT_Z)      # เลื่อนของทั้งชุด: ซ้าย-ขวา (x) และหน้า-หลัง (z) ให้อยู่กึ่งกลางโต๊ะ  # เลื่อนชุดของบนโต๊ะ
    # ---- ผังบนโต๊ะตามรูปจริง ----
    # คนนั่งอยู่ฝั่งเหนือ (ฝั่งเก้าอี้) หันไปทาง +Z  หน้าจอ iMac หันมาทางเก้าอี้ (-Z) ด้านหลังเครื่อง (โลโก้) หันเข้าห้อง
    # iMac ชิดปลายโต๊ะฝั่งทีวี  คีย์บอร์ดอยู่หน้าจอ  เมาส์อยู่ขวามือ(ทิศตะวันตก)ของคีย์บอร์ด  ไมค์ 2 ตัววางเฉียงขนานกัน
    iw, ih = 25.5 * INCH, 16 * INCH  # ขนาดแผ่นจอ iMac กว้าง 25.5 นิ้ว สูง 16 นิ้ว
    ix, iz = 3.00, 1.58                              # กึ่งกลางจอ (x) / ระนาบหน้าจอ (z)  # ตำแหน่งวางจอ
    glPushMatrix()                                   # หมุน iMac 180 องศารอบแกนตั้งที่จุด (ix, iz)  # เซฟตำแหน่งก่อนหมุน
    glTranslatef(ix, 0, iz)  # ย้ายจุดอ้างอิงไปที่ตำแหน่งจอ
    glRotatef(180, 0, 1, 0)  # หมุน 180 องศา ให้จอหันมาทางเก้าอี้
    glTranslatef(-ix, 0, -iz)  # ย้ายกลับ (สามบรรทัดนี้รวมกันคือ "หมุนอยู่กับที่")
    imac(ix, ty, iz, iw, ih)                         # iMac: จอบางเอนหลัง + แขนโค้ง + ฐานแบน  # วาด iMac
    glPopMatrix()  # กลับไปยังตำแหน่งที่เซฟไว้
    kx, kz = 2.85, 1.37  # ตำแหน่งวางคีย์บอร์ด
    glPushMatrix()                                   # คีย์บอร์ดหมุน 180 ให้แถวสเปซบาร์อยู่ฝั่งคนนั่ง (เหนือ)  # เซฟตำแหน่งก่อนหมุน
    glTranslatef(kx, 0, kz)  # ย้ายจุดอ้างอิงไปที่ตำแหน่งคีย์บอร์ด
    glRotatef(180, 0, 1, 0)  # หมุน 180 องศา
    glTranslatef(-kx, 0, -kz)  # ย้ายกลับ (หมุนอยู่กับที่)
    keyboard(kx, ty, kz)  # วาดคีย์บอร์ดบนผิวโต๊ะ
    glPopMatrix()  # กลับไปยังตำแหน่งที่เซฟไว้
    magic_mouse(2.65, ty, 1.40, 180)                 # Magic Mouse ปลายเมาส์ชี้ไปทางจอ (+Z)  # วางเมาส์ข้างคีย์บอร์ด หมุน 180 องศา
    mic(2.47, ty + 0.031, 1.245, -57)                # ไมค์ 2 ตัว หัวไมค์ชี้ไปทาง +Z เฉียงไปทางทีวี ~33 องศา  # วางไมค์ตัวแรก (ยกสูง 3.1 ซม. ให้พอดีกับรัศมีไมค์) หมุน -57 องศา
    mic(2.26, ty + 0.031, 1.300, -57)  # วางไมค์ตัวที่สอง ขนานกับตัวแรก
    glPopMatrix()                                    # จบกลุ่มของบนโต๊ะ กลับไปตำแหน่งปกติ  # จบการเลื่อน


def tv_stand():  # สร้างสูตรวางทีวีพร้อมขาตั้ง
    """ทีวี 49 x 28 inch ขอบล่างสูง 38 inch ยอดสูง 66 inch
    หน้าจอหันเข้าห้อง (+Z)  เสาขาตั้งอยู่ด้านหลังจอ  ชั้นวางยื่นมาด้านหน้า"""
    cx, pz = 4.05, BLACK_TABLE_Z      # แนวเดียวกับโต๊ะดำ  # ตำแหน่งทีวี (z ตรงกับโต๊ะดำ)
    ty = 38 * INCH  # ความสูงขอบล่างทีวี 38 นิ้ว
    tw, th = 49 * INCH, 28 * INCH  # ความกว้างและความสูงทีวี 49 x 28 นิ้ว
    dark = (0.10, 0.10, 0.11)  # สีดำของตัวทีวีและขาตั้ง
    cbox(cx, 0, pz - 0.05, 23 * INCH, 0.04, 0.55, dark, solid=True)                  # ฐาน  # วาดฐานขาตั้งเป็นแผ่นแบนบนพื้น (เดินชนได้)
    cbox(cx, 0.04, pz - 0.085, 0.05, 66 * INCH - 0.04, 0.04, (0.14, 0.14, 0.15))     # เสา (หลังจอ)  # วาดเสาตั้งสูง 66 นิ้ว อยู่หลังทีวี
    cbox(cx, 0.60, pz + 0.03, 10 * INCH, 0.012, 0.22, dark)                          # ชั้นวาง (หน้าเสา)  # วาดชั้นวางของเล็ก ๆ ยื่นออกมาด้านหน้าเสา
    cbox(cx, ty, pz - 0.035, tw, th, 0.05, dark)                                     # ตัวทีวี  # วาดตัวทีวีเป็นแผ่นกล่องบาง หนา 5 ซม.
    cbox(cx, ty + 0.06, pz - 0.075, 0.60, 0.30, 0.03, (0.18, 0.18, 0.19))            # ฝาหลังจอ (ให้รู้ว่าด้านหลัง)  # วาดกล่องนูนที่หลังทีวี (ส่วนที่ติดกับเสา)
    cbox(cx, ty + 0.02, pz - 0.010, tw - 0.03, th - 0.04, 0.004, (0.015, 0.02, 0.03))  # หน้าจอ (ด้าน +Z)  # วาดพื้นจอทีวีสีดำสนิท เว้นขอบ
    gquad([(cx - tw / 2 + 0.015, ty + 0.02, pz - 0.0075), (cx + tw / 2 - 0.015, ty + 0.02, pz - 0.0075),  # วาดเงาสะท้อนบนจอทีวี สองมุมล่าง
           (cx + tw / 2 - 0.015, ty + th - 0.02, pz - 0.0075), (cx - tw / 2 + 0.015, ty + th - 0.02, pz - 0.0075)],  # สองมุมบน
          [(0.01, 0.01, 0.015), (0.01, 0.01, 0.015), (0.06, 0.07, 0.10), (0.03, 0.035, 0.05)])  # สีสี่มุม ด้านบนสว่างกว่าให้ดูเหมือนกระจกสะท้อน
    COLLIDERS.append((cx - tw / 2, pz - 0.105, cx + tw / 2, pz))  # จดพื้นที่ทีวีไว้ในสมุดสิ่งกีดขวาง (เดินทะลุไม่ได้)


def cabinet_layout():  # สร้างสูตรบอกตำแหน่งบานกระจกเลื่อนของตู้ (ใช้ร่วมกันตอนวาดกรอบและวาดกระจก)
    """ตำแหน่งบานกระจกเลื่อน (x, z_เริ่ม, z_จบ, y_ล่าง, y_บน) ใช้ร่วมกันทั้งตอนวาดกรอบและวาดกระจก
    มี 2 ราง: x=0.485 (หลัง) และ x=0.505 (หน้า)  บานบนเลื่อนเปิดแง้ม 0.28 m  บานล่างเปิดแง้ม 0.18 m"""
    z0 = 0.50  # ตำแหน่งขอบตู้ด้านที่ใกล้ผนังหน้าต่าง
    top = CABINET_H - 0.06  # ระดับขอบบนของบานกระจก (ต่ำกว่าหัวตู้ 6 ซม.)
    return [  # ส่งรายการบานกระจก 4 บานกลับไป แต่ละบานบอก (ตำแหน่ง x, z เริ่ม, z จบ, ขอบล่าง, ขอบบน)
        (0.485, z0 + 0.04, z0 + 0.76, top - 0.86, top),                       # บนซ้าย (ปิด)  # บานบนซ้าย อยู่รางหลัง ปิดสนิท
        (0.505, z0 + 0.68 - 0.28, z0 + 1.40 - 0.28, top - 0.86, top),         # บนขวา (เลื่อนเปิด)  # บานบนขวา อยู่รางหน้า เลื่อนเปิดแง้ม 0.28 เมตร
        (0.485, z0 + 0.04 + 0.18, z0 + 0.76 + 0.18, 0.06, 0.86),              # ล่างซ้าย (เลื่อนเปิด)  # บานล่างซ้าย อยู่รางหลัง เลื่อนเปิดแง้ม 0.18 เมตร
        (0.505, z0 + 0.68, z0 + 1.40, 0.06, 0.86),                            # ล่างขวา (ปิด)  # บานล่างขวา อยู่รางหน้า ปิดสนิท
    ]


def cabinet():  # สร้างสูตรวาดตู้เหล็กพร้อมของข้างใน (ยกเว้นกระจก)
    """ตู้เหล็กกระจกเลื่อน ยาว 1.48 m ชิดผนังตะวันตก  สูง CABINET_H + กล่องขาวด้านบน
    ตัวตู้เป็นโครงกลวง มีชั้นวางและของข้างใน (กระจกวาดแยกใน cabinet_glass)"""
    z0, z1 = 0.50, 0.50 + 1.48  # ขอบตู้สองด้านตามความยาวห้อง (ตู้ยาว 1.48 เมตร)
    h = CABINET_H  # ความสูงตู้ (ค่าตั้งต้นตอนต้นไฟล์ที่ 1)
    steel, inner, shelf = (0.55, 0.57, 0.58), (0.46, 0.48, 0.50), (0.62, 0.64, 0.66)  # สีเหล็กภายนอก สีผนังด้านใน สีชั้นวาง
    COLLIDERS.append((0.02, z0, 0.48, z1))  # จดพื้นที่ตู้ไว้ในสมุดสิ่งกีดขวาง (เดินทะลุไม่ได้)
    box(0.02, 0, z0, 0.045, h, z1, inner)                    # ผนังหลัง  # วาดแผ่นหลังตู้ (ติดผนังห้อง)
    box(0.02, 0, z0, 0.48, h, z0 + 0.03, steel)              # ข้างซ้าย/ขวา  # วาดผนังข้างด้านหนึ่งของตู้
    box(0.02, 0, z1 - 0.03, 0.48, h, z1, steel)  # วาดผนังข้างอีกด้านหนึ่ง
    box(0.02, h - 0.03, z0, 0.48, h, z1, steel)             # ฝาบน  # วาดฝาด้านบนของตู้
    box(0.02, 0, z0, 0.48, 0.06, z1, steel)                 # ฐาน  # วาดพื้นตู้
    box(0.045, 0.86, z0, 0.48, 0.98, z1, steel)             # แผ่นแบ่งช่องบน/ล่าง  # วาดแผ่นกั้นกลางที่แบ่งตู้เป็นช่องบนกับช่องล่าง
    box(0.44, h - 0.06, z0, 0.48, h, z1, steel)            # รางบนด้านหน้า  # วาดรางด้านบนที่บานกระจกเลื่อนวิ่ง
    for y in (0.45, 1.28, 1.56):                            # ชั้นวาง  # วนวางชั้นวาง 3 ชั้น ที่ความสูง 0.45, 1.28, 1.56 เมตร
        box(0.045, y, z0 + 0.03, 0.46, y + 0.02, z1 - 0.03, shelf)  # วาดแผ่นชั้นวางหนา 2 ซม.
    # ของในช่องบน
    box(0.10, 0.98, z0 + 0.10, 0.42, 1.12, z0 + 0.45, (0.95, 0.82, 0.18))   # ของสีเหลือง  # วางของสีเหลืองบนแผ่นแบ่งช่อง
    box(0.10, 0.98, z0 + 0.55, 0.30, 1.20, z0 + 0.75, (0.20, 0.35, 0.70))   # กล่องน้ำเงิน  # วางกล่องสีน้ำเงิน
    box(0.10, 0.98, z0 + 0.90, 0.40, 1.15, z0 + 1.30, (0.90, 0.90, 0.88))   # กล่องขาว  # วางกล่องสีขาว
    box(0.10, 1.30, z0 + 0.15, 0.40, 1.50, z0 + 0.60, (0.93, 0.93, 0.90))   # เอกสาร  # วางปึกเอกสารบนชั้นที่ 2
    box(0.10, 1.30, z0 + 0.80, 0.40, 1.42, z0 + 1.25, (0.55, 0.40, 0.25))   # กล่องกระดาษ  # วางกล่องกระดาษสีน้ำตาลบนชั้นที่ 2
    box(0.10, 1.58, z0 + 0.20, 0.42, 1.78, z0 + 0.80, (0.10, 0.10, 0.11))   # กระเป๋าดำ  # วางกระเป๋าสีดำบนชั้นบนสุด
    # ของในช่องล่าง
    box(0.08, 0.06, z0 + 0.08, 0.44, 0.40, z0 + 0.55, (0.95, 0.60, 0.28))   # ม้วนผ้าส้ม  # วางม้วนผ้าสีส้มที่พื้นตู้
    box(0.08, 0.06, z0 + 0.70, 0.44, 0.30, z0 + 1.20, (0.15, 0.55, 0.30))   # ม้วนผ้าเขียว  # วางม้วนผ้าสีเขียวที่พื้นตู้
    box(0.10, 0.47, z0 + 0.30, 0.40, 0.70, z0 + 1.00, (0.92, 0.88, 0.80))   # กระดาษบนชั้น  # วางกระดาษบนชั้นที่ความสูง 0.45 เมตร
    # กรอบอะลูมิเนียมของบานเลื่อน
    alu, t = (0.74, 0.76, 0.78), 0.025  # สีอะลูมิเนียม และความกว้างกรอบ 2.5 ซม.
    for (px, za, zb, ya, yb) in cabinet_layout():  # วนทีละบานกระจก (ดึงตำแหน่งจากฟังก์ชัน cabinet_layout)
        box(px - 0.006, ya, za, px + 0.006, yb, za + t, alu)  # วาดกรอบด้านหนึ่งของบาน
        box(px - 0.006, ya, zb - t, px + 0.006, yb, zb, alu)  # วาดกรอบด้านตรงข้าม
        box(px - 0.006, ya, za, px + 0.006, ya + t, zb, alu)  # วาดกรอบด้านล่าง
        box(px - 0.006, yb - t, za, px + 0.006, yb, zb, alu)  # วาดกรอบด้านบน
    box(0.04, h, z0 + 0.04, 0.44, h + 0.15, z0 + 1.44, (0.92, 0.92, 0.94))  # กล่องขาวบนตู้  # วางกล่องสีขาวบนหลังตู้ สูง 15 ซม.


def cabinet_glass():  # สร้างสูตรวาดกระจกตู้แบบโปร่งใส
    """วาดกระจกตู้แบบโปร่งใส  ต้องเรียกหลังวาดของทึบทุกอย่างแล้ว"""
    glDepthMask(GL_FALSE)  # ปิดการจดความลึก เพื่อไม่ให้กระจกบังของที่อยู่หลังกระจก
    glEnable(GL_BLEND)  # เปิดโหมดผสมสี (ทำให้โปร่งใสได้)
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)  # ตั้งสูตรผสมสีแบบโปร่งใสมาตรฐาน
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม
    for (px, za, zb, ya, yb) in cabinet_layout():  # วนทีละบานกระจก
        glColor4f(0.72, 0.88, 0.92, GLASS_ALPHA)  # เลือกสีฟ้าอ่อน พร้อมค่าความทึบ (ตัวที่สี่คือความทึบ ตั้งค่าไว้ตอนต้นไฟล์ที่ 1)
        glVertex3f(px, ya, za); glVertex3f(px, ya, zb)  # สองมุมล่างของบาน
        glVertex3f(px, yb, zb); glVertex3f(px, yb, za)  # สองมุมบนของบาน
    glEnd()  # วาดกระจกเสร็จ
    glDisable(GL_BLEND)  # ปิดโหมดผสมสี
    glDepthMask(GL_TRUE)  # เปิดการจดความลึกกลับคืน


def c_stands():  # สร้างสูตรวางขาตั้งไฟ C-stand ทั้ง 7 อัน
    """C-stand 7 อัน เรียงเป็นแถวขนานกับหน้าตู้ (ตามแนวแกน Z) สร้างตามสเปคในรูป
    ฮับขาแต่ละอันสูงไม่เท่ากัน ขาจะได้ซ้อนกันได้เหมือนของจริง"""
    x = 0.95  # ตำแหน่งแนวนอนของแถว (ห่างผนังตะวันตก 0.95 เมตร)
    for i in range(7):  # วนวาง 7 อัน
        c_stand(x, 0.62 + i * 0.10, 0.18 + 0.04 * i)  # วางขาตั้ง ห่างกัน 10 ซม. และฮับขาแต่ละอันสูงขึ้นอันละ 4 ซม. (ขาจะได้ซ้อนกันได้)
    COLLIDERS.append((0.88, 0.55, 1.02, 1.30))  # จดพื้นที่ทั้งแถวไว้ในสมุดสิ่งกีดขวาง


def softboxes():  # สร้างสูตรวางซอฟต์บ็อกซ์ทั้ง 4 ตัว
    """ซอฟต์บ็อกซ์คละแบบ ตามขนาดที่วัดในรูป
    Nanlite ทรงโดมพาราโบลา Ø30 x สูง 25 inch  /  Godox สี่เหลี่ยม หน้า 39 x 27 inch ลึก 18 inch"""
    dome_para(3.25, 0.62, ribs=True)          # Nanlite ซี่ขาว  # วางโดมกลมซี่ขาวตัวที่ 1
    softbox_rect(4.35, 0.55, 8)               # Godox สี่เหลี่ยม  # วางซอฟต์บ็อกซ์สี่เหลี่ยม หมุนเฉียง 8 องศา
    dome_para(5.65, 0.95, ribs=True)          # โดมซี่ขาว  # วางโดมกลมซี่ขาวตัวที่ 2
    softbox_rect(6.65, 0.95, -25)             # Godox สี่เหลี่ยม หมุนเฉียง  # วางซอฟต์บ็อกซ์สี่เหลี่ยม หมุนเฉียง -25 องศา


def office_chair(cx, cz, facing=1):  # สร้างสูตรวาดเก้าอี้สำนักงาน (ตำแหน่ง ทิศที่หัน)
    """เก้าอี้หนังผู้บริหารพนักสูง ตามรูป: ที่นั่ง 18 inch หนา 2.5 inch สูง 18.5 inch
    ที่วางแขนสูง 26.5 inch  ยอดพนักสูง 39 inch  พนักหนา 4 inch เอนหลังเล็กน้อย
    พนักหุ้มหนังแบ่งช่องมีกรอบดำ  เบาะแบ่งช่อง  แขนดำโค้งเป็นห่วง  ขา 5 แฉกมีล้อ
    (facing=1 หันไปทาง -Z)"""
    brown, brown2 = (0.45, 0.24, 0.12), (0.41, 0.21, 0.10)  # สีหนังสีน้ำตาล 2 เฉดสลับกัน
    blk, pad = (0.08, 0.08, 0.09), (0.13, 0.13, 0.14)  # สีดำของโครง และสีของแผ่นรองแขน
    steel = (0.62, 0.64, 0.67)  # สีเหล็ก
    COLLIDERS.append((cx - 0.30, cz - 0.30, cx + 0.30, cz + 0.30))  # จดพื้นที่เก้าอี้ 60 x 60 ซม. ไว้ในสมุดสิ่งกีดขวาง
    glPushMatrix()  # เซฟตำแหน่งและมุมปัจจุบันไว้ก่อน
    glTranslatef(cx, 0, cz)  # ย้ายจุดอ้างอิงไปที่ตำแหน่งวางเก้าอี้
    if facing < 0:  # ถ้าให้เก้าอี้หันไปอีกทาง
        glRotatef(180, 0, 1, 0)  # หมุนเก้าอี้ 180 องศา
    sw = 18 * INCH  # ความกว้างเบาะนั่ง 18 นิ้ว
    sh = 18.5 * INCH  # ความสูงเบาะนั่ง 18.5 นิ้ว
    h2 = sw / 2  # ครึ่งหนึ่งของความกว้างเบาะ
    ya = 26.5 * INCH                                              # ความสูงที่วางแขน  # ความสูงที่วางแขน 26.5 นิ้ว

    # ---------- เบาะนั่ง: แกนดำ + หนัง 4 ช่องขวางความลึก + ขอบดำข้างเบาะ ----------
    box(-h2 + 0.01, sh - 0.0635, -h2, h2 - 0.01, sh - 0.02, h2, blk)  # วาดแกนเบาะสีดำ (ไส้ใน)
    box(-h2 - 0.005, sh - 0.075, -h2 - 0.005, h2 + 0.005, sh - 0.0635, h2 + 0.005, blk)   # ถาดรองเบาะ  # วาดถาดรองใต้เบาะ ใหญ่กว่าเบาะเล็กน้อย
    gap = 0.008  # ร่องระหว่างแผ่นหนัง 8 มม.
    band = (sw - 3 * gap) / 4  # ความกว้างของหนังแต่ละช่อง (4 ช่อง มีร่อง 3 ร่อง)
    for i in range(4):  # วนทำหนังทีละช่อง
        za = -h2 + i * (band + gap)  # ตำแหน่งเริ่มของช่องนี้
        top = sh - 0.012 if i == 0 else sh                        # ขอบหน้าเบาะลาดลงเล็กน้อย  # ช่องแรก (ขอบหน้า) เตี้ยลง 1.2 ซม. เพื่อให้ขอบเบาะลาด ที่เหลือสูงเท่ากัน
        box(-h2, sh - 0.0635, za, h2, top, za + band, brown if i % 2 == 0 else brown2)  # วาดหนังช่องนี้ ช่องคู่สีหนึ่ง ช่องคี่อีกสีหนึ่ง
    box(-h2 - 0.006, sh - 0.0635, -h2, -h2 + 0.006, sh - 0.004, h2, blk)               # ขอบดำซ้าย/ขวา  # วาดขอบดำข้างซ้ายของเบาะ
    box(h2 - 0.006, sh - 0.0635, -h2, h2 + 0.006, sh - 0.004, h2, blk)  # วาดขอบดำข้างขวาของเบาะ

    # ---------- กลไกใต้เบาะ + ก้านปรับ ----------
    box(-0.12, sh - 0.125, -0.12, 0.12, sh - 0.075, 0.12, blk)  # วาดกล่องกลไกใต้เบาะ
    box(-0.26, sh - 0.095, -0.03, 0.26, sh - 0.075, 0.03, blk)                         # คานยึดแขนทั้งสองข้าง  # วาดคานที่ยึดที่วางแขนซ้ายและขวา
    tube((0.10, sh - 0.105, 0.0), (0.20, sh - 0.115, -0.10), 0.006, blk, 8)            # ก้านปรับระดับ  # วาดก้านปรับระดับเก้าอี้
    ball(0.20, sh - 0.115, -0.10, 0.011, blk, 8, 6)  # วาดลูกบิดที่ปลายก้าน

    # ---------- ที่วางแขน: ห่วงโค้งสีดำ + แผ่นรองแขนบุนวม ----------
    for sx in (-0.262, 0.262):  # วนทำที่วางแขนสองข้าง (ซ้ายและขวา)
        box(sx - 0.012, sh - 0.095, -0.17, sx + 0.012, sh - 0.075, 0.12, blk)          # ราวล่างใต้เบาะ  # วาดราวล่างใต้เบาะ
        tube((sx, sh - 0.085, 0.10), (sx, sh + 0.05, 0.115), 0.013, blk, 10)           # เสาหลังโค้งออกเล็กน้อย  # วาดเสาหลังช่วงล่าง
        tube((sx, sh + 0.05, 0.115), (sx, ya - 0.02, 0.09), 0.013, blk, 10)  # วาดเสาหลังช่วงบน (โค้งเข้าหาที่วางแขน)
        ball(sx, sh + 0.05, 0.115, 0.013, blk, 10, 6)  # วาดลูกบอลที่ข้อต่อ ให้รอยต่อเรียบ
        tube((sx, sh - 0.085, -0.16), (sx, sh + 0.06, -0.175), 0.013, blk, 10)         # เสาหน้า  # วาดเสาหน้าช่วงล่าง
        tube((sx, sh + 0.06, -0.175), (sx, ya - 0.02, -0.19), 0.013, blk, 10)  # วาดเสาหน้าช่วงบน
        ball(sx, sh + 0.06, -0.175, 0.013, blk, 10, 6)  # วาดลูกบอลที่ข้อต่อ
        box(sx - 0.026, ya - 0.02, -0.19, sx + 0.026, ya + 0.022, 0.15, pad)           # แผ่นรองแขน  # วาดแผ่นรองแขนบุนวม
        cylinder(sx, ya - 0.02, -0.19, 0.026, 0.042, pad, 14)                          # ปลายหน้ามน  # วาดปลายด้านหน้าของแผ่นรองแขนให้มน
        box(sx - 0.020, ya + 0.022, -0.17, sx + 0.020, ya + 0.026, 0.12, (0.18, 0.18, 0.19))  # วาดแผ่นสีเทาบาง ๆ ด้านบนที่วางแขน

    # ---------- พนักพิง: เอนหลัง 8° หมุนรอบจุดหลังเบาะ ----------
    zp = h2 - 0.03  # จุดที่พนักยึดกับเบาะ (ด้านหลังเบาะ)
    glPushMatrix()  # เซฟตำแหน่งก่อนวาดพนัก
    glTranslatef(0, sh, zp)  # ย้ายจุดอ้างอิงไปที่โคนพนัก
    glRotatef(8, 1, 0, 0)  # เอนพนักไปด้านหลัง 8 องศา
    BH = 0.526                                                    # ความสูงพนักตามแนวพนัก (ยอดรวม ~39 inch)  # ความสูงพนัก 52.6 ซม.
    hw = 0.245                                                    # ครึ่งความกว้างพนัก  # ครึ่งความกว้างพนัก 24.5 ซม.
    box(-0.035, -0.10, -0.03, 0.035, 0.06, 0.03, blk)             # แขนยึดพนักกับกลไกเบาะ  # วาดแขนที่ยึดพนักกับกลไกใต้เบาะ
    box(-hw, 0.03, 0.02, hw, BH, 0.05, blk)                       # แผ่นหลังสีดำ  # วาดแผ่นหลังพนักสีดำ
    box(-hw, 0.03, -0.05, hw, 0.05, 0.05, blk)                    # กรอบล่าง  # วาดกรอบล่างของพนัก
    box(-hw, BH - 0.026, -0.05, hw, BH, 0.05, blk)                # กรอบบน  # วาดกรอบบนของพนัก
    box(-hw, 0.03, -0.05, -hw + 0.024, BH, 0.05, blk)             # กรอบข้าง  # วาดกรอบข้างซ้ายของพนัก
    box(hw - 0.024, 0.03, -0.05, hw, BH, 0.05, blk)  # วาดกรอบข้างขวาของพนัก
    iw = hw - 0.024  # ครึ่งความกว้างของพื้นที่หนังด้านใน (หักกรอบออก)
    y_a, y_b = 0.05, BH - 0.026  # ขอบล่างและขอบบนของพื้นที่หนังบนพนัก
    n, g = 5, 0.010  # แบ่งหนังพนักเป็น 5 ช่อง ร่องกว้าง 1 ซม.
    ph = (y_b - y_a - (n - 1) * g) / n  # ความสูงของหนังแต่ละช่อง
    for i in range(n):                                            # หนังบุนวม 5 ช่อง  # วนทำหนังทีละช่อง
        ya_i = y_a + i * (ph + g)  # ตำแหน่งขอบล่างของช่องนี้
        box(-iw, ya_i, -0.055, iw, ya_i + ph, 0.02, brown if i % 2 == 0 else brown2)  # วาดหนังช่องนี้ สลับสีน้ำตาลสองเฉด
    box(-0.004, y_a, -0.057, 0.004, y_b, -0.040, blk)             # ตะเข็บกลางแนวตั้ง  # วาดตะเข็บสีดำกลางพนักตามแนวตั้ง
    glPopMatrix()  # กลับไปยังตำแหน่งที่เซฟไว้ก่อนวาดพนัก

    # ---------- แกนยกระดับ + ขา 5 แฉก + ล้อ ----------
    cylinder(0, 0.14, 0, 0.036, 0.17, blk, 14)                    # กระบอกล่าง  # วาดกระบอกโช้คล่าง (ท่อนใหญ่)
    cylinder(0, 0.31, 0, 0.026, sh - 0.125 - 0.31, (0.30, 0.30, 0.32), 14)   # แกนบน  # วาดแกนโช้คท่อนบน (ท่อนเล็กกว่า) ขึ้นไปถึงใต้เบาะ
    cylinder(0, 0.31, 0, 0.032, 0.015, steel, 14)                 # ปลอกต่อ  # วาดปลอกโลหะตรงรอยต่อของสองท่อน
    cylinder(0, 0.105, 0, 0.050, 0.040, blk, 14)                  # ฮับกลางขา  # วาดฮับกลางที่ขาทั้ง 5 มาต่อกัน
    for k in range(5):  # วนทำขา 5 แฉก
        a = math.radians(18 + 72 * k)  # มุมของขาแต่ละแฉก ห่างกัน 72 องศา (360 หาร 5) แล้วแปลงเป็นเรเดียน
        ca, sa = math.cos(a), math.sin(a)  # ค่า cos และ sin ของมุมนั้น
        tip = (0.33 * ca, 0.085, 0.33 * sa)  # ตำแหน่งปลายขา ห่างจากกลาง 33 ซม.
        tube((0.0, 0.125, 0.0), tip, 0.021, blk, 8)  # วาดขาเป็นท่อจากฮับไปถึงปลาย
        ball(tip[0], tip[1], tip[2], 0.021, blk, 8, 6)  # วาดลูกบอลที่ปลายขา ให้ปลายมน
        cylinder(tip[0], 0.060, tip[2], 0.009, 0.040, steel, 8)   # แกนล้อ  # วาดแกนล้อ
        box(tip[0] - 0.012, 0.050, tip[2] - 0.020, tip[0] + 0.012, 0.062, tip[2] + 0.020, blk)  # วาดโครงยึดล้อ
        glPushMatrix()                                            # ตัวล้อ 2 ข้างของแกน  # เซฟตำแหน่งก่อนวาดล้อ
        glTranslatef(tip[0], 0, tip[2])  # ย้ายไปที่ปลายขา
        glRotatef(-math.degrees(a), 0, 1, 0)  # หมุนให้ล้อหันตามทิศของขา
        for dz in (-0.014, 0.014):  # วนทำล้อสองข้างของแกน
            ball(0.0, 0.026, dz, 0.026, (0.05, 0.05, 0.06), 10, 6)  # วาดล้อเป็นลูกบอลสีดำ
        glPopMatrix()  # กลับไปยังตำแหน่งที่เซฟไว้ก่อนวาดล้อ
    glPopMatrix()  # กลับไปยังตำแหน่งที่เซฟไว้ตอนต้นฟังก์ชัน


STOOL_STACK_N = 5          # จำนวนสตูลต่อ 1 กอง  # จำนวนสตูลที่ซ้อนกันในแต่ละกอง
STOOL_PITCH = 0.14         # ระยะห่างแนวตั้งของสตูลแต่ละตัวในกอง (เมตร)  # ระยะห่างแนวตั้งของสตูลแต่ละตัวในกอง 14 ซม.
STOOL_STACK_POS = [        # ตำแหน่งกอง (x, z) 3 กอง เรียงชิดผนังตะวันตก (ฝั่งไวท์บอร์ด) จากมุมประตูมาทางหน้าต่าง  # รายการตำแหน่งกองสตูล
    (0.30, D - 0.30), (0.30, D - 0.82), (0.30, D - 1.34),  # 3 กอง ห่างกันกองละ 52 ซม. เรียงชิดผนังตะวันตก เริ่มจากมุมใกล้ประตู
]


def stool(cx, y_off, cz, dots=False):  # ประกาศสูตร "สร้างสตูลเหล็ก 1 ตัว" ต้องบอกตำแหน่ง cx, cz, ความสูงที่ยกขึ้น y_off และว่าจะให้มีรูที่นั่งไหม (dots)
    """สตูลเหล็กกลมสีขาว (แบบรูปอ้างอิง): ที่นั่ง Ø32 cm เจาะรู ขาท่อ 4 ขากางออก ปลายขามียางรอง สูง 45 cm
    y_off = ยกทั้งตัวขึ้นจากพื้น (ใช้ตอนซ้อน)"""  # คำอธิบายของสูตรนี้ (ไว้ให้คนอ่าน) บอกว่าที่นั่งกว้าง 32 ซม. สูง 45 ซม. y_off ใช้ตอนวางซ้อนกัน
    wht = (0.93, 0.93, 0.94)  # ตั้งชื่อ wht เป็นสีขาวนวลของตัวสตูล
    cap = (0.62, 0.63, 0.65)  # ตั้งชื่อ cap เป็นสีเทาของยางรองปลายขา
    hs = 0.45  # ความสูงสตูล 0.45 เมตร (45 ซม.)
    cylinder(cx, y_off + hs - 0.04, cz, 0.16, 0.04, wht, 28)  # วาดที่นั่งเป็นแผ่นทรงกระบอกแบนๆ รัศมี 16 ซม. หนา 4 ซม. (ตัวเลข 28 = ความละเอียดความกลม)
    if dots:  # ถ้าสั่งให้มีรู ก็ทำส่วนข้างล่างนี้
        yy = y_off + hs + 0.002  # ความสูงที่จะวาดรู คือเหนือผิวที่นั่งนิดเดียว (ไม่งั้นจะมองไม่เห็น)
        dc = (0.55, 0.56, 0.58)  # สีของรู เป็นเทาเข้มกว่าที่นั่ง
        step, sz = 0.026, 0.0065  # step = ระยะห่างระหว่างรู 2.6 ซม., sz = ครึ่งหนึ่งของขนาดรู
        for i in range(-5, 6):  # วนไล่แถวตามแนวซ้าย-ขวา จากแถว -5 ถึง 5
            for j in range(-5, 6):  # ในแต่ละแถว วนไล่ตามแนวหน้า-หลัง จาก -5 ถึง 5 (รวมเป็นตาราง 11x11 จุด)
                dx, dz = i * step, j * step  # คำนวณว่าจุดนี้อยู่ห่างจากกลางที่นั่งเท่าไร
                if math.hypot(dx, dz) > 0.125 or abs(dx) < 0.012 or abs(dz) < 0.012:  # ถ้าจุดอยู่นอกวงกลมที่นั่ง หรืออยู่บนเส้นกากบาทกลาง (เว้นไว้ไม่เจาะ)
                    continue  # ข้ามจุดนี้ ไปจุดต่อไปเลย
                gquad([(cx + dx - sz, yy, cz + dz - sz), (cx + dx + sz, yy, cz + dz - sz),  # วาดรูเล็กๆ เป็นสี่เหลี่ยม: ระบุมุมที่ 1 และ 2
                       (cx + dx + sz, yy, cz + dz + sz), (cx + dx - sz, yy, cz + dz + sz)], [dc] * 4)  # มุมที่ 3 และ 4 แล้วระบุสีรูให้ทั้ง 4 มุมเป็นสีเดียวกัน
    for k in range(4):  # ทำขา 4 ขา วนซ้ำ 4 รอบ (k = 0,1,2,3)
        a = math.radians(45 + 90 * k)  # มุมของขาแต่ละขา: 45°, 135°, 225°, 315° (กระจายรอบที่นั่งเท่าๆ กัน)
        ca, sa = math.cos(a), math.sin(a)  # แปลงมุมเป็นทิศทางซ้าย-ขวา (ca) และหน้า-หลัง (sa)
        p0 = (cx + 0.135 * ca, y_off + hs - 0.03, cz + 0.135 * sa)  # จุดเริ่มต้นของขา: ใต้ที่นั่ง
        p1 = (cx + 0.160 * ca, y_off + hs - 0.07, cz + 0.160 * sa)  # จุดโค้งงอของขา: ต่ำลงและออกไปด้านนอกนิดหน่อย
        p2 = (cx + 0.230 * ca, y_off + 0.045, cz + 0.230 * sa)  # ปลายขา: ใกล้พื้น และกางออกไปไกลที่สุด
        tube(p0, p1, 0.0125, wht, 8)  # วาดท่อสั้นๆ จากใต้ที่นั่งไปจุดโค้ง (รัศมีท่อ 1.25 ซม.)
        ball(p1[0], p1[1], p1[2], 0.0125, wht, 8, 6)  # วาดลูกบอลเล็กตรงจุดโค้ง ให้ข้อต่อดูกลมเนียน ไม่เป็นเหลี่ยม
        tube(p1, p2, 0.0125, wht, 8)  # วาดท่อยาวจากจุดโค้งลงไปถึงปลายขา
        cylinder(p2[0], y_off, p2[2], 0.0145, 0.045, cap, 8)  # วาดยางรองสีเทาที่ปลายขา แตะพื้น


def stool_stack(cx, cz, n=5):  # ประกาศสูตร "สตูลวางซ้อนกันเป็นตั้ง" n = จำนวนตัว (ถ้าไม่บอกจะใช้ 5)
    """สตูลซ้อนกัน n ตัว (ตัวบนสวมขาครอบที่นั่งตัวล่าง)"""  # คำอธิบาย: ตัวบนสวมลงบนตัวล่าง
    for k in range(n):  # วนซ้ำตามจำนวนสตูล (k = ลำดับตัวที่ 0,1,2,...)
        stool(cx, k * STOOL_PITCH, cz, dots=True)  # สร้างสตูลหนึ่งตัว ยกสูงขึ้นทีละ STOOL_PITCH (ระยะซ้อนที่ตั้งไว้ที่อื่น) และให้มีรูที่นั่ง
    COLLIDERS.append((cx - 0.26, cz - 0.26, cx + 0.26, cz + 0.26))  # บันทึก "กรอบที่เดินทะลุไม่ได้" ขนาดประมาณ 52x52 ซม. ไว้ในรายการสิ่งกีดขวาง


def bar_stool(cx, cz, yaw=0.0):  # ประกาศสูตร "สตูลบาร์" ต้องบอกตำแหน่ง และ yaw = องศาที่หมุนรอบตัว (ไม่บอกคือ 0)
    """สตูลบาร์เปลือกพลาสติกขาว + ขาไม้โอ๊ค 4 ขากางออก + ที่พักเท้าเหล็กดำ (แบบ About A Stool)
    ที่นั่งสูง ~65 cm  พนักโค้งอยู่ด้าน +Z (ชิดผนังประตู)  yaw = หมุนรอบแกนตั้ง (องศา)"""  # คำอธิบายรูปร่างสตูล: เบาะพลาสติกขาว ขาไม้ ที่พักเท้าเหล็กดำ สูงราว 65 ซม.
    COLLIDERS.append((cx - 0.27, cz - 0.27, cx + 0.27, cz + 0.27))  # บันทึกกรอบสิ่งกีดขวางของสตูลตัวนี้ (ประมาณ 54x54 ซม.)
    white, oak, blk = (0.93, 0.94, 0.97), (0.80, 0.62, 0.38), (0.05, 0.05, 0.06)  # ตั้งชื่อสี 3 สี: ขาว (เปลือก), สีไม้โอ๊ค (ขา), ดำ (ที่พักเท้า)
    rx, rz, y_c = 0.235, 0.205, 0.625  # ขนาดที่นั่งรูปวงรี: ครึ่งกว้าง 23.5 ซม., ครึ่งลึก 20.5 ซม. และความสูงของที่นั่ง 62.5 ซม.
    seg, rings = 56, 12  # ความละเอียดการวาดเปลือก: แบ่งรอบวง 56 ช่อง และแบ่งจากกลางไปขอบ 12 วง (ยิ่งมากยิ่งเนียน)
    ld = math.sqrt(sum(v * v for v in LIGHT_DIR))  # วัดความยาวของลูกศรบอกทิศแสง (เตรียมปรับให้เป็นความยาว 1)
    L = tuple(v / ld for v in LIGHT_DIR)  # ได้ทิศทางแสงที่ปรับขนาดแล้ว ไว้ใช้คำนวณว่าตรงไหนสว่าง ตรงไหนมืด

    def P(a, t, dy=0.0):  # สูตรย่อย: หา "ตำแหน่งจริง" ของจุดหนึ่งบนผิวเปลือก a = มุมรอบ, t = ระยะจากกลางไปขอบ (0 ถึง 1), dy = ยกขึ้น/ลงเพิ่ม
        """(ท้องเบาะเว้า พนักยกขึ้นด้านหลังแบบนุ่ม)"""  # (หมายเหตุเดิมในโค้ด) ท้องเบาะเว้าลง พนักด้านหลังยกสูงขึ้นนุ่มๆ
        back = max(0.0, math.sin(a)) ** 2  # ตัวเลขบอกว่าจุดนี้อยู่ด้านหลังมากแค่ไหน (ด้านหน้า = 0, ด้านหลังสุด = 1)
        y = y_c + 0.03 * t ** 2 + 0.11 * back * t ** 3 + dy  # คำนวณความสูง: ขอบยกขึ้นเล็กน้อยทำให้เบาะเว้า และด้านหลังยกสูงอีกเป็นพนักพิง
        return (rx * t * math.cos(a), y, rz * t * math.sin(a))  # ส่งตำแหน่ง (ซ้าย-ขวา, สูง, หน้า-หลัง) กลับไปให้ผู้เรียก

    def shade(a, t, sign=1.0):  # สูตรย่อย: คำนวณ "ความสว่าง" ของผิวแต่ละจุด เพื่อให้ดูโค้งนูนเรียบเนียน
        """เฉดต่อจุด (smooth shading) จากเวกเตอร์ตั้งฉากจริง"""  # (หมายเหตุเดิม) ใช้ทิศที่ผิวหันไปจริงๆ มาคำนวณแสงเงา
        t = min(max(t, 0.03), 1.0)  # กันค่า t ไม่ให้ต่ำเกิน 0.03 หรือสูงเกิน 1 (ตรงกลางเป๊ะคำนวณไม่ได้)
        e = 1e-3  # ระยะก้าวเล็กจิ๋ว 0.001 ใช้ดูว่าผิวลาดไปทางไหน
        pa0, pa1 = P(a - e, t), P(a + e, t)  # หาจุดสองจุดที่ขยับไปซ้าย-ขวาตามแนวรอบวงนิดเดียว
        pt0, pt1 = P(a, max(t - e, 0.0)), P(a, min(t + e, 1.0))  # หาจุดสองจุดที่ขยับเข้า-ออกตามแนวกลางไปขอบนิดเดียว
        u = [pa1[j] - pa0[j] for j in range(3)]  # ลูกศรเส้นที่ 1 ที่แตะบนผิว (ตามแนวรอบวง)
        v = [pt1[j] - pt0[j] for j in range(3)]  # ลูกศรเส้นที่ 2 ที่แตะบนผิว (ตามแนวกลางไปขอบ)
        n = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]]  # หาลูกศรที่ "ชี้ตั้งฉากออกจากผิว" จากลูกศรสองเส้นนั้น (เรียกว่า cross product)
        nl = math.sqrt(sum(c * c for c in n)) or 1.0  # วัดความยาวลูกศรนั้น (ถ้าได้ 0 ใช้ 1 แทนกันหารด้วยศูนย์)
        n = [sign * c / nl for c in n]  # ปรับให้ยาว 1 และกลับทิศถ้า sign เป็นลบ
        if n[1] < 0:  # ถ้าลูกศรชี้ลงพื้น
            n = [-c for c in n]  # กลับให้ชี้ขึ้นแทน (ให้ผิวหันหาแสงจากด้านบน)
        return 0.62 + 0.38 * max(0.0, n[0] * L[0] + n[1] * L[1] + n[2] * L[2])  # ความสว่างอยู่ระหว่าง 0.62 (มืดสุด) ถึง 1.0 (สว่างสุด) ขึ้นกับว่าผิวหันเข้าหาแสงแค่ไหน

    def vtx(a, t, dy=0.0, k=1.0):  # สูตรย่อย: "วางมุมหนึ่งมุม" ของแผ่นเปลือก พร้อมกำหนดสีที่เหมาะกับแสง (k = ตัวคูณความมืดเพิ่ม)
        s = shade(a, t) * k  # ความสว่างของมุมนี้ คูณตัวปรับความมืด
        glColor3f(white[0] * s, white[1] * s, white[2] * s)  # ตั้งสีขาวที่ปรับความสว่างแล้ว
        glVertex3f(*P(a, t, dy))  # ปักมุมนี้ลงไปที่ตำแหน่งที่คำนวณได้

    glPushMatrix()  # "จำตำแหน่งเดิมไว้" ก่อนจะขยับ/หมุนจุดวาด (เหมือนบันทึกเกม)
    glTranslatef(cx, 0, cz)  # ย้ายจุดวาดไปยืนที่ตำแหน่งของสตูลบนพื้น จากนี้ไปทุกอย่างวาดสัมพันธ์กับจุดนี้
    glRotatef(yaw, 0, 1, 0)  # หมุนจุดวาดรอบแกนตั้งตามองศา yaw เพื่อให้สตูลหันไปทิศที่ต้องการ
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม (ทุก 4 มุมที่ระบุ = 1 แผ่น)
    for i in range(seg):  # วนไล่ทีละ "ช่อง" รอบวงของเบาะ
        a0, a1 = 2 * math.pi * i / seg, 2 * math.pi * (i + 1) / seg  # มุมเริ่มต้นและมุมสิ้นสุดของช่องนี้
        for k in range(rings):  # ในแต่ละช่อง วนไล่ทีละ "วง" จากกลางออกไปขอบ
            t0, t1 = k / rings, (k + 1) / rings  # ระยะของวงใน (t0) และวงนอก (t1)
            for (a, t) in ((a0, t0), (a1, t0), (a1, t1), (a0, t1)):  # ไล่ 4 มุมของแผ่นสี่เหลี่ยมเล็กๆ แผ่นหนึ่งบนผิวด้านบน
                vtx(a, t)  # วางมุมนั้น (ผิวบน)
            for (a, t) in ((a0, t0), (a0, t1), (a1, t1), (a1, t0)):  # ไล่ 4 มุมเหมือนเดิมแต่สลับลำดับ เพื่อทำผิวด้านล่าง
                vtx(a, t, -0.018, 0.62)  # วางมุมนั้นต่ำลง 1.8 ซม. (ความหนาเปลือก) และทำให้มืดลงเพราะอยู่ใต้เบาะ
        for (a, dy) in ((a0, 0.0), (a1, 0.0), (a1, -0.018), (a0, -0.018)):  # ทำ "ขอบ" ของเปลือก คือแผ่นแนวตั้งที่ปิดระหว่างผิวบนและล่าง
            vtx(a, 1.0, dy, 0.92)  # วางมุมที่ริมสุด (t = 1) ให้สีเกือบสว่างสุด
    glEnd()  # จบการวาดแผ่นสี่เหลี่ยมทั้งหมดของตัวเปลือก
    legs = []  # เตรียมรายการว่างไว้ เก็บจุดบนขาแต่ละขา เอาไว้ต่อที่พักเท้า
    for sx in (-1, 1):  # วนสองฝั่งซ้าย (-1) และขวา (1)
        for sz in (-1, 1):  # วนสองฝั่งหน้า (-1) และหลัง (1) รวมเป็นขา 4 ขา
            top = (sx * 0.150, 0.612, sz * 0.110)  # จุดบนของขา: ติดใต้เบาะ
            bot = (sx * 0.255, 0.0, sz * (0.185 if sz < 0 else 0.250))  # จุดล่างของขา: ที่พื้น กางออกไปด้านนอก (ขาหลังกางมากกว่าขาหน้านิดหน่อย)
            tube(top, bot, 0.020, oak, 14)  # วาดขาไม้เป็นท่อเอียงจากใต้เบาะลงพื้น รัศมี 2 ซม.
            f = (0.612 - 0.26) / 0.612  # สัดส่วนความสูงที่จะติดที่พักเท้า (ที่ความสูง 26 ซม. จากพื้น)
            legs.append(tuple(top[j] + (bot[j] - top[j]) * f for j in range(3)))  # คำนวณตำแหน่งบนขาตรงจุดนั้น แล้วเก็บเข้ารายการ
    for (i, j) in ((0, 1), (1, 3), (3, 2), (2, 0)):  # เลือกขาทีละคู่ที่อยู่ติดกัน เพื่อต่อท่อเป็นสี่เหลี่ยมรอบขาทั้งสี่
        tube(legs[i], legs[j], 0.006, blk, 10)  # วาดท่อเหล็กสีดำบางๆ เชื่อมสองขา (เป็นที่พักเท้า)
    glPopMatrix()  # "กลับไปตำแหน่งเดิม" ที่จำไว้ตอนแรก เพื่อไม่ให้การย้าย/หมุนไปกระทบของชิ้นอื่น


def stools():  # ประกาศสูตร "วางสตูลทั้งหมดในห้อง"
    # สตูลบาร์ใกล้ประตู + กระเป๋าดำ
    bar_stool(5.85, 8.55, 0)  # วางสตูลบาร์ตัวที่ 1 ที่ x=5.85, z=8.55 ไม่หมุน
    bar_stool(5.30, 8.55, -6)  # วางสตูลบาร์ตัวที่ 2 ข้างๆ หมุนเอียงไป 6 องศาให้ดูเป็นธรรมชาติ
    # สตูลเหล็กสีขาววางซ้อนกันที่มุมตะวันตกเฉียงใต้ (ชิดผนังตะวันตก x=0 และผนังประตู z=D)
    for (x, z) in STOOL_STACK_POS:  # วนไล่ทุกตำแหน่งที่ตั้งค่าไว้ว่าจะวางสตูลเหล็กซ้อน
        stool_stack(x, z, STOOL_STACK_N)  # สร้างตั้งสตูลซ้อนกันที่ตำแหน่งนั้น ตามจำนวนที่ตั้งไว้


LIGHT_N = tuple(v / math.sqrt(sum(c * c for c in LIGHT_DIR)) for v in LIGHT_DIR)  # ทิศทางแสงที่ปรับให้ยาว 1 (เก็บไว้ใช้ทั้งไฟล์ ต่างจากตัวที่คำนวณในสตูลบาร์ซึ่งใช้เฉพาะในนั้น)


def _xs(a):  # สูตรย่อย: บอกความสว่างของผิวทรงกระบอกนอนที่มุม a รอบแกน
    """เฉดสีของผิวทรงกระบอกแนวแกน X ที่มุม a (ใช้ทำ smooth shading)"""  # คำอธิบาย: คำนวณแสงเงาของท่อนนอน ให้ดูกลมเนียน
    return 0.60 + 0.40 * max(0.0, math.sin(a) * LIGHT_N[1] + math.cos(a) * LIGHT_N[2])  # ความสว่าง 0.60 (มืดสุด) ถึง 1.0 (สว่างสุด) ขึ้นกับว่าด้านนั้นหันเข้าหาแสงแค่ไหน


def xcyl(x0, x1, cy, cz, r, col, seg=40):  # ประกาศสูตร "ทรงกระบอกนอนไปตามแนวซ้าย-ขวา" จาก x0 ถึง x1 รัศมี r สี col
    """ทรงกระบอกวางนอนตามแนวแกน X (ผิวข้าง) จาก x0 ถึง x1 จุดศูนย์กลางที่ (cy, cz)"""  # คำอธิบาย: วาดเฉพาะผิวข้าง ไม่รวมหัวท้าย
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม
    for i in range(seg):  # วนไล่ทีละช่องรอบท่อ (ยิ่ง seg มากยิ่งกลม)
        a0, a1 = 2 * math.pi * i / seg, 2 * math.pi * (i + 1) / seg  # มุมเริ่มและมุมจบของช่องนี้
        for (x, a) in ((x0, a0), (x1, a0), (x1, a1), (x0, a1)):  # ไล่ 4 มุมของแผ่นที่ปิดผิวข้างช่องนี้ (สองมุมที่หัวท่อ สองมุมที่ท้ายท่อ)
            s = _xs(a)  # หาความสว่างของมุมนี้
            glColor3f(col[0] * s, col[1] * s, col[2] * s)  # ตั้งสีโดยคูณกับความสว่าง
            glVertex3f(x, cy + r * math.sin(a), cz + r * math.cos(a))  # ปักมุมที่ตำแหน่งบนเส้นรอบวงของท่อ
    glEnd()  # จบการวาด


def xring(x, cy, cz, r0, r1, col, seg=40):  # ประกาศสูตร "วงแหวนแบน" ที่ระนาบ x รัศมีในคือ r0 รัศมีนอกคือ r1
    """วงแหวน (หน้าตัดปลายม้วน) ที่ระนาบ x"""  # คำอธิบาย: ใช้ทำหน้าตัดปลายม้วนกระดาษ
    glColor3f(*col)  # ตั้งสีเดียวให้ทั้งวง
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม
    for i in range(seg):  # วนไล่ทีละช่องรอบวง
        a0, a1 = 2 * math.pi * i / seg, 2 * math.pi * (i + 1) / seg  # มุมเริ่มและมุมจบของช่องนี้
        for (r, a) in ((r0, a0), (r1, a0), (r1, a1), (r0, a1)):  # ไล่ 4 มุมของแผ่นช่องนี้ (วงในสองมุม วงนอกสองมุม)
            glVertex3f(x, cy + r * math.sin(a), cz + r * math.cos(a))  # ปักมุมที่ตำแหน่งบนวงนั้น
    glEnd()  # จบการวาด


def paper_roll(x0, x1, cy, cz, r, paper, tail=0.0):  # ประกาศสูตร "ม้วนฉากกระดาษ" วางนอน จาก x0 ถึง x1 รัศมี r สีกระดาษ paper และ tail คือความยาวกระดาษที่คลี่ออกมาบนพื้น
    """ม้วนฉากกระดาษถ่ายภาพ (seamless paper) วางนอนตามแนว X
    มีแกนกระดาษแข็งโผล่ออกหัวท้าย  ปลายม้วนมีขอบกระดาษเป็นเส้นเงา  หน้าตัดเห็นชั้นกระดาษเป็นวงๆ
    tail > 0 = มีแผ่นกระดาษคลี่ออกมาบนพื้นด้านหน้ายาว tail เมตร"""  # คำอธิบายของม้วนกระดาษ: มีแกนกระดาษแข็งโผล่หัวท้าย มีเส้นขอบกระดาษ หน้าตัดเห็นชั้นๆ และอาจมีแผ่นคลี่ออกมา
    core_r, core_ext = 0.038, 0.035  # รัศมีแกนกระดาษแข็ง 3.8 ซม. และความยาวที่แกนโผล่พ้นหัวท้ายม้วน 3.5 ซม.
    card, hole = (0.72, 0.58, 0.40), (0.06, 0.05, 0.05)  # สีแกนกระดาษแข็ง (น้ำตาลอ่อน) และสีรูกลางแกน (เกือบดำ)
    xcyl(x0, x1, cy, cz, r, paper)  # วาดตัวม้วนกระดาษเป็นทรงกระบอกนอน
    a_e = 1.15  # มุมที่เป็นตำแหน่งขอบปลายกระดาษที่พันอยู่รอบม้วน
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม สำหรับเส้นขอบกระดาษ
    glColor3f(paper[0] * 0.70, paper[1] * 0.70, paper[2] * 0.70)  # ใช้สีกระดาษแต่มืดลง 30% ให้เห็นเป็นเส้นเงา
    for (aa, bb) in ((a_e, a_e + 0.05),):  # ทำเส้นขอบ 1 เส้น กว้างช่วงมุมเล็กน้อย
        for (x, a) in ((x0, aa), (x1, aa), (x1, bb), (x0, bb)):  # ไล่ 4 มุมของแถบเส้นขอบ ตลอดความยาวม้วน
            glVertex3f(x, cy + (r + 0.0006) * math.sin(a), cz + (r + 0.0006) * math.cos(a))  # ปักมุมให้ลอยเหนือผิวม้วนนิดเดียว (0.6 มม.) เพื่อไม่ให้ภาพกระพริบทับกัน
    glEnd()  # จบการวาดเส้นขอบ
    nr = 7  # จำนวนวงที่จะแบ่งหน้าตัดปลายม้วน ให้เห็นเป็นชั้นๆ
    for x, k in ((x0, 0.82), (x1, 0.94)):  # ทำหน้าตัดทั้งสองหัวม้วน (หัวซ้ายมืดกว่า 0.82 หัวขวาสว่างกว่า 0.94)
        for j in range(nr):  # วนทีละวงจากในออกนอก
            ra = core_r + (r - core_r) * j / nr  # รัศมีขอบในของวงนี้
            rb = core_r + (r - core_r) * (j + 1) / nr  # รัศมีขอบนอกของวงนี้
            s = k * (1.0 if j % 2 == 0 else 0.90)  # วงเลขคู่สีปกติ วงเลขคี่มืดลง 10% ทำให้เป็นริ้วสลับชั้นกระดาษ
            xring(x + (-0.0004 if x == x0 else 0.0004), cy, cz, ra, rb, (paper[0] * s, paper[1] * s, paper[2] * s))  # วาดวงแหวนชั้นนี้ ขยับออกจากปลายม้วนเล็กน้อย (0.4 มม.) กันภาพทับกัน
    xcyl(x0 - core_ext, x1 + core_ext, cy, cz, core_r, card, 20)  # วาดแกนกระดาษแข็งตรงกลาง ยาวกว่าม้วนทั้งสองด้าน
    for x, k in ((x0 - core_ext, 0.78), (x1 + core_ext, 0.90)):  # ทำหน้าตัดปลายแกนทั้งสองด้าน (ซ้ายมืดกว่า)
        xring(x + (-0.0004 if x < x0 else 0.0004), cy, cz, 0.031, core_r, (card[0] * k, card[1] * k, card[2] * k), 20)  # วาดขอบหนาของแกนกระดาษแข็ง (วงแหวนสีน้ำตาลอ่อน)
        xring(x + (0.0006 if x < x0 else -0.0006), cy, cz, 0.0, 0.031, hole, 20)  # วาดรูกลางแกน เป็นวงกลมสีเกือบดำ
    if tail > 0:  # ถ้ามีกระดาษคลี่ออกมาบนพื้น
        y = 0.003  # ความสูงแผ่นกระดาษ สูงจากพื้น 3 มม. (กันทับกับพื้นแล้วภาพกระพริบ)
        zs, ze = cz, cz + tail  # จุดเริ่มของแผ่น (ที่ม้วน) และจุดปลายแผ่น (ไกลออกมา tail เมตร)
        gquad([(x0, y, zs), (x1, y, zs), (x1, y, ze - 0.05), (x0, y, ze - 0.05)],  # วาดแผ่นกระดาษแบนบนพื้น: ระบุมุมทั้ง 4 (เว้นปลาย 5 ซม. ไว้ทำส่วนงอ)
              [(paper[0] * 0.97, paper[1] * 0.97, paper[2] * 0.97)] * 4)  # สีแผ่นกระดาษ มืดกว่าม้วนนิดเดียว (97%) ใช้สีเดียวทั้ง 4 มุม
        gquad([(x0, y, ze - 0.05), (x1, y, ze - 0.05), (x1, y + 0.014, ze), (x0, y + 0.014, ze)],  # วาดแผ่นเล็กต่อจากปลาย ที่ลาดสูงขึ้น 1.4 ซม.
              [(paper[0] * 0.90, paper[1] * 0.90, paper[2] * 0.90)] * 4)       # สีมืดลงเหลือ 90% ให้ดูเป็นส่วนที่งอขึ้น (ปลายกระดาษงอขึ้นเล็กน้อย)


def portable_ac(cx, cz):  # ประกาศสูตร "เครื่องปรับอากาศแบบเคลื่อนย้ายได้" ต้องบอกตำแหน่ง cx, cz
    """เครื่องปรับอากาศแบบตั้งพื้น (portable) หน้าเครื่องหันเข้าห้อง (-X) มีล้อ ช่องดูดลม ช่องเป่าลมแบบมีครีบ
    แผงควบคุมด้านบน (หน้าจอ LED + ปุ่ม + ช่องลมบน) มือจับข้างเครื่อง ช่องดูระดับน้ำ"""  # คำอธิบาย: หน้าเครื่องหันเข้าห้อง มีล้อ ช่องลม แผงควบคุม มือจับ ช่องดูระดับน้ำ
    sx, sz = 0.28, 0.45  # ขนาดตัวเครื่องบนพื้น: ลึก 28 ซม. (ซ้าย-ขวา) x กว้าง 45 ซม. (หน้า-หลัง)
    xf, xb = cx - sx / 2, cx + sx / 2  # ตำแหน่งด้านหน้า (xf) และด้านหลัง (xb) ของเครื่อง
    z0, z1 = cz - sz / 2, cz + sz / 2  # ตำแหน่งขอบด้านหนึ่ง (z0) และอีกด้านหนึ่ง (z1) ของเครื่อง
    cream, grey = (0.92, 0.91, 0.86), (0.40, 0.41, 0.44)  # สีครีมของตัวเครื่อง และสีเทาเข้มของฝาบน
    dark, slat = (0.09, 0.09, 0.10), (0.58, 0.59, 0.61)  # สีเกือบดำ (ช่องลม/ล้อ) และสีเทาอ่อน (ซี่กริล)
    for dx in (-0.09, 0.09):  # วนสองตำแหน่งซ้าย-ขวาของล้อ
        for dz in (-0.17, 0.17):  # วนสองตำแหน่งหน้า-หลังของล้อ (รวมเป็นล้อ 4 ล้อ)
            cylinder(cx + dx, 0.0, cz + dz, 0.022, 0.04, dark, 10)  # วาดล้อเป็นทรงกระบอกเล็กสีดำ รัศมี 2.2 ซม. สูง 4 ซม.
    box(xf + 0.008, 0.035, z0 + 0.008, xb - 0.008, 0.075, z1 - 0.008, (0.55, 0.55, 0.58))   # วาดฐานแบนๆ สีเทาเหนือล้อ (เล็กกว่าตัวเครื่องเล็กน้อย)
    box(xf, 0.075, z0, xb, 0.60, z1, cream, solid=True)                                    # วาดตัวเครื่องหลักเป็นกล่องสีครีม สูงตั้งแต่ 7.5 ซม. ถึง 60 ซม.
    box(xf - 0.006, 0.60, z0 - 0.006, xb + 0.006, 0.628, z1 + 0.006, grey)                 # วาดฝาบนสีเทา ใหญ่กว่าตัวเครื่องนิดเดียวให้ดูเป็นขอบ
    ty = 0.6285  # ความสูงผิวหน้าฝาบน (ใช้วางแผงควบคุม)

    def rect(xa, xb_, za, zb, col, y=ty + 0.0005):  # สูตรย่อย: วาดสี่เหลี่ยมแบนบนฝาบนเครื่อง ระบุขอบทั้ง 4 ด้านและสี
        gquad([(xa, y, za), (xb_, y, za), (xb_, y, zb), (xa, y, zb)], [col] * 4)  # วาดแผ่นสี่เหลี่ยมสีเดียว ลอยเหนือฝาบนนิดเดียวไม่ให้ภาพทับกัน

    rect(xf + 0.03, xf + 0.085, cz - 0.14, cz + 0.14, (0.05, 0.06, 0.07), ty)             # วาดหน้าจอแสดงผลเป็นแผ่นดำ
    led = (0.95, 0.30, 0.18)  # สีส้มแดงของตัวเลขไฟ LED
    for zc in (cz - 0.090, cz - 0.055):                                                    # วนสองตำแหน่งสำหรับตัวเลข 2 หลักบนจอ
        rect(xf + 0.071, xf + 0.075, zc - 0.009, zc + 0.009, led)  # ขีดแนวนอนบนสุดของเลข (เลขแบบ 7 ขีด)
        rect(xf + 0.0565, xf + 0.0585, zc - 0.009, zc + 0.009, led)  # ขีดแนวนอนกลาง
        rect(xf + 0.040, xf + 0.044, zc - 0.009, zc + 0.009, led)  # ขีดแนวนอนล่างสุด
        rect(xf + 0.040, xf + 0.075, zc - 0.009, zc - 0.0065, led)  # ขีดแนวตั้งด้านหนึ่ง
        rect(xf + 0.040, xf + 0.075, zc + 0.0065, zc + 0.009, led)  # ขีดแนวตั้งอีกด้านหนึ่ง
    for k, c in enumerate(((0.2, 0.9, 0.3), (0.2, 0.6, 0.95), (0.95, 0.75, 0.2))):         # วนสร้างไฟสถานะ 3 ดวง: เขียว ฟ้า เหลือง
        rect(xf + 0.045, xf + 0.052, cz + 0.02 + 0.035 * k, cz + 0.032 + 0.035 * k, c)  # วาดไฟสีเล็กๆ เรียงข้างกันห่างกัน 3.5 ซม.
    for k in range(5):                                                                      # วนสร้างปุ่มกด 5 ปุ่ม
        cylinder(xf + 0.115, ty, cz - 0.12 + 0.06 * k, 0.011, 0.004, (0.78, 0.79, 0.80), 14)  # วาดปุ่มกลมแบนสีเทาอ่อน เรียงห่างกัน 6 ซม.
    rect(xf + 0.15, xb - 0.03, cz - 0.15, cz + 0.15, dark, ty)                              # วาดช่องลมออกด้านบน เป็นแผ่นสีดำ
    for k in range(7):  # วนสร้างซี่กริลครอบช่องลม 7 ซี่
        x = xf + 0.16 + k * 0.0145  # ตำแหน่งของซี่แต่ละซี่ ห่างกัน 1.45 ซม.
        box(x, ty, cz - 0.15, x + 0.006, ty + 0.006, cz + 0.15, slat)  # วาดซี่กริลเป็นแท่งบางๆ สีเทาอ่อน พาดตามความกว้างช่องลม
    # ---- ด้านหน้า (หันเข้าห้อง) ----
    xp = xf - 0.001  # ระนาบหน้าเครื่อง ลอยออกมา 1 มม. ให้ลายไม่จมในตัวเครื่อง
    gquad([(xp, 0.47, cz - 0.17), (xp, 0.47, cz + 0.17), (xp, 0.57, cz + 0.17), (xp, 0.57, cz - 0.17)], [dark] * 4)  # วาดช่องเป่าลมออกด้านหน้า เป็นแผ่นสีดำ (สูง 47-57 ซม.)
    for k in range(5):                                                                      # วนสร้างครีบช่องเป่าลม 5 ซี่
        yy = 0.485 + k * 0.017  # ความสูงของครีบแต่ละซี่ ห่างกัน 1.7 ซม.
        box(xf - 0.012, yy, cz - 0.17, xf, yy + 0.007, cz + 0.17, cream)  # วาดครีบเป็นแท่งสีครีมบางๆ ยื่นออกมาจากหน้าเครื่อง
    gquad([(xp, 0.14, cz - 0.18), (xp, 0.14, cz + 0.18), (xp, 0.40, cz + 0.18), (xp, 0.40, cz - 0.18)], [dark] * 4)  # วาดช่องดูดลมด้านล่าง เป็นแผ่นสีดำ (สูง 14-40 ซม.)
    for k in range(15):                                                                     # วนสร้างซี่กริลดูดลม 15 ซี่
        yy = 0.145 + k * 0.017  # ความสูงของซี่แต่ละซี่ ห่างกัน 1.7 ซม.
        box(xf - 0.006, yy, cz - 0.18, xf, yy + 0.007, cz + 0.18, slat)  # วาดซี่เป็นแท่งสีเทาอ่อน พาดตามความกว้างช่องดูดลม
    for dz in (-0.06, 0.06):  # วนสองตำแหน่งสำหรับแท่งแนวตั้งค้ำกริล
        box(xf - 0.007, 0.14, cz + dz - 0.003, xf, 0.40, cz + dz + 0.003, cream)  # วาดแท่งตั้งสีครีมคร่อมซี่กริล ให้ดูแข็งแรง
    box(xf - 0.008, 0.40, cz - 0.19, xf, 0.41, cz + 0.19, cream)                            # วาดกรอบกริลด้านบน
    box(xf - 0.008, 0.13, cz - 0.19, xf, 0.14, cz + 0.19, cream)  # วาดกรอบกริลด้านล่าง
    box(xf - 0.008, 0.14, cz - 0.19, xf, 0.40, cz - 0.18, cream)  # วาดกรอบกริลด้านข้างหนึ่ง
    box(xf - 0.008, 0.14, cz + 0.18, xf, 0.40, cz + 0.19, cream)  # วาดกรอบกริลด้านข้างอีกด้าน
    gquad([(xp, 0.423, cz - 0.07), (xp, 0.423, cz + 0.07), (xp, 0.447, cz + 0.07), (xp, 0.447, cz - 0.07)],  # วาดป้ายชื่อแบรนด์ เป็นแถบสีเทาอ่อนแบนๆ กว้าง 14 ซม.
          [(0.76, 0.78, 0.81)] * 4)                                                         # กำหนดสีป้ายเป็นเทาอ่อนทั้ง 4 มุม
    for (za, zb) in ((-0.055, -0.030), (-0.022, 0.010), (0.018, 0.050)):  # วนสร้างขีดสีเข้มสามขีดบนป้าย เป็นสัญลักษณ์แทนตัวอักษรแบรนด์
        gquad([(xp - 0.0005, 0.431, cz + za), (xp - 0.0005, 0.431, cz + zb),  # วาดขีดแต่ละขีดเป็นแถบเล็กๆ: มุมที่ 1 และ 2
               (xp - 0.0005, 0.439, cz + zb), (xp - 0.0005, 0.439, cz + za)], [(0.20, 0.21, 0.24)] * 4)  # มุมที่ 3 และ 4 พร้อมสีเทาเข้ม ลอยเหนือป้ายนิดเดียว
    gquad([(xp, 0.09, cz + 0.08), (xp, 0.09, cz + 0.17), (xp, 0.12, cz + 0.17), (xp, 0.12, cz + 0.08)],  # วาดช่องดูระดับน้ำ เป็นแถบเล็กๆ ที่มุมล่างของเครื่อง
          [(0.35, 0.60, 0.80)] * 4)                                                         # สีฟ้า ให้ดูเป็นหน้าต่างใสเห็นน้ำ
    box(xf - 0.015, 0.095, cz - 0.16, xf, 0.115, cz - 0.13, dark)                           # วาดจุกระบายน้ำเป็นกล่องเล็กสีดำ ยื่นออกมาด้านหน้า
    for zz in (z0 - 0.001, z1 + 0.001):                                                     # วนทำมือจับสองข้างของเครื่อง (ซ้ายและขวา)
        gquad([(cx - 0.07, 0.40, zz), (cx + 0.07, 0.40, zz), (cx + 0.07, 0.47, zz), (cx - 0.07, 0.47, zz)],  # วาดช่องมือจับ เป็นแผ่นสีดำบนข้างเครื่อง กว้าง 14 ซม. สูง 7 ซม.
              [(0.12, 0.12, 0.13)] * 4)  # สีดำเกือบสนิท
        gquad([(cx - 0.07, 0.397, zz), (cx + 0.07, 0.397, zz), (cx + 0.07, 0.40, zz), (cx - 0.07, 0.40, zz)],  # วาดแถบเล็กๆ ใต้ช่องมือจับ ให้ดูเป็นขอบที่นิ้วเกาะได้
              [(0.70, 0.70, 0.68)] * 4)  # สีเทาอ่อน


def corner_stuff():  # ประกาศสูตร "วางของที่มุมห้อง" ได้แก่ แอร์และม้วนกระดาษ
    """เครื่องปรับอากาศแบบตั้งพื้น + ม้วนฉากกระดาษ 3 ม้วน ที่มุมตะวันออกเฉียงเหนือ"""  # คำอธิบาย: ของทั้งหมดอยู่มุมตะวันออกเฉียงเหนือ
    portable_ac(W - 0.31, 0.85)  # วางแอร์ ห่างจากผนังด้านตะวันออก 31 ซม. (W คือความกว้างห้อง) และอยู่ที่ z=0.85
    # ม้วนฉากกระดาษ กว้าง 1.36 m วางนอนชิดผนังหน้าต่าง: ขาว + ชมพู อยู่ล่าง, คราฟท์วางพาดด้านบนร่องกลาง
    COLLIDERS.append((5.64, 0.0, 7.16, 0.40))  # บันทึกกรอบสิ่งกีดขวางของกองม้วนกระดาษ (กว้าง 1.52 ม. ลึก 40 ซม.)
    paper_roll(5.70, 7.06, 0.070, 0.085, 0.070, (0.95, 0.95, 0.94))  # ม้วนที่ 1 สีขาว วางบนพื้น (ล่างสุด)
    paper_roll(5.70, 7.06, 0.065, 0.225, 0.065, (0.95, 0.55, 0.65), tail=0.40)  # ม้วนที่ 2 สีชมพู วางข้างม้วนขาว และมีกระดาษคลี่ออกมาบนพื้น 40 ซม.
    paper_roll(5.74, 7.10, 0.180, 0.155, 0.060, (0.74, 0.57, 0.36))  # ม้วนที่ 3 สีน้ำตาลคราฟท์ วางพาดอยู่ด้านบนร่องระหว่างสองม้วนล่าง



# =====================================================================
# 5.5) พัดลมระบายอากาศ (ใบพัดหมุนได้) + สายไฟตามผนัง
# =====================================================================
FAN_XS = (W / 2 - 0.175,)   # ตำแหน่งกลางพัดลมในแนวซ้าย-ขวา: ตัวเดียว อยู่ซ้ายเสากลาง 17.5 ซม. (เป็นรายการเผื่ออยากเพิ่มตัวอื่นภายหลัง)
FAN_CY = 2.31                    # ความสูงกลางพัดลม 2.31 เมตร จากพื้น (อยู่กลางช่องแสงด้านบน)
FAN_RPS = 1.5                    # ความเร็วใบพัด 1.5 รอบต่อวินาที (แก้เลขนี้ได้ ยิ่งมากยิ่งเร็ว ใส่ 0 คือหยุดนิ่ง)
 
 
def disc_z(cx, cy, z, r, c, seg=28):  # ประกาศสูตร "วาดแผ่นวงกลมแบน" จุดกลาง (cx, cy) ที่ระยะ z รัศมี r สี c และ seg = จำนวนช่องที่ใช้ประกอบเป็นวงกลม
    """แผ่นวงกลมแบนในระนาบ XY (หันหน้าเข้าห้อง)"""  # คำอธิบาย: แผ่นกลมแบน หันหน้าเข้าหาในห้อง
    glColor3f(*c)  # ตั้งสีที่จะใช้วาด
    glBegin(GL_TRIANGLE_FAN)  # เริ่มวาดแบบ "พัดสามเหลี่ยม" คือสามเหลี่ยมหลายอันที่มีจุดยอดร่วมกันที่ศูนย์กลาง
    glVertex3f(cx, cy, z)  # ปักจุดแรกที่ศูนย์กลางวงกลม
    for i in range(seg + 1):  # วนไล่ทีละจุดรอบวงกลม (บวก 1 เพื่อให้วงปิดสนิท)
        a = 2 * math.pi * i / seg  # มุมของจุดนี้ (วนครบ 360 องศาเมื่อ i ถึง seg)
        glVertex3f(cx + r * math.cos(a), cy + r * math.sin(a), z)  # ปักจุดบนเส้นรอบวง ตามมุมที่คำนวณ
    glEnd()  # จบการวาด
 
 
def cable(pts, r=0.008, col=(0.05, 0.05, 0.06), seg=6):  # ประกาศสูตร "วาดสายไฟ" ผ่านจุดต่างๆ ใน pts รัศมีสาย r สี col (ถ้าไม่บอก ใช้สีดำ) seg = ความละเอียดความกลม
    """สายไฟต่อเนื่องผ่านหลายจุด (ท่อกลมระหว่างจุด + ลูกบอลเล็กที่ข้อต่อให้เนียน)"""  # คำอธิบาย: ท่อกลมต่อกัน พร้อมลูกบอลเล็กตรงมุมให้เนียน
    for p, q in zip(pts[:-1], pts[1:]):  # จับจุดเป็นคู่ติดกัน (จุดที่ 1 กับ 2, จุดที่ 2 กับ 3, ...) แล้วทำทีละคู่
        tube(p, q, r, col, seg)  # วาดท่อกลมเชื่อมสองจุดนั้น
    for p in pts[1:-1]:  # วนไล่ทุกจุดที่อยู่ "ตรงกลาง" (ไม่รวมจุดแรกและจุดสุดท้าย)
        ball(p[0], p[1], p[2], r * 1.05, col, 6, 4)  # วาดลูกบอลเล็กที่จุดนั้น ขนาดโตกว่าสายนิดหน่อย เพื่อปิดรอยต่อตรงมุมให้ดูเรียบ
 
 
def wall_clip(x, y, z, axis, col=(0.80, 0.80, 0.78)):  # ประกาศสูตร "วาดที่รัดสายไฟ" ติดผนัง ที่ตำแหน่ง (x, y, z) axis บอกว่าผนังหันไปทางไหน col = สี (ไม่บอกใช้สีขาวอมเทา)
    """ที่รัดสายไฟเล็กๆ ติดผนัง axis = 'x' (ผนังเหนือ/ใต้) หรือ 'z' (ผนังตะวันตก/ตะวันออก)"""  # คำอธิบาย: axis เป็น 'x' สำหรับผนังหน้าต่าง/ประตู หรือ 'z' สำหรับผนังตะวันตก/ตะวันออก
    s = 0.012  # ความหนาของที่รัดสาย (ครึ่งหนึ่ง) 1.2 ซม. ที่ยื่นออกจากผนัง
    if axis == 'x':  # ถ้าเป็นผนังที่ยาวไปตามแนวซ้าย-ขวา (ผนังหน้าต่าง/ผนังประตู)
        box(x - s, y - 0.020, z - 0.018, x + s, y + 0.020, z + 0.018, col)  # วาดกล่องเล็กๆ สูง 4 ซม. กว้าง 3.6 ซม. ที่ตำแหน่งนั้น
    else:  # ถ้าไม่ใช่ (ผนังตะวันตก/ตะวันออก)
        box(x - 0.018, y - 0.020, z - s, x + 0.018, y + 0.020, z + s, col)  # วาดกล่องเล็กๆ แบบเดียวกัน แต่หมุนให้ตรงกับทิศผนัง
 
 
def exhaust_fan(cx):  # ประกาศสูตร "วาดส่วนที่อยู่นิ่งของพัดลม" ที่ฝังทะลุผนังหนา 12 ซม. เห็นได้ทั้งฝั่งในห้องและฝั่งทางเดิน (cx = ตำแหน่งกลางแนวซ้าย-ขวา)
    """ตัวเรือนสี่เหลี่ยมฝังในผนัง มีท่อลมกลมทะลุ + ตะแกรงทั้งสองหน้า
    ใบพัดวาดแยกใน fan_blades() ที่กลางความหนาผนัง เพื่อให้หมุนได้และเห็นจากทั้งสองฝั่ง"""  # คำอธิบาย: ส่วนที่ไม่เคลื่อนไหวถูกวาดครั้งเดียวแล้วจำไว้ ส่วนใบพัดวาดทุกเฟรม
    cy = FAN_CY  # ความสูงกลางพัดลม
    zr = D - 0.002  # ระนาบหน้าพัดลมฝั่งในห้อง (ยื่นออกมา 2 มม. กันภาพทับกันจนกะพริบ)
    zc = FZ + 0.002  # ระนาบหน้าพัดลมฝั่งทางเดิน (ยื่นออกมา 2 มม. เช่นกัน)
    hw, ho = 0.15, 0.108  # ครึ่งความกว้างตัวเรือนสี่เหลี่ยม 15 ซม. และรัศมีช่องลมกลม 10.8 ซม.
    plate = (0.90, 0.90, 0.88)  # สีตัวเรือนพัดลม (ขาวอมเทา)
    grille = (0.88, 0.88, 0.86)  # สีตะแกรงหน้า (ขาวอมเทา)
    box(cx - hw, cy - hw, D, cx - ho, cy + hw, FZ, plate)  # แท่งกรอบด้านซ้าย ยาวทะลุผนังจากฝั่งในห้อง (z = D) ถึงฝั่งทางเดิน (z = FZ)
    box(cx + ho, cy - hw, D, cx + hw, cy + hw, FZ, plate)  # แท่งกรอบด้านขวา ทะลุผนังเช่นกัน
    box(cx - ho, cy + ho, D, cx + ho, cy + hw, FZ, plate)  # แท่งกรอบด้านบน ทะลุผนังเช่นกัน
    box(cx - ho, cy - hw, D, cx + ho, cy - ho, FZ, plate)  # แท่งกรอบด้านล่าง ทะลุผนังเช่นกัน (ได้ช่องลมสี่เหลี่ยมกว้าง 21.6 ซม. ตรงกลาง)
    glColor3f(0.12, 0.12, 0.13)  # ตั้งสีเทาเข้มสำหรับผนังด้านในของท่อลม
    glBegin(GL_QUAD_STRIP)  # เริ่มวาดแถบสี่เหลี่ยมต่อเนื่อง ใช้ทำผนังท่อกลมที่ทะลุผนังห้อง
    for i in range(33):  # วนไล่ 33 จุดรอบวง (เกิน 1 จุดเพื่อให้วงปิดสนิท)
        a = 2 * math.pi * i / 32  # มุมของจุดนี้ (ครบ 360 องศาเมื่อ i = 32)
        glVertex3f(cx + ho * math.cos(a), cy + ho * math.sin(a), D)  # จุดบนขอบท่อ ปลายฝั่งในห้อง
        glVertex3f(cx + ho * math.cos(a), cy + ho * math.sin(a), FZ)  # จุดบนขอบท่อ ปลายฝั่งทางเดิน (คู่กับจุดบน)
    glEnd()  # จบการวาดผนังท่อ
    for zf in (zr, zc):  # วนทำหน้าแผงปิดมุมที่ว่างระหว่างวงกลมกับช่องสี่เหลี่ยม ทีละฝั่ง (ในห้อง และทางเดิน)
        glColor3f(*plate)  # ตั้งสีเดียวกับตัวเรือน
        glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยมเล็กๆ รอบวง
        for i in range(32):  # วนทีละช่วงรอบวง 32 ช่วง (45 องศาตรงกับทุก 4 ช่วง จึงตรงมุมสี่เหลี่ยมพอดี)
            a0, a1 = 2 * math.pi * i / 32, 2 * math.pi * (i + 1) / 32  # มุมเริ่มและมุมจบของช่วงนี้
            q0 = ho / max(abs(math.cos(a0)), abs(math.sin(a0)))  # ระยะจากกลางถึงขอบช่องสี่เหลี่ยมในทิศมุม a0
            q1 = ho / max(abs(math.cos(a1)), abs(math.sin(a1)))  # ระยะจากกลางถึงขอบช่องสี่เหลี่ยมในทิศมุม a1
            glVertex3f(cx + ho * math.cos(a0), cy + ho * math.sin(a0), zf)  # มุมที่ 1: บนวงกลม ทิศ a0
            glVertex3f(cx + q0 * math.cos(a0), cy + q0 * math.sin(a0), zf)  # มุมที่ 2: บนขอบสี่เหลี่ยม ทิศ a0
            glVertex3f(cx + q1 * math.cos(a1), cy + q1 * math.sin(a1), zf)  # มุมที่ 3: บนขอบสี่เหลี่ยม ทิศ a1
            glVertex3f(cx + ho * math.cos(a1), cy + ho * math.sin(a1), zf)  # มุมที่ 4: บนวงกลม ทิศ a1
        glEnd()  # จบการวาดแผ่นปิดมุมของหน้านี้
    for zf, sg in ((zr, -1.0), (zc, 1.0)):  # วนทำตะแกรงหน้าทีละฝั่ง (sg = ทิศที่ยื่นออกจากผนัง ในห้อง -1 ทางเดิน +1)
        zg = zf + sg * 0.010  # ตะแกรงลอยออกมาจากหน้าแผงอีก 1 ซม.
        for r in (0.108, 0.070):  # ทำวงแหวนตะแกรง 2 วง: วงนอก (รัศมี 10.8 ซม.) และวงใน (7 ซม.)
            glColor3f(*grille)  # ตั้งสีตะแกรง
            glBegin(GL_QUAD_STRIP)  # เริ่มวาดแถบสี่เหลี่ยมต่อเนื่องเป็นวงแหวน
            for i in range(33):  # วนไล่ 33 จุดรอบวง
                a = 2 * math.pi * i / 32  # มุมของจุดนี้
                for rr in (r - 0.003, r + 0.003):  # ปักสองจุดต่อมุม คือขอบในและขอบนอกของวงแหวน (หนา 6 มม.)
                    glVertex3f(cx + rr * math.cos(a), cy + rr * math.sin(a), zg)  # ปักจุดบนวงแหวน
            glEnd()  # จบวงแหวนนี้
        box(cx - ho, cy - 0.0035, zg - 0.002, cx + ho, cy + 0.0035, zg + 0.002, grille)  # แท่งบางแนวนอนตัดผ่านกลาง (เส้นแนวนอนของกากบาท)
        box(cx - 0.0035, cy - ho, zg - 0.002, cx + 0.0035, cy + ho, zg + 0.002, grille)  # แท่งบางแนวตั้งตัดผ่านกลาง (เส้นแนวตั้งของกากบาท)
    # สายไฟพัดลม: จากมุมบนของเรือนฝั่งในห้อง -> ไต่ขึ้นตามเสากลาง -> ต่อเข้าสายหลักที่พาดใต้คาน
    zf = D - 0.067  # ระยะห่างจากผนังของสายส่วนที่ไต่ขึ้น (ยื่นออกมาหน้าเสาเล็กน้อยจะได้ไม่จมในเสา)
    s = 1.0 if cx < W / 2 else -1.0  # ทิศไปหาเสากลาง: พัดลมอยู่ซ้ายเสากลางได้ +1 อยู่ขวาได้ -1
    xc = W / 2 - s * 0.010  # ตำแหน่งสายที่ไต่ขึ้นเสา: เยื้องจากกลางเสา 1 ซม.
    cable([(cx + s * 0.11, cy + 0.13, D - 0.012), (xc, cy + 0.13, zf), (xc, 2.605, zf),  # วาดสายไฟ ผ่านจุด: มุมบนของเรือน -> ไปที่เสากลาง -> ไต่ขึ้นตามเสาจนถึงเหนือกรอบกระจก
           (xc, 2.64, D - 0.018), (xc, 2.65, D - 0.015)], 0.004, (0.05, 0.05, 0.06))  # -> เข้าชิดผนังและต่อกับสายหลัก ใช้สายเล็ก (รัศมี 4 มม.) สีดำ


def fan_blades(angle_deg, cx):  # ประกาศสูตร "วาดใบพัด" 1 ตัว โดยต้องบอกว่าตอนนี้ใบพัดหมุนไปกี่องศา และอยู่ที่ตำแหน่ง cx ไหน
    """ใบพัดหมุน — วาดทุกเฟรมนอก display list"""  # คำอธิบาย: ใบพัดต้องวาดใหม่ทุกเฟรมภาพ (ทุกครั้งที่จอรีเฟรช) เพราะตำแหน่งเปลี่ยนตลอด
    glPushMatrix()  # "จำตำแหน่งเดิมไว้" ก่อนจะขยับ/หมุนจุดวาด (เหมือนบันทึกเกม)
    glTranslatef(cx, FAN_CY, (D + FZ) / 2)  # ย้ายจุดวาดไปอยู่กลางพัดลม ตรงกึ่งกลางความหนาผนัง (ระหว่างผนังในห้องกับผนังทางเดิน) จะได้เห็นใบพัดทั้งสองฝั่ง
    glRotatef(angle_deg, 0, 0, 1)  # หมุนจุดวาดตามองศาที่รับมา โดยหมุนรอบแกนที่ชี้ออกจากผนังเข้าหาห้อง (เหมือนใบพัดหมุนบนผนัง)
    for k in range(5):  # วนทำใบพัดทีละใบ รวม 5 ใบ
        a0 = 2 * math.pi * k / 5  # มุมเริ่มต้นของใบพัดใบนี้ (กระจายห่างกัน 72 องศาเท่าๆ กัน)
        a1 = a0 + 0.62  # มุมปลายอีกด้านของใบ (กว้างออกไปประมาณ 35 องศา)
        am = a0 + 0.20  # มุมกลางๆ ที่ใช้ทำให้ใบพัดมีสันนูน
        shade = 1.0 if k % 2 == 0 else 0.86  # ใบเลขคู่สีปกติ ใบเลขคี่มืดลงเล็กน้อย ให้เห็นแต่ละใบชัดขึ้น
        glColor3f(0.64 * shade, 0.66 * shade, 0.69 * shade)  # ตั้งสีเทาของครึ่งแรกของใบ ปรับตามความสว่าง
        glBegin(GL_TRIANGLES)                          # เริ่มวาดสามเหลี่ยม (ทุก 3 จุดเป็น 1 อัน) สำหรับครึ่งแรกของใบพัด ซึ่งเป็นทรงลิ่มโค้ง
        glVertex3f(0, 0, 0)  # จุดที่ 1 อยู่ตรงกลางพัดลม
        glVertex3f(0.100 * math.cos(a0), 0.100 * math.sin(a0), 0)  # จุดที่ 2 อยู่ที่ปลายใบ ด้านขอบเริ่มต้น (ห่างกลาง 10 ซม.)
        glVertex3f(0.098 * math.cos(am), 0.098 * math.sin(am), 0)  # จุดที่ 3 อยู่ที่สันนูนกลางใบ (ห่างกลาง 9.8 ซม.)
        glEnd()  # จบสามเหลี่ยมนี้
        glColor3f(0.50 * shade, 0.52 * shade, 0.55 * shade)  # เปลี่ยนเป็นเทาเข้มกว่า สำหรับครึ่งหลังของใบ ให้ดูเหมือนใบบิดเอียงรับแสงต่างกัน
        glBegin(GL_TRIANGLES)  # เริ่มวาดสามเหลี่ยมอีกอันสำหรับครึ่งหลัง
        glVertex3f(0, 0, 0)  # จุดที่ 1 อยู่ตรงกลางพัดลม
        glVertex3f(0.098 * math.cos(am), 0.098 * math.sin(am), 0)  # จุดที่ 2 อยู่ที่สันนูนกลางใบ
        glVertex3f(0.100 * math.cos(a1), 0.100 * math.sin(a1), 0)  # จุดที่ 3 อยู่ที่ปลายใบอีกด้าน
        glEnd()  # จบสามเหลี่ยมนี้ (ได้ใบพัดครบ 1 ใบ แล้ววนไปทำใบถัดไป)
    glColor3f(0.85, 0.86, 0.87)                        # ตั้งสีขาวอมเทาอ่อนสำหรับ "ดุม" คือแกนกลางที่ยึดใบพัด
    for dz in (-0.002, 0.002):  # วาดดุมสองหน้า: ฝั่งในห้อง (-2 มม.) และฝั่งทางเดิน (+2 มม.) ให้ลอยทับเหนือใบพัดทั้งสองด้าน
        glPushMatrix()  # จำตำแหน่งไว้ก่อนขยับดุมแต่ละหน้า
        glTranslatef(0, 0, dz)  # ขยับจุดวาดไปทางหน้านั้น 2 มม.
        glBegin(GL_TRIANGLE_FAN)  # เริ่มวาดวงกลมแบบพัดสามเหลี่ยม
        glVertex3f(0, 0, 0)  # ปักจุดศูนย์กลางดุม
        for i in range(15):  # วนไล่ 15 จุดรอบวง
            a = 2 * math.pi * i / 14  # มุมของจุดนี้ (ครบวงเมื่อ i = 14)
            glVertex3f(0.022 * math.cos(a), 0.022 * math.sin(a), 0)  # ปักจุดบนเส้นรอบวงดุม รัศมี 2.2 ซม.
        glEnd()  # จบการวาดดุมหน้านี้
        glPopMatrix()  # กลับไปตำแหน่งเดิม
    glPopMatrix()  # "กลับไปตำแหน่งเดิม" ที่จำไว้ตอนแรก เพื่อไม่ให้การย้าย/หมุนไปกระทบของชิ้นอื่น
 
 
def _ring_pts(dy, dxo):  # ประกาศสูตร "คำนวณเส้นทางสายไฟรอบห้อง" ส่งกลับเป็นรายการจุด โดย dy = ปรับความสูง และ dxo = ปรับตำแหน่งตรงคาน
    """เส้นทางสายไฟวนรอบห้องเป็นวงปิดเดียว (ผนังประตู -> ตะวันตก -> หน้าต่าง -> ตะวันออก -> ประตู)
    ข้ามเสาที่ผนังหน้าต่างด้วยการยื่นออกมาหน้าเสา และลอดใต้คานที่ผนังประตู
    dy = ชดเชยความสูง (ให้สายขนานกันไม่ทับ)  dxo = ชดเชยตำแหน่งตรงคาน"""  # คำอธิบาย: สายเดินวนรอบห้องเป็นวงปิด ข้ามเสาโดยยื่นออกมาหน้าเสา และลอดใต้คานที่ผนังประตู ค่า dy ทำให้สายหลายเส้นเรียงขนานกันไม่ซ้อนทับ
    bm = 0.37 / 2  # ครึ่งหนึ่งของความกว้างคาน (คานกว้าง 37 ซม.)
    Y = H - 0.18 + dy  # ความสูงสายหลัก: ต่ำจากเพดาน 18 ซม. (ประมาณ 3.12 ม.) ปรับด้วย dy
    yc = 2.65 + dy  # ความสูงตอนสายลอดใต้คาน 2.65 ม. (ต่ำกว่าท้องคาน 2.70 ม. และสูงกว่ากรอบกระจกบนสุด 2.60 ม.)
    zd, zn, xw, xe = D - 0.015, 0.015, 0.015, W - 0.015  # ตำแหน่งสายแต่ละผนัง ห่างผนัง 1.5 ซม.: ผนังประตู (zd), ผนังหน้าต่าง (zn), ผนังตะวันตก (xw), ผนังตะวันออก (xe)
    xl = W / 2 - bm - 0.012 - dxo  # ตำแหน่งซ้ายของคาน (ขอบคานด้านซ้าย เว้น 1.2 ซม. และชดเชยด้วย dxo)
    xr = W / 2 + bm + 0.012 + dxo  # ตำแหน่งขวาของคาน (ขอบคานด้านขวา เว้น 1.2 ซม. และชดเชยด้วย dxo)
    return [  # ส่งรายการจุดทั้งหมดที่สายต้องผ่าน เรียงตามลำดับ ให้ผู้เรียกไปวาดต่อ
        (xl, Y, zd), (xw, Y, zd),                                   # เริ่มที่ผนังประตูฝั่งซ้ายของคาน แล้ววิ่งไปจนสุดมุมตะวันตก
        (xw, Y, 0.125), (0.27, Y, 0.125), (0.285, Y, zn),           # เลี้ยวไปตามผนังตะวันตก แล้วยื่นออกมาหน้าเสามุม ก่อนกลับชิดผนังหน้าต่าง
        (W / 2 - 0.22, Y, zn), (W / 2 - 0.19, Y, 0.125),            # วิ่งไปตามผนังหน้าต่างจนถึงเสากลาง แล้วยื่นออกมาหน้าเสากลาง
        (W / 2 + 0.19, Y, 0.125), (W / 2 + 0.22, Y, zn),  # ผ่านหน้าเสากลางไปอีกฝั่ง แล้วกลับชิดผนังอีกครั้ง
        (W - 0.285, Y, zn), (W - 0.27, Y, 0.125), (xe, Y, 0.125),   # วิ่งต่อไปที่เสามุมตะวันออก ยื่นออกมาหน้าเสา แล้วเลี้ยวเข้าผนังตะวันออก
        (xe, Y, zd), (xr, Y, zd),                                   # วิ่งตามผนังตะวันออกไปถึงผนังประตู แล้ววิ่งไปจนถึงขอบคานด้านขวา
        (xr, yc, zd), (xl, yc, zd), (xl, Y, zd),                    # ลดสายลงต่ำ ลอดใต้คานไปอีกฝั่ง แล้วยกขึ้นกลับสู่ความสูงเดิม ตรงจุดเริ่มต้น (สายจึงเป็นวงปิด)
    ]
 
 
def wall_wires():  # ประกาศสูตร "วาดสายไฟทั้งหมดบนผนัง"
    """สายไฟวนรอบห้องเป็นวงเดียว (ดำ ขาว เทา ขนานกัน) + สายแยกลงปลั๊ก/กล่องต่อสาย
    ทุกเส้นต่อถึงกัน และไม่มีเส้นไหนพาดผ่านกระจกเลย"""  # คำอธิบาย: สาย 3 สี (ดำ ขาว เทา) วิ่งขนานกันรอบห้อง มีสายแยกลงปลั๊กและกล่องต่อสาย ทุกเส้นเชื่อมถึงกัน ไม่พาดผ่านกระจก
    blk = (0.05, 0.05, 0.06)  # ตั้งชื่อสีดำ
    wht = (0.90, 0.90, 0.88)  # ตั้งชื่อสีขาว
    gry = (0.35, 0.36, 0.38)  # ตั้งชื่อสีเทาเข้ม
    bm = 0.37 / 2  # ครึ่งหนึ่งของความกว้างคาน 37 ซม.
    zd, zn, xw, xe = D - 0.015, 0.015, 0.015, W - 0.015  # ตำแหน่งสายชิดผนังทั้ง 4 ด้าน (เหมือนในสูตรข้างบน)
    Y = H - 0.18  # ความสูงสายหลัก (ต่ำจากเพดาน 18 ซม.)
 
    for (dy, dxo, r, col) in ((0.0, 0.0, 0.008, blk), (-0.025, 0.014, 0.006, wht), (0.022, 0.026, 0.005, gry)):  # วนทำสาย 3 เส้น แต่ละเส้นมี: ปรับความสูง, ปรับตำแหน่งตรงคาน, ขนาดสาย, และสี (ดำหนาสุด ขาวกลาง เทาบางสุด)
        pts = _ring_pts(dy, dxo)  # ขอเส้นทางสายสำหรับสายเส้นนี้
        cable(pts, r, col)  # วาดสายตามเส้นทางนั้น
        p = pts[0]  # หยิบจุดเริ่มต้นของเส้นทางมา
        ball(p[0], p[1], p[2], r * 1.05, col, 6, 4)       # วาดลูกบอลปิดรอยต่อที่จุดเริ่ม/จุดจบ (เพราะสายเป็นวงปิด จุดนี้เป็นที่สายมาบรรจบกัน)
 
    # ที่รัดสาย
    x = 0.30  # เริ่มวางที่รัดสายที่ x = 0.30 ม. บนผนังประตูฝั่งตะวันตก
    while x < W / 2 - bm - 0.25:                          # ทำซ้ำตราบใดที่ยังไม่ถึงใกล้คาน (เว้น 25 ซม.) ที่ผนังประตู ฝั่งตะวันตก
        wall_clip(x, Y, zd, 'x'); x += 0.55  # วางที่รัดสายหนึ่งตัว แล้วขยับไปข้างหน้า 55 ซม. เพื่อวางตัวต่อไป
    x = W / 2 + bm + 0.30  # เริ่มวางที่ฝั่งตะวันออกของคาน ห่างคาน 30 ซม.
    while x < W - 0.30:                                   # ทำซ้ำตราบใดที่ยังไม่ถึงใกล้ผนังตะวันออก (เว้น 30 ซม.) ที่ผนังประตู ฝั่งตะวันออก
        wall_clip(x, Y, zd, 'x'); x += 0.55  # วางที่รัดสายหนึ่งตัว แล้วขยับไป 55 ซม.
    for x in (0.9, 1.7, 2.5, 3.2, 4.55, 5.25, 6.05, 6.85):    # ที่ผนังหน้าต่าง วางที่รัดสายตามตำแหน่งที่กำหนดไว้ 8 จุด (เลี่ยงตำแหน่งเสา)
        wall_clip(x, Y, zn, 'x')  # วางที่รัดสายหนึ่งตัวที่ตำแหน่งนั้น
    z = 0.5  # เริ่มวางที่ระยะ 0.5 ม. จากผนังหน้าต่าง บนผนังตะวันตก/ตะวันออก
    while z < D - 0.2:                                    # ทำซ้ำตราบใดที่ยังไม่ถึงใกล้ผนังประตู (เว้น 20 ซม.) ที่ผนังตะวันตก / ตะวันออก
        wall_clip(xw, Y, z, 'z'); wall_clip(xe, Y, z, 'z'); z += 0.60  # วางที่รัดสายทั้งผนังตะวันตกและตะวันออกพร้อมกัน แล้วขยับไป 60 ซม.
 
    # สายแยกลงปลั๊กไฟ ชิดผนังตะวันออก (อยู่ระหว่างขอบหน้าต่างแถบกับม่านผนังตะวันออก ไม่โดนกระจก)
    xs = W - 0.155  # ตำแหน่งสายแยกปลั๊ก: ห่างผนังตะวันออก 15.5 ซม.
    cable([(xs, Y, zd), (xs, 0.50, zd)], 0.007, blk)  # วาดสายสีดำลากจากสายหลักลงมาถึงความสูง 50 ซม. (ระดับปลั๊ก)
    for y in (2.85, 2.30, 1.60, 0.95):  # ไล่ 4 ความสูงที่จะติดที่รัดสายบนสายที่ลงมา
        wall_clip(xs, y, zd, 'x')  # ติดที่รัดสายหนึ่งตัวที่ความสูงนั้น
    box(xs - 0.045, 0.40, zd - 0.025, xs + 0.045, 0.54, zd, wht)                       # วาดแผงปลั๊กเป็นกล่องสีขาว (กว้าง 9 ซม. สูง 14 ซม.)
    box(xs - 0.030, 0.425, zd - 0.030, xs + 0.030, 0.475, zd - 0.025, (0.30, 0.30, 0.32))   # วาดช่องเสียบปลั๊กเป็นกล่องเล็กสีเทาเข้ม ติดบนแผง
    # สายแยกลงกล่องต่อสายเหนือหน้าต่างแถบ (อยู่เหนือกรอบกระจก)
    cable([(2.45, Y, zd), (2.45, 2.88, zd)], 0.007, blk)  # วาดสายสีดำลากจากสายหลักลงมาที่ความสูง 2.88 ม.
    box(2.45 - 0.055, 2.70, zd - 0.035, 2.45 + 0.055, 2.88, zd, wht)                   # วาดกล่องต่อสายสีขาว (กว้าง 11 ซม. สูง 18 ซม.)
    box(2.45 - 0.040, 2.72, zd - 0.040, 2.45 + 0.040, 2.86, zd - 0.035, (0.82, 0.82, 0.80))  # วาดฝากล่องสีขาวอมเทาเล็กกว่านิดหน่อย ซ้อนด้านหน้า ให้ดูเป็นกล่องมีฝา
    # สายแยกลงปลั๊กข้างไวท์บอร์ด
    cable([(xw, Y, 7.55), (xw, 0.60, 7.55)], 0.007, blk)  # วาดสายสีดำลากจากสายหลักบนผนังตะวันตก ลงมาที่ความสูง 60 ซม.
    box(0.0, 0.50, 7.55 - 0.045, 0.025, 0.60, 7.55 + 0.045, wht)  # วาดแผงปลั๊กสีขาว (กล่องบางๆ) ติดผนังตะวันตกข้างไวท์บอร์ด
    box(0.025, 0.52, 7.55 - 0.030, 0.030, 0.58, 7.55 + 0.030, (0.30, 0.30, 0.32))  # วาดช่องเสียบปลั๊กสีเทาเข้ม ติดบนแผงนั้น


# =====================================================================
# 5.7) KAT VR  (ลู่เดิน VR 360° แบบในรูป)  ตั้งไว้มุมตะวันออกเฉียงใต้
#      ขนาดทั้งหมดประมาณจากรูปถ่าย (ยังไม่ได้วัดของจริง) แก้ได้ที่ค่าคงที่ด้านล่าง
# =====================================================================
KAT_POS = (W - 0.75, D - 0.75)   # ตำแหน่งกลางฐานเครื่อง (x, z): ห่างผนังตะวันออก 75 ซม. และห่างผนังประตู 75 ซม. (อยู่มุมห้อง)
KAT_YAW = 225                    # ทิศที่บันไดหันไป เป็นองศา (0 = ไปทางประตู, 180 = ไปทางหน้าต่าง, 90 = ไปทางตะวันออก, -90 = ไปทางตะวันตก) ค่า 225 = เฉียงเข้าห้อง
KAT_R = 0.60                     # รัศมีวงล้อมฐานแปดเหลี่ยม 60 ซม. (ฐานกว้างราว 1.1 เมตร)
KAT_H = 0.30                     # ความสูงฐาน 30 ซม.
KAT_PAD_R = 0.46                 # รัศมีแผ่นเดิน 46 ซม. (เส้นผ่านศูนย์กลางราว 92 ซม.)
KAT_CYAN = (0.04, 0.70, 0.92)    # สีฟ้าสว่าง (สีประจำแบรนด์ ใช้ทำแถบและลาย)
KAT_BLACK = (0.07, 0.07, 0.08)   # สีดำของตัวเครื่อง
KAT_STEP = [(-0.28, 0.50), (0.28, 0.50), (0.34, 0.68), (0.20, 0.92), (-0.20, 0.92), (-0.34, 0.68)]   # แปลนพื้นบันได: รายการมุม 6 มุม (x, z) ที่ลากต่อกันเป็นรูปหกเหลี่ยม
KAT_STEP_H = 0.17                # ความสูงบันได 17 ซม.
 
_SEG7 = {0: 'abcdef', 1: 'bc', 2: 'abdeg', 3: 'abcdg', 4: 'bcfg', 5: 'acdfg', 6: 'acdefg',
         7: 'abc', 8: 'abcdefg', 9: 'abcdfg'}  # ตารางตัวเลขแบบ 7 ขีด (เหมือนนาฬิกาดิจิทัล): ตัวเลขแต่ละตัวต้อง "เปิดไฟ" ขีดไหนบ้าง a=บน b=ขวาบน c=ขวาล่าง d=ล่าง e=ซ้ายล่าง f=ซ้ายบน g=กลาง
 
 
def _seg_digit(d, cx, cy, z, h, col):  # ประกาศสูตร "วาดตัวเลขแบบ 7 ขีด" d = ตัวเลขที่ต้องการ, (cx, cy) = จุดกลางตัวเลข, z = ระยะลึก, h = ความสูงตัวเลข, col = สี
    """ตัวเลข 7 ส่วน แปะบนผิวที่หันไปทาง +Z (ใช้ทำเลข 4 และ 6 บนตัวเครื่อง)"""  # คำอธิบาย: ตัวเลขแบบ 7 ขีด แปะบนผิวที่หันไปทางประตู ใช้ทำเลข 4 และ 6 บนตัวเครื่อง
    w, t = h * 0.55, h * 0.17  # คำนวณความกว้างตัวเลข (55% ของความสูง) และความหนาของแต่ละขีด (17% ของความสูง)
    r = {'a': (-w / 2, h / 2 - t, w / 2, h / 2), 'b': (w / 2 - t, 0, w / 2, h / 2),  # ตารางตำแหน่งของแต่ละขีด เก็บเป็นสี่เหลี่ยม (ซ้าย, ล่าง, ขวา, บน): ขีด a คือแถบบนสุด, ขีด b คือแถบขวาครึ่งบน
         'c': (w / 2 - t, -h / 2, w / 2, 0), 'd': (-w / 2, -h / 2, w / 2, -h / 2 + t),  # ขีด c คือแถบขวาครึ่งล่าง, ขีด d คือแถบล่างสุด
         'e': (-w / 2, -h / 2, -w / 2 + t, 0), 'f': (-w / 2, 0, -w / 2 + t, h / 2),  # ขีด e คือแถบซ้ายครึ่งล่าง, ขีด f คือแถบซ้ายครึ่งบน
         'g': (-w / 2, -t / 2, w / 2, t / 2)}  # ขีด g คือแถบกลางแนวนอน
    for s in _SEG7[d]:  # ไล่ดูทีละขีดที่ตัวเลขนี้ต้องใช้ (ดูจากตารางด้านบน)
        x0, y0, x1, y1 = r[s]  # ดึงขอบทั้งสี่ของขีดนั้นมาใช้
        gquad([(cx + x0, cy + y0, z), (cx + x1, cy + y0, z), (cx + x1, cy + y1, z), (cx + x0, cy + y1, z)], [col] * 4)  # วาดขีดเป็นแผ่นสี่เหลี่ยมสีเดียว ย้ายไปอยู่ตำแหน่งกลางที่กำหนด
 
 
def make_text_tex(text, color=(10, 178, 235), size=110):  # ประกาศสูตร "สร้างภาพข้อความ" (ไว้แปะเป็นโลโก้) text = ข้อความ, color = สี (ค่าอยู่ระหว่าง 0-255), size = ขนาดฟอนต์
    """สร้างเท็กซ์เจอร์ข้อความ (ใช้ฟอนต์ของ pygame) ไว้ทำโลโก้ \"KAT VR\"
    ต้องเรียกก่อนเริ่ม display list (เพราะสร้างเท็กซ์เจอร์ข้างในลิสต์ไม่ได้)  คืนค่า (id, อัตราส่วนกว้าง/สูง)"""  # คำอธิบาย: สร้างภาพจากข้อความ ต้องเรียกก่อนเริ่มบันทึกการวาด ส่งคืนรหัสภาพและอัตราส่วนกว้างต่อสูง
    font = pygame.font.Font(None, size)  # เปิดฟอนต์มาตรฐานของไลบรารี pygame ที่ขนาดที่ต้องการ
    font.set_bold(True)  # ตั้งเป็นตัวหนา
    surf = font.render(text, True, color)  # เขียนข้อความลงเป็นภาพ (True = ให้ขอบตัวอักษรเนียน)
    w, h = surf.get_size()  # วัดความกว้างและความสูงของภาพข้อความ
    data = pygame.image.tostring(surf, "RGBA", True)  # แปลงภาพเป็นข้อมูลพิกเซลดิบ (สี + ความโปร่งใส) และพลิกแนวตั้งให้ตรงกับที่กราฟิกการ์ดต้องการ
    tid = glGenTextures(1)  # ขอ "เลขรหัสภาพ" ใหม่จากกราฟิกการ์ด เพื่อใช้อ้างอิงภาพนี้ภายหลัง
    glBindTexture(GL_TEXTURE_2D, tid)  # บอกกราฟิกการ์ดว่า "ต่อไปนี้จะตั้งค่าภาพรหัสนี้"
    glPixelStorei(GL_UNPACK_ALIGNMENT, 1)  # บอกวิธีอ่านข้อมูลพิกเซล (เรียงแบบแน่น ไม่เว้นช่อง)
    gluBuild2DMipmaps(GL_TEXTURE_2D, GL_RGBA, w, h, GL_RGBA, GL_UNSIGNED_BYTE, data)  # ส่งภาพให้กราฟิกการ์ด พร้อมสร้างภาพย่อหลายขนาด (mipmap) ให้ภาพไกลๆ ดูเนียนไม่เป็นเม็ด
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE)  # ตั้งว่าถ้าแปะภาพเกินขอบแนวนอน ให้ยืดสีขอบแทนที่จะวนซ้ำ
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE)  # เหมือนบรรทัดบน แต่สำหรับแนวตั้ง
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR_MIPMAP_LINEAR)  # ตั้งวิธีย่อภาพเมื่อมองจากไกล ให้ผสมสีเนียนระหว่างภาพย่อแต่ละขนาด
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR)  # ตั้งวิธีขยายภาพเมื่อมองใกล้ ให้ผสมสีเนียน
    return tid, w / h  # ส่งคืนรหัสภาพ และอัตราส่วนกว้างต่อสูง (เอาไว้แปะภาพให้สัดส่วนไม่เพี้ยน)
 
 
def _logo_decal(logo, cx, cy, z, h):  # ประกาศสูตร "แปะโลโก้" logo = ข้อมูลภาพจากสูตรข้างบน, (cx, cy) = ตำแหน่งกลางโลโก้, z = ระยะลึก, h = ความสูงตัวอักษร
    """แปะข้อความโปร่งใสบนผิวที่หันไปทาง +Z  h = ความสูงตัวอักษร (เมตร)"""  # คำอธิบาย: แปะข้อความพื้นหลังโปร่งใสบนผิวที่หันไปทางประตู
    tid, asp = logo  # แยกข้อมูลโลโก้ออกเป็นรหัสภาพ (tid) และอัตราส่วนกว้างต่อสูง (asp)
    w = h * asp  # คำนวณความกว้างโลโก้จากความสูงที่ต้องการ
    glEnable(GL_TEXTURE_2D)  # เปิดโหมด "แปะภาพ"
    glBindTexture(GL_TEXTURE_2D, tid)  # เลือกภาพโลโก้ที่จะใช้
    glEnable(GL_BLEND)  # เปิดโหมด "ผสมสี" เพื่อให้ส่วนโปร่งใสของภาพมองทะลุเห็นสิ่งที่อยู่ข้างหลัง
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)  # เลือกสูตรผสมสีแบบมาตรฐานของความโปร่งใส
    glDepthMask(GL_FALSE)  # ปิดการบันทึกความลึกชั่วคราว ไม่ให้โลโก้โปร่งใสไปบังของที่อยู่หลังมันผิดๆ
    glColor3f(1, 1, 1)  # ตั้งสีขาวล้วน (เพื่อให้ภาพแสดงสีจริง ไม่ถูกย้อมสีอื่น)
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม 1 แผ่นเป็นกระดานที่จะแปะภาพ
    glTexCoord2f(0, 0); glVertex3f(cx - w / 2, cy - h / 2, z)  # มุมล่างซ้ายของแผ่น ผูกกับมุมล่างซ้ายของภาพ
    glTexCoord2f(1, 0); glVertex3f(cx + w / 2, cy - h / 2, z)  # มุมล่างขวาของแผ่น ผูกกับมุมล่างขวาของภาพ
    glTexCoord2f(1, 1); glVertex3f(cx + w / 2, cy + h / 2, z)  # มุมบนขวาของแผ่น ผูกกับมุมบนขวาของภาพ
    glTexCoord2f(0, 1); glVertex3f(cx - w / 2, cy + h / 2, z)  # มุมบนซ้ายของแผ่น ผูกกับมุมบนซ้ายของภาพ
    glEnd()  # จบการวาดแผ่น
    glDepthMask(GL_TRUE)  # เปิดการบันทึกความลึกกลับเหมือนเดิม
    glDisable(GL_BLEND)  # ปิดโหมดผสมสี
    glDisable(GL_TEXTURE_2D)  # ปิดโหมดแปะภาพ เพื่อให้ของชิ้นต่อไปไม่ถูกแปะภาพโดยไม่ตั้งใจ
 
 
def _oct_pts(R):  # ประกาศสูตร "หาจุดมุมของรูปแปดเหลี่ยม" รัศมีวงล้อม R
    """จุดมุมแปดเหลี่ยมด้านเท่า รัศมีวงล้อม R (ด้านแบนหันไปทางแกน X/Z)"""  # คำอธิบาย: จุดมุมแปดเหลี่ยมด้านเท่า ให้ด้านแบนหันไปตรงกับแกน x และ z
    return [(R * math.cos(math.radians(22.5 + 45 * k)), R * math.sin(math.radians(22.5 + 45 * k))) for k in range(8)]  # ส่งคืนรายการมุม 8 จุด เริ่มที่ 22.5° แล้วบวกทีละ 45° (22.5 ทำให้ด้านแบนหันตรงแกน)
 
 
def _oct_r(a, R):  # ประกาศสูตร "ระยะจากกลางถึงขอบแปดเหลี่ยม" ในทิศมุม a (เรเดียน)
    """ระยะจากกึ่งกลางถึงขอบแปดเหลี่ยม ที่มุม a (เรเดียน)"""  # คำอธิบาย: วัดว่าเดินจากกลางไปในทิศมุม a จะถึงขอบแปดเหลี่ยมที่ระยะเท่าไร
    ap = R * math.cos(math.radians(22.5))  # ระยะจากกลางไปตั้งฉากกับกลางด้านแบน (ระยะสั้นสุดไปถึงขอบ)
    d = (a + math.radians(22.5)) % math.radians(45) - math.radians(22.5)  # หาว่าทิศนี้เบี่ยงจากแนวตั้งฉากกับด้านที่ใกล้ที่สุดกี่องศา (อยู่ในช่วง -22.5° ถึง 22.5°)
    return ap / math.cos(d)  # ยิ่งเบี่ยงจากแนวตั้งฉากมาก ระยะยิ่งยาวขึ้น (ไปสุดที่มุมของแปดเหลี่ยม)
 
 
def _poly_prism(pts, y0, y1, col, grow=0.0, top=True):  # ประกาศสูตร "สร้างแท่งปริซึม" pts = มุมของฐาน, y0 = ความสูงล่าง, y1 = ความสูงบน, col = สี, grow = ขยายออกด้านข้าง, top = จะปิดฝาด้านบนไหม
    """แท่งปริซึมจากรูปหลายเหลี่ยมนูน (x, z)  grow = ขยายผนังข้างออกไปอีกเล็กน้อย (ใช้ทำแถบสีที่ยื่นออกมา)"""  # คำอธิบาย: แท่งจากฐานหลายเหลี่ยม ค่า grow ใช้ขยายผนังออกเล็กน้อย เอาไว้ทำแถบสีที่นูนออกมา
    n = len(pts)  # นับจำนวนมุมของฐาน
    mx = sum(p[0] for p in pts) / n  # หาจุดกึ่งกลางของฐาน (ค่าเฉลี่ยตำแหน่ง x ของทุกมุม)
    mz = sum(p[1] for p in pts) / n  # ค่าเฉลี่ยตำแหน่ง z ของทุกมุม (รวมกับบรรทัดบนได้จุดกึ่งกลาง)
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม สำหรับผนังข้างแต่ละด้าน
    for i in range(n):  # วนทีละด้านของฐาน
        a, b = pts[i], pts[(i + 1) % n]  # จุดสองจุดที่เป็นหัวและท้ายของด้านนี้ (ด้านสุดท้ายวนกลับไปต่อกับจุดแรก)
        ex, ez = b[0] - a[0], b[1] - a[1]  # ทิศทางของด้านนี้ (ลูกศรจากจุด a ไป b)
        L = math.hypot(ex, ez) or 1.0  # ความยาวของด้านนี้ (ถ้าได้ 0 ใช้ 1 กันหารด้วยศูนย์)
        nx, nz = ez / L, -ex / L  # คำนวณทิศที่ "ชี้ตั้งฉากออกจากผนัง" (เรียกว่า เวกเตอร์ตั้งฉาก) ให้ยาว 1
        if nx * ((a[0] + b[0]) / 2 - mx) + nz * ((a[1] + b[1]) / 2 - mz) < 0:  # เช็กว่าทิศนั้นชี้ออกนอกรูปหรือชี้เข้าข้างใน (เทียบกับจุดกึ่งกลาง)
            nx, nz = -nx, -nz  # ถ้าชี้เข้าข้างใน ให้กลับทิศให้ชี้ออกนอก
        sh = 0.55 + 0.45 * max(0.0, nx * LIGHT_N[0] + nz * LIGHT_N[2])  # คำนวณความสว่างของผนังด้านนี้ตามว่าหันเข้าหาแสงแค่ไหน (0.55 มืดสุด ถึง 1.0 สว่างสุด)
        glColor3f(col[0] * sh, col[1] * sh, col[2] * sh)  # ตั้งสีผนังโดยคูณกับความสว่าง
        glVertex3f(a[0] + nx * grow, y0, a[1] + nz * grow)  # มุมล่างของผนังฝั่งจุด a (ขยับออกด้านข้างตามค่า grow)
        glVertex3f(b[0] + nx * grow, y0, b[1] + nz * grow)  # มุมล่างของผนังฝั่งจุด b
        glVertex3f(b[0] + nx * grow, y1, b[1] + nz * grow)  # มุมบนของผนังฝั่งจุด b
        glVertex3f(a[0] + nx * grow, y1, a[1] + nz * grow)  # มุมบนของผนังฝั่งจุด a
    glEnd()  # จบการวาดผนังข้างทั้งหมด
    if top:  # ถ้าต้องการปิดฝาด้านบน
        glColor3f(col[0] * SHADE_TOP, col[1] * SHADE_TOP, col[2] * SHADE_TOP)  # ตั้งสีฝาบนด้วยความสว่างของผิวด้านบน
        glBegin(GL_POLYGON)  # เริ่มวาดรูปหลายเหลี่ยม 1 แผ่น
        for p in pts:  # ไล่ทุกมุมของฐาน
            glVertex3f(p[0], y1, p[1])  # ปักมุมที่ความสูงบนสุด
        glEnd()  # จบการวาดฝาบน
 
 
def _arc_band(cx, cz, r0, r1, a0, a1, y0, y1, col, seg=14):  # ประกาศสูตร "แผ่นโค้งเป็นแถบ" (เหมือนส่วนของวงแหวนที่มีความหนาและความสูง) กลาง (cx, cz) รัศมีใน r0 รัศมีนอก r1 มุมเริ่ม a0 มุมจบ a1 สูงจาก y0 ถึง y1
    """แผ่นโค้งตามส่วนของวงกลม (ใช้ทำเบาะพนักหลังของสายรัดเอว)  มุมเป็นองศา x=cos z=sin"""  # คำอธิบาย: แถบโค้งตามส่วนของวงกลม ใช้ทำเบาะพนักหลังของสายรัดเอว มุมเป็นองศา
    a0, a1 = math.radians(a0), math.radians(a1)  # แปลงมุมจากองศาเป็นเรเดียนเพื่อใช้คำนวณ
 
    def sh(nx, nz):  # สูตรย่อย: คำนวณความสว่างจากทิศที่ผิวหันไป
        return 0.55 + 0.45 * max(0.0, nx * LIGHT_N[0] + nz * LIGHT_N[2])  # สว่างระหว่าง 0.55 ถึง 1.0 ตามว่าหันเข้าหาแสงแค่ไหน
 
    def P(r, a, y):  # สูตรย่อย: หาตำแหน่งจริงของจุดที่รัศมี r มุม a ความสูง y
        return (cx + r * math.cos(a), y, cz + r * math.sin(a))  # ส่งคืนตำแหน่ง (x, y, z) บนวงกลม
 
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม
    for i in range(seg):  # วนแบ่งแถบโค้งเป็นช่องเล็กๆ ทีละช่อง (ยิ่งแบ่งมากยิ่งโค้งเนียน)
        t0 = a0 + (a1 - a0) * i / seg  # มุมเริ่มของช่องนี้
        t1 = a0 + (a1 - a0) * (i + 1) / seg  # มุมจบของช่องนี้
        tm = (t0 + t1) / 2  # มุมกลางของช่องนี้ (ใช้คำนวณทิศที่ผิวหัน)
        for (r, sg) in ((r1, 1.0), (r0, -1.0)):                       # วาดผนังสองด้านของแถบ: ด้านนอก (หันออกจากศูนย์กลาง) และด้านใน (หันเข้าหาศูนย์กลาง)
            s = sh(sg * math.cos(tm), sg * math.sin(tm))  # คำนวณความสว่างผนังด้านนี้
            glColor3f(col[0] * s, col[1] * s, col[2] * s)  # ตั้งสีโดยคูณกับความสว่าง
            glVertex3f(*P(r, t0, y0)); glVertex3f(*P(r, t1, y0)); glVertex3f(*P(r, t1, y1)); glVertex3f(*P(r, t0, y1))  # ปักมุมทั้ง 4 ของผนังช่องนี้ (ล่างซ้าย ล่างขวา บนขวา บนซ้าย)
        glColor3f(col[0] * SHADE_TOP, col[1] * SHADE_TOP, col[2] * SHADE_TOP)    # ตั้งสีของขอบด้านบนแถบ
        glVertex3f(*P(r0, t0, y1)); glVertex3f(*P(r1, t0, y1)); glVertex3f(*P(r1, t1, y1)); glVertex3f(*P(r0, t1, y1))  # ปักมุมของแผ่นปิดด้านบนช่องนี้
        glColor3f(col[0] * SHADE_BOT, col[1] * SHADE_BOT, col[2] * SHADE_BOT)    # ตั้งสีของขอบด้านล่างแถบ (มืดกว่าเพราะอยู่ใต้)
        glVertex3f(*P(r0, t0, y0)); glVertex3f(*P(r1, t0, y0)); glVertex3f(*P(r1, t1, y0)); glVertex3f(*P(r0, t1, y0))  # ปักมุมของแผ่นปิดด้านล่างช่องนี้
    for a in (a0, a1):                                                          # ปิดหัวและท้ายของแถบโค้ง ด้วยแผ่นตั้งสองแผ่น
        glColor3f(col[0] * 0.8, col[1] * 0.8, col[2] * 0.8)  # ตั้งสีเข้มลงนิดหน่อย (80%)
        glVertex3f(*P(r0, a, y0)); glVertex3f(*P(r1, a, y0)); glVertex3f(*P(r1, a, y1)); glVertex3f(*P(r0, a, y1))  # ปักมุมทั้ง 4 ของแผ่นปิดปลายแถบ
    glEnd()  # จบการวาดแถบทั้งหมด
 
 
def kat_vr(logo, cx, cz, yaw):  # ประกาศสูตร "สร้างเครื่อง KAT VR ทั้งตัว" logo = ภาพโลโก้, (cx, cz) = ตำแหน่ง, yaw = องศาหมุนรอบตัว
    """KAT VR  ลู่เดิน VR 360° ตามรูป: ฐานแปดเหลี่ยมสีดำมีแถบฟ้า แผ่นเดินเว้าลายซี่ มีวงขาว
    บันไดพรมยื่นออกด้านหน้า (เลข 6)  ขา 3 ขาชี้ขึ้นไปห่วงรัดเอว + เบาะพนักหลัง + สายรัดห้อย
    กล่องเซนเซอร์สูงด้านบนมีลายฟ้า (เลข 4)  ก่อนหมุน บันไดชี้ไปทาง +Z  yaw = หมุนรอบแกนตั้ง (องศา)"""  # คำอธิบายองค์ประกอบทั้งหมดของเครื่อง: ฐาน แผ่นเดิน บันได ขา ห่วงรัดเอว เบาะ สาย กล่องเซนเซอร์ (ก่อนหมุน บันไดหันไปทางประตู)
    blk, cyan, white = KAT_BLACK, KAT_CYAN, (0.92, 0.92, 0.94)  # ตั้งชื่อสีย่อ: ดำ ฟ้า ขาว
    pad = (0.12, 0.12, 0.13)  # สีเทาเข้มของเบาะรัดเอว
    R, Hb, pr = KAT_R, KAT_H, KAT_PAD_R  # ตั้งชื่อย่อให้ค่าคงที่: รัศมีฐาน (R) ความสูงฐาน (Hb) รัศมีแผ่นเดิน (pr)
    glPushMatrix()  # "จำตำแหน่งเดิมไว้" ก่อนจะขยับ/หมุนจุดวาด (เหมือนบันทึกเกม)
    glTranslatef(cx, 0, cz)  # ย้ายจุดวาดไปยืนที่ตำแหน่งของเครื่องบนพื้น จากนี้ทุกอย่างวาดสัมพันธ์กับจุดนี้
    glRotatef(yaw, 0, 1, 0)  # หมุนจุดวาดรอบแกนตั้งตามองศา yaw ทำให้เครื่องทั้งตัวหันไปทิศที่ต้องการ
 
    # ---------- ฐาน ----------
    _poly_prism(_oct_pts(R), 0.0, Hb, blk, top=False)  # สร้างฐานเป็นแท่งแปดเหลี่ยมสีดำ สูงตามค่า Hb (ยังไม่ปิดฝาบน เพราะเดี๋ยวจะวาดแผ่นเดินและขอบแยกต่างหาก)
    _poly_prism(_oct_pts(R), 0.075, 0.115, cyan, grow=0.003, top=False)          # สร้างแถบสีฟ้ารอบฐาน เป็นแท่งแปดเหลี่ยมบางๆ (สูง 7.5-11.5 ซม.) ที่นูนออกมา 3 มม.
    seg = 64  # จำนวนช่องที่แบ่งวงกลม (ยิ่งมากยิ่งกลมเนียน)
    rin = pr + 0.025  # รัศมีขอบในของหน้าบนฐาน = รัศมีแผ่นเดิน + 2.5 ซม. (เว้นที่ไว้ให้วงขาว)
    glColor3f(0.08, 0.08, 0.09)                                                  # ตั้งสีดำเข้มของหน้าบนฐาน (ส่วนวงแหวนระหว่างแผ่นเดินกับขอบนอกแปดเหลี่ยม)
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม
    for i in range(seg):  # วนทีละช่องรอบวง
        a0, a1 = 2 * math.pi * i / seg, 2 * math.pi * (i + 1) / seg  # มุมเริ่มและมุมจบของช่องนี้
        glVertex3f(rin * math.cos(a0), Hb, rin * math.sin(a0))  # มุมที่ 1: ขอบในด้านมุมเริ่ม
        glVertex3f(_oct_r(a0, R) * math.cos(a0), Hb, _oct_r(a0, R) * math.sin(a0))  # มุมที่ 2: ขอบนอก (ตามรูปแปดเหลี่ยม) ด้านมุมเริ่ม
        glVertex3f(_oct_r(a1, R) * math.cos(a1), Hb, _oct_r(a1, R) * math.sin(a1))  # มุมที่ 3: ขอบนอกด้านมุมจบ
        glVertex3f(rin * math.cos(a1), Hb, rin * math.sin(a1))  # มุมที่ 4: ขอบในด้านมุมจบ
    glEnd()  # จบการวาดหน้าบนฐาน
    glColor3f(*white)                                                            # ตั้งสีขาวสำหรับวงขาวรอบแผ่นเดิน
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม
    for i in range(seg):  # วนทีละช่องรอบวง
        a0, a1 = 2 * math.pi * i / seg, 2 * math.pi * (i + 1) / seg  # มุมเริ่มและมุมจบของช่องนี้
        for (r, a) in ((pr, a0), (rin, a0), (rin, a1), (pr, a1)):  # ไล่ 4 มุมของแผ่นช่องนี้ (รัศมีในและรัศมีนอก ทั้งสองมุม)
            glVertex3f(r * math.cos(a), Hb + 0.002, r * math.sin(a))  # ปักมุมที่ลอยเหนือหน้าบนฐานเล็กน้อย (2 มม.) ไม่ให้ภาพทับกันจนกระพริบ
    glEnd()  # จบการวาดวงขาว
 
    # ---------- แผ่นเดินเว้าเป็นจาน + ซี่ร่องกระจายจากกลาง ----------
    y_mid = Hb - 0.055  # ความสูงตรงกลางแผ่นเดิน ต่ำกว่าขอบ 5.5 ซม. (ทำให้เว้าเป็นจาน)
 
    def dish_y(r):  # สูตรย่อย: ความสูงของแผ่นเดินที่ระยะ r จากกลาง
        return y_mid + (Hb - y_mid) * (r / pr) ** 2  # กลางต่ำสุด ยิ่งออกไปขอบยิ่งสูงขึ้นแบบโค้ง (ตามสูตรพาราโบลา) จนถึงระดับขอบที่ Hb
 
    rings, sg = 7, 48  # แบ่งแผ่นเดินเป็น 7 วงจากกลางออกขอบ และ 48 ช่องรอบวง
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม
    for k in range(rings):  # วนทีละวงจากกลางออกขอบ
        r0, r1 = pr * k / rings, pr * (k + 1) / rings  # รัศมีขอบในและขอบนอกของวงนี้
        for i in range(sg):  # วนทีละช่องรอบวง
            a0, a1 = 2 * math.pi * i / sg, 2 * math.pi * (i + 1) / sg  # มุมเริ่มและมุมจบของช่องนี้
            s = (1.0 if i % 2 == 0 else 0.88) * (0.80 + 0.20 * (k + 1) / rings)  # ความสว่าง: ช่องเลขคี่มืดลง 12% ทำให้เป็นลายซี่สลับสี และยิ่งออกขอบยิ่งสว่างขึ้น
            glColor3f(0.085 * s, 0.085 * s, 0.095 * s)  # ตั้งสีดำอมเทา คูณกับความสว่าง
            for (r, a) in ((r0, a0), (r1, a0), (r1, a1), (r0, a1)):  # ไล่ 4 มุมของแผ่นช่องนี้
                glVertex3f(r * math.cos(a), dish_y(r), r * math.sin(a))  # ปักมุมที่ระดับความสูงตามความเว้าของจาน
    glEnd()  # จบการวาดแผ่นเดิน
    glColor3f(0.20, 0.20, 0.22)  # ตั้งสีเทาสำหรับเส้นร่องที่พุ่งออกจากกลาง
    glBegin(GL_QUADS)  # เริ่มวาดแผ่นสี่เหลี่ยม
    for j in range(36):  # วนทำร่อง 36 เส้น กระจายรอบวงทุก 10 องศา
        a = 2 * math.pi * j / 36  # มุมของร่องเส้นนี้
        for (r, da) in ((0.10, -0.012), (0.10, 0.012), (pr - 0.04, 0.003), (pr - 0.04, -0.003)):  # ไล่ 4 มุมของร่อง ซึ่งเป็นแถบเรียวแหลมที่กว้างตรงกลาง (r=0.10) และแคบตรงขอบ
            glVertex3f(r * math.cos(a + da), dish_y(r) + 0.0012, r * math.sin(a + da))  # ปักมุมที่ลอยเหนือพื้นแผ่นเดิน 1.2 มม. ไม่ให้ภาพทับกันจนกระพริบ
    glEnd()  # จบการวาดร่อง
 
    # ---------- โลโก้ KAT VR บนด้านหน้าของฐาน ----------
    zl = R * math.cos(math.radians(22.5)) + 0.002  # หาตำแหน่งผิวด้านหน้าฐาน (ระยะจากกลางถึงกลางด้านแบน) แล้วขยับออกมา 2 มม. ไม่ให้จมในผิว
    _logo_decal(logo, 0.0, 0.235, zl, 0.07)  # แปะโลโก้ที่กลางด้านหน้าฐาน ความสูง 23.5 ซม. ตัวอักษรสูง 7 ซม.
 
    # ---------- บันไดมีพรม (เลข 6) ----------
    _poly_prism(KAT_STEP, 0.0, KAT_STEP_H, blk)  # สร้างตัวบันไดเป็นแท่งหกเหลี่ยมสีดำตามแปลนที่ตั้งไว้ (ปิดฝาบนด้วย)
    _poly_prism(KAT_STEP, 0.04, 0.075, cyan, grow=0.003, top=False)  # สร้างแถบสีฟ้าบางๆ รอบบันได นูนออกมา 3 มม.
    ys = KAT_STEP_H + 0.0015  # ความสูงที่จะปูพรม: เหนือผิวบันได 1.5 มม. (กันภาพกระพริบ)
    for i in range(14):                                                          # ปูพรมลายตารางหมากรุก: วนไล่ 14 คอลัมน์
        for j in range(9):  # และ 9 แถว (รวม 126 ช่อง)
            s = 0.20 if (i + j) % 2 == 0 else 0.27  # ช่องที่ผลรวมตำแหน่งเป็นเลขคู่ใช้เทาเข้ม ช่องเลขคี่ใช้เทาอ่อน ทำให้เป็นลายสลับสี
            xa, za = -0.21 + i * 0.03, 0.60 + j * 0.03  # ตำแหน่งมุมของช่องนี้ ช่องละ 3 ซม.
            gquad([(xa, ys, za), (xa + 0.03, ys, za), (xa + 0.03, ys, za + 0.03), (xa, ys, za + 0.03)], [(s, s, s + 0.01)] * 4)  # วาดช่องพรมสี่เหลี่ยมเล็กๆ หนึ่งช่อง (ใส่น้ำเงินเพิ่มนิดเดียวให้ออกเทาเย็น)
    zf = KAT_STEP[3][1] + 0.0015  # ตำแหน่งผิวหน้าบันไดด้านที่ยื่นออกมา (จากมุมที่ 4 ของแปลน) ขยับออกมาเล็กน้อย
    gquad([(0.065, 0.09, zf), (0.135, 0.09, zf), (0.135, 0.16, zf), (0.065, 0.16, zf)], [cyan] * 4)  # วาดป้ายสี่เหลี่ยมสีฟ้าเล็กๆ ที่หน้าบันได เป็นพื้นให้ตัวเลข
    _seg_digit(6, 0.10, 0.125, zf + 0.0008, 0.045, white)  # วาดเลข 6 สีขาวลงบนป้ายนั้น (ความสูงตัวเลข 4.5 ซม.)
 
    # ---------- ขา 3 ขา + ห่วงรัดเอว ----------
    ry, rz = 1.34, -0.04                                                         # ความสูง (1.34 ม.) และตำแหน่งหน้า-หลังของจุดกึ่งกลางห่วงรัดเอว
    for (fx, fz, tx, ty, tz) in ((0.52, 0.0, 0.20, ry, rz), (-0.52, 0.0, -0.20, ry, rz), (0.0, -0.52, 0.0, 1.54, -0.27)):  # วนทำขา 3 ขา แต่ละขามีจุดล่างที่ฐาน (fx, fz) และจุดบน (tx, ty, tz): ขาขวา ขาซ้าย และขาหลังที่ยาวและสูงกว่า
        tube((fx, Hb, fz), (tx, ty, tz), 0.011, blk, 8)  # วาดขาเป็นท่อสีดำ จากฐานเฉียงขึ้นไปหาห่วง (รัศมี 1.1 ซม.)
        cylinder(fx, Hb, fz, 0.022, 0.035, cyan, 10)                              # วาดหูยึดขาสีฟ้าที่โคนขา เป็นทรงกระบอกเล็ก
    ring = []  # เตรียมรายการว่างไว้เก็บจุดที่จะต่อเป็นห่วง
    for k in range(15):                                                          # สร้างจุด 15 จุดสำหรับห่วงรูปเกือกม้า (เปิดด้านหน้า)
        a = math.radians(130 + 280 * k / 14)  # มุมของจุดนี้ เริ่ม 130° ไล่ไป 410° (กวาด 280° ไม่ครบรอบ เหลือช่องเปิด 80° ให้ผู้เล่นก้าวเข้า)
        ring.append((0.20 * math.cos(a), ry, rz + 0.20 * math.sin(a)))  # เก็บตำแหน่งจุดบนวงกลมรัศมี 20 ซม. ที่ความสูงของห่วง
    cable(ring, 0.016, blk, 8)  # วาดห่วงเป็นสายหนา (รัศมี 1.6 ซม.) ต่อผ่านจุดทั้งหมด ได้เป็นห่วงรูปเกือกม้า
    _arc_band(0.0, rz, 0.19, 0.235, 205, 335, ry, ry + 0.22, pad)                 # วาดเบาะพนักหลังเป็นแถบโค้งสูง 22 ซม. อยู่ด้านหลังของห่วง (มุม 205°-335°)
    _arc_band(0.0, rz, 0.195, 0.225, 235, 305, ry - 0.20, ry - 0.07, pad)         # วาดเบาะล่างที่ห้อยลงมาใต้ห่วง เป็นแถบโค้งแคบกว่า
    box(-0.012, ry - 0.07, rz - 0.235, 0.012, ry, rz - 0.200, blk)               # วาดกล่องเล็กสีดำเชื่อมระหว่างเบาะล่างกับห่วง
    for sx in (-1, 1):                                                           # วนทำสายรัดห้อยสองข้าง (ซ้าย -1 และขวา 1)
        x = sx * 0.205  # ตำแหน่งของสายข้างนี้ ห่างจากกลาง 20.5 ซม.
        box(x - 0.007, 0.80, rz - 0.030, x + 0.007, ry, rz + 0.030, blk)  # วาดสายรัดเป็นแถบแบนสีดำ ห้อยจากห่วงลงมาถึงสูง 80 ซม.
        box(x - 0.012, 0.76, rz - 0.040, x + 0.012, 0.84, rz + 0.040, (0.20, 0.21, 0.23))   # วาดตัวปลายสาย (หัวล็อกสีเทาเข้ม) ที่ปลายล่างของสาย
    box(0.205 - 0.010, 1.00, rz - 0.032, 0.205 + 0.010, 1.06, rz + 0.032, cyan)  # วาดแถบสีฟ้าพาดบนสายขวา สูง 6 ซม.
    box(-0.205 - 0.011, ry - 0.07, rz - 0.020, -0.205 + 0.011, ry - 0.02, rz + 0.020, (0.75, 0.10, 0.10))  # วาดหัวเข็มขัดสีแดงบนสายซ้าย ใต้ห่วงลงมาเล็กน้อย
 
    # ---------- คอเครื่อง + กล่องเซนเซอร์ด้านบน (เลข 4) ----------
    box(-0.10, 1.56, -0.25, 0.10, 1.62, -0.08, (0.22, 0.23, 0.25))  # วาดคอเครื่อง เป็นกล่องสีเทาเข้มที่รองรับกล่องเซนเซอร์ด้านบน
    _poly_prism([(-0.10, -0.06), (0.10, -0.06), (0.12, -0.16), (0.10, -0.26), (-0.10, -0.26), (-0.12, -0.16)],  # สร้างกล่องเซนเซอร์เป็นแท่งหกเหลี่ยมสีดำ: ระบุมุมทั้ง 6 ของฐาน
                1.62, 2.00, blk)  # สูงตั้งแต่ 1.62 ถึง 2.00 เมตร
    zt = -0.06 + 0.0012  # ตำแหน่งผิวหน้ากล่องเซนเซอร์ (ด้านที่หันไปทางประตู) ขยับออกมา 1.2 มม. สำหรับแปะลาย
    for g in (-1, 1):                                                            # วนทำลายรูปตัว V สองซีก (ซ้าย -1 และขวา 1)
        gquad([(g * 0.10, 1.945, zt), (0.0, 1.875, zt), (0.0, 1.840, zt), (g * 0.10, 1.910, zt)], [cyan] * 4)  # วาดแถบสีฟ้าเฉียงจากขอบกล่องลงมาที่กึ่งกลาง ซีกซ้ายและซีกขวาประกอบกันเป็นตัว V
    gquad([(-0.035, 1.735, zt), (0.035, 1.735, zt), (0.035, 1.810, zt), (-0.035, 1.810, zt)], [cyan] * 4)  # วาดป้ายสี่เหลี่ยมสีฟ้าใต้ตัว V เป็นพื้นให้ตัวเลข
    _seg_digit(4, 0.0, 1.772, zt + 0.0008, 0.042, white)  # วาดเลข 4 สีขาวลงบนป้ายนั้น (ความสูงตัวเลข 4.2 ซม.)
    glPopMatrix()  # "กลับไปตำแหน่งเดิม" ที่จำไว้ตอนแรก เพื่อไม่ให้การย้าย/หมุนไปกระทบของชิ้นอื่น
 
 
def kat_vr_station(logo, cx=KAT_POS[0], cz=KAT_POS[1], yaw=KAT_YAW):  # ประกาศสูตร "วางเครื่อง KAT VR พร้อมกรอบกันชน" ถ้าไม่ระบุตำแหน่งและทิศ จะใช้ค่าที่ตั้งไว้ด้านบนสุด
    """วาด KAT VR + ใส่กล่องชน 2 กล่อง (ฐาน, บันได) ให้เดินทะลุไม่ได้"""  # คำอธิบาย: วาดเครื่อง และเพิ่มกรอบกันชน 2 กรอบ (ฐาน กับ บันได) เพื่อไม่ให้ผู้เล่นเดินทะลุ
    kat_vr(logo, cx, cz, yaw)  # วาดตัวเครื่อง
    th = math.radians(yaw)  # แปลงองศาที่หมุนเป็นเรเดียน
    cs, sn = math.cos(th), math.sin(th)  # หาตัวเลขที่ใช้คำนวณการหมุน (cos และ sin ของมุมนั้น)
 
    def aabb(pts):  # สูตรย่อย: หา "กรอบสี่เหลี่ยมที่ครอบรูปทรงที่หมุนแล้ว" (aabb = กรอบที่ด้านขนานกับแกนห้อง)
        xs = [cx + p[0] * cs + p[1] * sn for p in pts]  # คำนวณตำแหน่ง x จริงในห้องของทุกมุม หลังจากหมุนตามองศาแล้ว
        zs = [cz - p[0] * sn + p[1] * cs for p in pts]  # คำนวณตำแหน่ง z จริงในห้องของทุกมุมเช่นกัน
        return (min(xs), min(zs), max(xs), max(zs))  # ส่งคืนกรอบ (x ต่ำสุด, z ต่ำสุด, x สูงสุด, z สูงสุด) ที่ครอบทุกมุมพอดี
 
    COLLIDERS.append(aabb(_oct_pts(KAT_R)))  # เพิ่มกรอบกันชนของฐานแปดเหลี่ยมเข้ารายการสิ่งกีดขวาง
    COLLIDERS.append(aabb(KAT_STEP))  # เพิ่มกรอบกันชนของบันไดเข้ารายการสิ่งกีดขวาง



# =====================================================================
# 5.8) ลำโพง JBL PartyBox 310  วางบนพื้นข้างโต๊ะดำ (ด้านขวาของ iMac)
#      ขนาดจริงตามสเปค: กว้าง 325.6 x สูง 687.7 x ลึก 367.8 mm
# =====================================================================
SPK_POS = (4.95, 1.50)      # กลางตัวลำโพง (x, z)  วางบนพื้นข้างทีวีดำ ฝั่งขวา (ทีวีกว้าง x=3.43-4.67) เว้นห่างขอบทีวี ~12 cm
                            # >> ตำแหน่งลำโพงในห้อง: ห่างไปทางขวา 4.95 ม. และลึกเข้าไป 1.50 ม. (แก้เลขตรงนี้เพื่อขยับลำโพง)
SPK_YAW = 0                 # หมุนรอบแกนตั้ง (องศา)  0 = หน้าลำโพง(ตะแกรง+คลิปส้ม)หันไปทาง +Z (เข้าห้อง)
                            # >> มุมหมุนของลำโพง 0 องศา = หันหน้าเข้าห้อง (ใส่ 90 = หมุนไปทางขวา 90 องศา)
SPK_W, SPK_H, SPK_D = 0.3256, 0.6877, 0.3678    # ขนาดลำโพง: กว้าง, สูง, ลึก (เมตร) ตามสเปคจริง
SPK_ORANGE = (0.95, 0.40, 0.08)                 # สีส้มของคลิป JBL (แดงมาก เขียนนิดหน่อย น้ำเงินน้อย = ส้ม)
 
 
def _chamf_rect(hw, hd, c):                     # ฟังก์ชัน: สร้าง "สี่เหลี่ยมที่ตัดมุมเฉียง" (hw=ครึ่งความกว้าง, hd=ครึ่งความลึก, c=ขนาดมุมที่ตัด)
    """สี่เหลี่ยมตัดมุมเฉียง (แปลนตัวลำโพง)"""  # คำอธิบายฟังก์ชัน: รูปร่างมองจากด้านบนของตัวลำโพง
    return [(-hw + c, -hd), (hw - c, -hd), (hw, -hd + c), (hw, hd - c),     # ให้ค่ากลับเป็นรายการจุด 8 จุด (บรรทัดนี้ = ขอบด้านหลัง + มุมหลังขวา + ขอบขวา)
            (hw - c, hd), (-hw + c, hd), (-hw, hd - c), (-hw, -hd + c)]     # จุดที่เหลือ: มุมหน้าขวา ขอบด้านหน้า มุมหน้าซ้าย ขอบซ้าย รวมกันเป็นรูป 8 เหลี่ยมมุมมน
 
 
def _bar(cx, cy, dx, dy, z, length, width, col):    # ฟังก์ชัน: วาด "แท่งสี่เหลี่ยมเอียง" (cx,cy=จุดกึ่งกลางแท่ง, dx,dy=ทิศทางที่แท่งชี้, z=ความลึกที่วาง, length=ยาว, width=กว้าง, col=สี)
    """แท่งสี่เหลี่ยมเอียงบนผิวหน้า (ทำคลิปส้มที่มุมตะแกรง)  (dx, dy) = ทิศของแท่ง"""  # ใช้ทำคลิปสีส้มตรงมุมตะแกรง
    n = math.hypot(dx, dy) or 1.0                   # หาความยาวของลูกศรทิศทาง (ถ้าเป็น 0 ให้ใช้ 1 กันคำนวณพัง)
    dx, dy = dx / n, dy / n                         # ปรับทิศทางให้ยาวเท่ากับ 1 พอดี (ทำให้ขนาดแท่งแม่นยำ)
    px, py = -dy, dx                                # หาทิศที่ตั้งฉากกับแท่ง (ใช้เป็นแนว "ความกว้าง" ของแท่ง)
    hl, hw = length / 2, width / 2                  # ครึ่งหนึ่งของความยาว และครึ่งหนึ่งของความกว้าง (ใช้คำนวณขอบแท่ง)
    gquad([(cx - dx * hl - px * hw, cy - dy * hl - py * hw, z), (cx + dx * hl - px * hw, cy + dy * hl - py * hw, z),     # วาดแผ่นสี่เหลี่ยม: จุดมุม 2 จุดแรก (ปลายแท่งทั้งสองด้านฝั่งหนึ่ง)
           (cx + dx * hl + px * hw, cy + dy * hl + py * hw, z), (cx - dx * hl + px * hw, cy - dy * hl + py * hw, z)], [col] * 4)  # จุดมุม 2 จุดหลัง (ฝั่งตรงข้าม) แล้วทาสี col ทั้ง 4 มุม
 
 
def _spk_grille(z, hx, y0, y1, logo=None):      # ฟังก์ชัน: วาด "แผงตะแกรง" 1 ด้าน (z=ระยะผิวด้านนอก, hx=ครึ่งความกว้างแผง, y0=ขอบล่าง, y1=ขอบบน, logo=โลโก้ถ้าต้องการ)
    """แผงตะแกรงบนผิวที่หันไปทาง +Z ของระบบพิกัดตอนนี้: พื้นเข้ม + เส้นตะแกรงถี่ + คลิปส้ม 4 มุม (+ โลโก้)"""    # สรุป: พื้นดำ + เส้นตะแกรงถี่ ๆ + คลิปส้มที่ 4 มุม (+โลโก้ถ้ามี)
    gquad([(-hx, y0, z), (hx, y0, z), (hx, y1, z), (-hx, y1, z)], [(0.035, 0.035, 0.04)] * 4)     # วาดแผ่นพื้นสีดำเข้มเป็นฉากหลังของตะแกรง
    zz = z + 0.0006                                 # ยกชั้นถัดไปให้ลอยเหนือพื้นนิดเดียว (0.6 มม.) ไม่ให้ภาพกระพริบทับกัน
    n = int((y1 - y0) / 0.0065)                     # คำนวณว่าจะวาดเส้นตะแกรงได้กี่เส้น (เว้นห่างเส้นละ 6.5 มม.)
    for k in range(n):                                                           # เส้นตะแกรงแนวนอน
                                                    # วนซ้ำ: ทำคำสั่งข้างล่างทีละเส้น เริ่มจากเส้นที่ 0 ไปจนครบ n เส้น
        yy = y0 + 0.003 + k * 0.0065                # หาความสูงของเส้นนี้ (เริ่มจากขอบล่าง แล้วไล่ขึ้นทีละ 6.5 มม.)
        gquad([(-hx + 0.006, yy, zz), (hx - 0.006, yy, zz), (hx - 0.006, yy + 0.0022, zz), (-hx + 0.006, yy + 0.0022, zz)],    # วาดแถบแคบ ๆ หนา 2.2 มม. เว้นขอบซ้ายขวา 6 มม. = 1 เส้นตะแกรง
              [(0.13, 0.13, 0.14)] * 4)             # สีเทาเข้ม ทำให้เห็นเป็นลายเส้นบนพื้นดำ
    for (sx, sy) in ((-1, 1), (1, 1), (-1, -1), (1, -1)):                        # คลิปส้มชี้เข้าหาศูนย์กลาง
                                                    # วนซ้ำ 4 รอบ ตรงกับ 4 มุม: ซ้ายบน, ขวาบน, ซ้ายล่าง, ขวาล่าง (sx = ซ้าย/ขวา, sy = บน/ล่าง)
        cx = sx * (hx - 0.020)                      # ตำแหน่งแนวซ้าย-ขวาของคลิป (ห่างขอบ 2 ซม.)
        cy = (y1 - 0.030) if sy > 0 else (y0 + 0.030)   # ตำแหน่งความสูงของคลิป: ถ้ามุมบนให้ห่างขอบบน 3 ซม. ถ้ามุมล่างให้ห่างขอบล่าง 3 ซม.
        _bar(cx, cy, sx * -1.0, -sy * 1.0, zz + 0.0006, 0.050, 0.013, SPK_ORANGE)    # วาดแท่งสีส้มยาว 5 ซม. กว้าง 1.3 ซม. เอียงชี้เข้าหาตรงกลางแผง
    if logo is not None:                            # ถ้ามีการส่งโลโก้เข้ามา
        _logo_decal(logo, 0.0, (y0 + y1) / 2 - 0.02, zz + 0.0012, 0.075)    # ติดโลโก้ตรงกลางแผง (ต่ำกว่ากึ่งกลางนิดหน่อย) ขนาดประมาณ 7.5 ซม.
 
 
def jbl_speaker(logo, cx, cz, yaw):             # ฟังก์ชันหลัก: สร้างลำโพงทั้งตัว (logo=รูปโลโก้, cx/cz=ตำแหน่งบนพื้น, yaw=มุมหมุน)
    """JBL PartyBox 310: ตัวถังดำมนเหลี่ยม ฝาบนยื่นเล็กน้อย  ด้านหน้า/ข้างมีตะแกรงถี่ + คลิปส้ม 4 มุม
    ด้านบนมีหูหิ้วเว้า แผงปุ่ม และฝาช่องไมค์สีเทา  ด้านหลังมีแผงช่องต่อ + ล้อ 2 ล้อที่มุมล่าง"""    # สรุปรูปลักษณ์ของลำโพงตัวนี้ทั้งหมด
    hw, hd, H = SPK_W / 2, SPK_D / 2, SPK_H         # ครึ่งความกว้าง, ครึ่งความลึก, ความสูงทั้งตัว (ใช้คำนวณขอบต่าง ๆ)
    blk = (0.055, 0.055, 0.06)                      # สีดำของตัวถังลำโพง (ดำอมเทานิด ๆ)
    glPushMatrix()                                  # เซฟตำแหน่งปัจจุบันไว้ก่อน (เดี๋ยวจะย้าย/หมุนเพื่อวางลำโพง)
    glTranslatef(cx, 0, cz)                         # ย้ายจุดวาดไปที่ตำแหน่งลำโพง (ติดพื้น y=0)
    glRotatef(yaw, 0, 1, 0)                         # หมุนรอบแกนตั้ง (แกน y) ตามมุม yaw ที่กำหนด
 
    # ---------- ตัวถัง ----------
    _poly_prism(_chamf_rect(hw, hd, 0.050), 0.018, H - 0.085, blk, top=False)    # สร้างตัวถังหลัก: แท่งรูป 8 เหลี่ยม สูงจาก 1.8 ซม. ถึงใต้ฝาบน 8.5 ซม. (ไม่ปิดหัวแท่ง เพราะฝาบนแยกทำ)
    _poly_prism(_chamf_rect(hw * 1.03, hd * 1.025, 0.054), H - 0.085, H, blk)       # ฝาบนยื่นออกเล็กน้อย
                                                    # สร้างฝาครอบด้านบนหนา 8.5 ซม. ใหญ่กว่าตัวถังนิดหน่อย (3%) ให้ดูเป็นขอบยื่นออกมาแบบลำโพงจริง
    box(-hw + 0.03, 0.0, hd - 0.08, -hw + 0.09, 0.02, hd - 0.03, (0.04, 0.04, 0.045))   # ขายาง
                                                    # วางกล่องเล็กสีดำที่ใต้ลำโพงมุมหน้าซ้าย = ขายางรองพื้น
    box(hw - 0.09, 0.0, hd - 0.08, hw - 0.03, 0.02, hd - 0.03, (0.04, 0.04, 0.045))     # ขายางมุมหน้าขวา
 
    # ---------- ตะแกรงหน้า / ข้าง / หลัง ----------
    _spk_grille(hd + 0.002, 0.125, 0.075, H - 0.125)                               # หน้า (+Z)
                                                    # ติดแผงตะแกรงด้านหน้า (ยื่นออกจากตัวถัง 2 มม.) กว้างข้างละ 12.5 ซม. สูงจาก 7.5 ซม. ถึง 12.5 ซม. ก่อนถึงยอด
    for sgn in (1, -1):                                                           # ข้างซ้าย/ขวา (โลโก้ JBL)
                                                    # วนซ้ำ 2 รอบ: รอบแรกด้านขวา รอบสองด้านซ้าย
        glPushMatrix()                              # เซฟตำแหน่งก่อนหมุน
        glRotatef(90 * sgn, 0, 1, 0)                # หมุนมุมมอง 90 องศา (ซ้ายหรือขวาตามรอบ) เพื่อให้ "ด้านข้าง" กลายเป็น "ด้านหน้า" ชั่วคราว
        _spk_grille(hw + 0.002, 0.140, 0.075, H - 0.125, logo)    # วาดตะแกรงด้านข้างพร้อมโลโก้ JBL
        glPopMatrix()                               # กลับสู่ตำแหน่งที่เซฟไว้ (เลิกหมุน)
    glPushMatrix()                                                                # หลัง (-Z): ตะแกรง + แผงช่องต่อ
                                                    # เซฟตำแหน่งอีกครั้ง เพื่อทำด้านหลัง
    glRotatef(180, 0, 1, 0)                         # หมุนครึ่งรอบ ให้ด้านหลังกลายเป็นด้านหน้าชั่วคราว
    _spk_grille(hd + 0.002, 0.125, 0.075, H - 0.125)    # วาดตะแกรงด้านหลัง (ไม่มีโลโก้)
    zp = hd + 0.0035                                # ระยะลอยของแผงช่องต่อ (สูงกว่าตะแกรงเล็กน้อย)
    gquad([(-0.065, 0.20, zp), (0.065, 0.20, zp), (0.065, 0.36, zp), (-0.065, 0.36, zp)], [(0.16, 0.16, 0.17)] * 4)    # วาดแผงเทาเข้มกว้าง 13 ซม. สูง 16 ซม. = แผงที่เป็นที่ตั้งของช่องเสียบสาย
    for (px, py) in ((-0.03, 0.31), (0.03, 0.31), (-0.03, 0.25), (0.03, 0.25)):    # ช่องเสียบ
                                                    # วนซ้ำ 4 รอบ ตามตำแหน่งช่องเสียบ 4 ช่อง (ซ้ายบน ขวาบน ซ้ายล่าง ขวาล่าง)
        gquad([(px - 0.011, py - 0.011, zp + 0.0006), (px + 0.011, py - 0.011, zp + 0.0006),    # วาดสี่เหลี่ยมจัตุรัสเล็ก 2.2 ซม.: มุมล่าง 2 จุด
               (px + 0.011, py + 0.011, zp + 0.0006), (px - 0.011, py + 0.011, zp + 0.0006)], [(0.02, 0.02, 0.025)] * 4)    # มุมบน 2 จุด และทาสีดำสนิท ให้ดูเหมือนรู
    glPopMatrix()                                   # กลับสู่ตำแหน่งปกติ (เลิกหมุน 180 องศา)
 
    # ---------- ล้อ 2 ล้อที่มุมล่างด้านหลัง ----------
    wr, wz = 0.055, -hd + 0.040                     # wr = รัศมีล้อ 5.5 ซม., wz = ตำแหน่งล้อแนวหน้า-หลัง (ใกล้ด้านหลัง ห่างขอบ 4 ซม.)
    for sgn in (1, -1):                             # วนซ้ำ 2 รอบ: ล้อขวา และล้อซ้าย
        xa, xb = sgn * (hw - 0.012), sgn * (hw + 0.030)     # ขอบในและขอบนอกของล้อ (ล้อยื่นออกจากตัวลำโพงเล็กน้อย)
        x0, x1 = min(xa, xb), max(xa, xb)           # จัดเรียงให้ค่าน้อยมาก่อนค่ามาก (กันสลับลำดับเวลาอยู่ฝั่งซ้าย)
        xcyl(x0, x1, wr, wz, wr, (0.04, 0.04, 0.045), 24)    # วาดตัวล้อเป็นทรงกระบอกนอน สีดำ ความละเอียด 24 เหลี่ยม (ยิ่งมากยิ่งกลม)
        xo = xb + sgn * 0.0006                      # ตำแหน่งหน้าล้อด้านนอก (ยกเล็กน้อยกันภาพซ้อน)
        xring(xo, wr, wz, 0.0, wr, (0.05, 0.05, 0.055), 24)    # วาดหน้ายางล้อเป็นวงกลมเต็ม สีดำ
        xring(xo + sgn * 0.0006, wr, wz, 0.008, 0.026, (0.35, 0.36, 0.38), 20)     # ฝาดุมล้อ
                                                    # วาดวงแหวนสีเทาเงินตรงกลางล้อ = ฝาครอบดุมล้อ
 
    # ---------- ด้านบน ----------
    yt = H + 0.0012                                 # ความสูงของพื้นผิวด้านบน (ยกเหนือฝาเล็กน้อย 1.2 มม. กันภาพซ้อน)
    gquad([(-0.100, yt, 0.075), (0.100, yt, 0.075), (0.100, yt, 0.150), (-0.100, yt, 0.150)], [(0.015, 0.015, 0.02)] * 4)   # หูหิ้วเว้า
                                                    # วาดแผ่นสีดำสนิทกว้าง 20 ซม. = พื้นที่ส่วนเว้าของหูหิ้ว
    for (bx, bz) in ((-0.045, 0.020), (0.0, 0.020), (0.045, 0.020), (-0.045, -0.025), (0.0, -0.025), (0.045, -0.025)):
                                                    # วนซ้ำ 6 รอบ ตามตำแหน่งปุ่มกด 6 ปุ่ม (แถวหน้า 3 ปุ่ม แถวหลัง 3 ปุ่ม)
        cylinder(bx, H, bz, 0.010, 0.003, (0.30, 0.31, 0.33), 14)                  # ปุ่มกด
                                                    # วาดปุ่มกลม รัศมี 1 ซม. สูง 3 มม. สีเทา
    cylinder(-0.105, H, -0.005, 0.014, 0.003, (0.30, 0.31, 0.33), 16)             # ปุ่มพลังงาน/ไฟ
                                                    # วาดปุ่มกลมฝั่งซ้าย (ปุ่มเปิดปิด) ใหญ่กว่าปุ่มทั่วไปเล็กน้อย
    cylinder(0.105, H, -0.005, 0.014, 0.003, (0.30, 0.31, 0.33), 16)              # ปุ่มวอลลุ่ม
                                                    # วาดปุ่มกลมฝั่งขวา (ปุ่มเร่งเสียง)
    gquad([(-0.085, yt + 0.0004, -0.150), (0.085, yt + 0.0004, -0.150), (0.085, yt + 0.0004, -0.108), (-0.085, yt + 0.0004, -0.108)],    # วาดแผ่นกว้าง 17 ซม. ลึก 4.2 ซม. ทางด้านหลังของฝาบน
          [(0.40, 0.41, 0.43)] * 4)                                                  # ฝาช่องไมค์สีเทา
                                                    # ทาสีเทาอ่อน = ฝาปิดช่องเสียบไมโครโฟน
    gquad([(-0.085, yt + 0.0004, -0.108), (0.085, yt + 0.0004, -0.108), (0.085, yt + 0.0004, -0.096), (-0.085, yt + 0.0004, -0.096)],    # วาดแถบแคบ 1.2 ซม. ติดกับขอบฝาสีเทา
          [SPK_ORANGE] * 4)                                                          # ช่องส้มใต้ฝา
                                                    # ทาสีส้ม = ขอบสีส้มที่โผล่ใต้ฝาช่องไมค์
    glPopMatrix()                                   # กลับสู่ตำแหน่งเดิมก่อนวางลำโพง (จบการสร้างลำโพง ไม่ให้กระทบของชิ้นอื่นในห้อง)
 
 
def jbl_speaker_station(logo, cx=SPK_POS[0], cz=SPK_POS[1], yaw=SPK_YAW):    # ฟังก์ชัน: "วางลำโพงลงห้อง" ถ้าไม่ระบุค่า จะใช้ตำแหน่งและมุมที่ตั้งไว้ตอนต้นไฟล์
    """วางลำโพง + กล่องชนตามขนาดจริง"""             # วางลำโพง และสร้าง "กล่องล่องหน" ไว้กันไม่ให้ตัวละครเดินทะลุลำโพง
    jbl_speaker(logo, cx, cz, yaw)                  # เรียกสูตรสร้างลำโพงด้านบน เพื่อวาดลำโพงที่ตำแหน่งที่กำหนด
    th = math.radians(yaw)                          # แปลงมุมจากองศาเป็นเรเดียน (หน่วยที่สูตรคณิตศาสตร์ต้องใช้)
    cs, sn = math.cos(th), math.sin(th)             # คำนวณค่าโคไซน์และไซน์ของมุม (ใช้คำนวณตำแหน่งหลังหมุน)
    pts = [(-SPK_W / 2, -SPK_D / 2), (SPK_W / 2, -SPK_D / 2), (SPK_W / 2, SPK_D / 2), (-SPK_W / 2, SPK_D / 2)]    # จุดมุมทั้ง 4 ของฐานลำโพง (ก่อนหมุน) เทียบกับจุดกึ่งกลาง
    xs = [cx + p[0] * cs + p[1] * sn for p in pts]  # คำนวณตำแหน่งแนวซ้าย-ขวาจริงของแต่ละมุม หลังหมุนและวางลงห้องแล้ว
    zs = [cz - p[0] * sn + p[1] * cs for p in pts]  # คำนวณตำแหน่งแนวหน้า-หลังจริงของแต่ละมุม หลังหมุนและวางลงห้องแล้ว
    COLLIDERS.append((min(xs), min(zs), max(xs), max(zs)))    # เพิ่มกรอบสี่เหลี่ยมที่ครอบลำโพงพอดีเข้าไปในรายการ "สิ่งกีดขวาง" ของห้อง
 
 
# =====================================================================
# 5.9) สวิตช์ไฟข้างสตูลบาร์ตรงประตู (ตามรูปจริง)
#      แผงขาว 3 ช่อง + แผงโครเมียม 2 ช่อง ติดผนังประตู ชิดขอบม่านฝั่งตะวันออก
#      อยู่เหนือสตูลบาร์ตัวที่ x=5.30  แก้ตำแหน่ง/ความสูงได้ที่ค่าคงที่ด้านล่าง
# =====================================================================
SWITCH_Y = 1.25                  # ความสูงกึ่งกลางสวิตช์จากพื้น (เมตร)
                                 # >> สวิตช์อยู่สูงจากพื้น 1.25 เมตร
SWITCH_WHITE_X = (5.20, 5.32)    # แผงขาว 3 ช่อง (x เริ่ม, x จบ)
                                 # >> แผงสีขาววางตั้งแต่ตำแหน่ง 5.20 ถึง 5.32 ม. (กว้าง 12 ซม.)
SWITCH_CHROME_X = (5.085, 5.185) # แผงโครเมียม 2 ช่อง (ชิดขอบม่านที่ x=5.05)
                                 # >> แผงสีโครเมียมวางตั้งแต่ 5.085 ถึง 5.185 ม. (กว้าง 10 ซม.) อยู่ติดกับแผงขาวทางซ้าย
 
 
def light_switches():            # ฟังก์ชัน: สร้างสวิตช์ไฟทั้งหมดบนผนัง
    z = D                                        # ผิวผนังประตูด้านใน (ยื่นเข้าห้องไปทาง -Z)
                                                 # ระยะความลึกของผนังที่ติดสวิตช์ (D คือค่าความลึกห้องที่กำหนดไว้ที่อื่น)
    cy = SWITCH_Y                                # ความสูงกึ่งกลางสวิตช์ (ใช้ชื่อสั้นลงเพื่อเขียนง่าย)
    rocker = (0.93, 0.92, 0.88)                  # สีของปุ่มกดโยก (ขาวนวล ๆ)
    rocker_lo = tuple(v * SHADE_N * 0.80 for v in rocker)   # ครึ่งล่างของปุ่มเข้มกว่า ให้เห็นเป็นปุ่มกดโยก
                                                 # สีครึ่งล่างของปุ่ม: ทำให้เข้มขึ้น 20% (และปรับตามแสงในห้อง SHADE_N) เพื่อให้ดูเป็นปุ่มที่กดเอียงมีเงา
    line = (0.22, 0.22, 0.23)                    # สีเทาเข้ม ใช้ทำเส้นคั่นกลางปุ่ม
 
    # ---------- แผงขาว 3 ช่อง ----------
    x0, x1 = SWITCH_WHITE_X                      # ดึงค่าจุดเริ่ม-จุดจบของแผงขาวมาใช้
    box(x0, cy - 0.039, z - 0.018, x1, cy + 0.039, z, (0.97, 0.97, 0.95))    # วาดแผ่นฐานสีขาว สูง 7.8 ซม. หนา 1.8 ซม. ยื่นจากผนังออกมา
    pitch = (x1 - x0) / 3                        # ความกว้างของ 1 ช่อง (แบ่งแผงเป็น 3 ส่วนเท่า ๆ กัน)
    for i in range(3):                           # วนซ้ำ 3 รอบ ทำสวิตช์ทีละตัว (ตัวที่ 0, 1, 2)
        mx = x0 + pitch * (i + 0.5)              # หาจุดกึ่งกลางของช่องที่ i
        box(mx - 0.0105, cy - 0.021, z - 0.024, mx + 0.0105, cy + 0.021, z - 0.018, rocker)    # วาดตัวปุ่มกดสีขาวนวล กว้าง 2.1 ซม. สูง 4.2 ซม. ยื่นจากแผงอีก 6 มม.
        zf = z - 0.0243                          # ระยะหน้าสุดของปุ่ม (ใช้วาดรายละเอียดบนหน้าปุ่ม)
        gquad([(mx - 0.0105, cy - 0.021, zf), (mx + 0.0105, cy - 0.021, zf),    # ทาครึ่งล่างของปุ่มด้วยสีเข้ม: มุมล่าง 2 จุด
               (mx + 0.0105, cy, zf), (mx - 0.0105, cy, zf)], [rocker_lo] * 4)    # มุมกลางปุ่ม 2 จุด (รวมเป็นแผ่นครึ่งล่าง)
        gquad([(mx - 0.0105, cy - 0.0008, zf - 0.0001), (mx + 0.0105, cy - 0.0008, zf - 0.0001),    # วาดเส้นบาง ๆ ตรงกลางปุ่ม: ขอบล่างของเส้น
               (mx + 0.0105, cy + 0.0008, zf - 0.0001), (mx - 0.0105, cy + 0.0008, zf - 0.0001)], [line] * 4)    # ขอบบนของเส้น ทาสีเทาเข้ม = เส้นแบ่งครึ่งบน/ล่างของปุ่ม
 
    # ---------- แผงโครเมียม 2 ช่อง ----------
    c0, c1 = SWITCH_CHROME_X                     # ดึงค่าจุดเริ่ม-จุดจบของแผงโครเมียมมาใช้
    box(c0, cy - 0.033, z - 0.008, c1, cy + 0.033, z, (0.74, 0.76, 0.79))    # วาดแผ่นฐานสีเงินโครเมียม สูง 6.6 ซม. หนา 8 มม. (บางกว่าแผงขาว)
    for k in range(2):                           # วนซ้ำ 2 รอบ ทำสวิตช์ทีละตัว (ตัวที่ 0 และ 1)
        mx = c0 + (c1 - c0) * (0.30 + 0.40 * k)  # หาจุดกึ่งกลางของสวิตช์ตัวนี้ (ตัวแรกอยู่ที่ 30% ของแผง ตัวสองอยู่ที่ 70%)
        gquad([(mx - 0.013, cy - 0.020, z - 0.0083), (mx + 0.013, cy - 0.020, z - 0.0083),    # วาดช่องสีดำเว้าเข้าไป: มุมล่าง 2 จุด
               (mx + 0.013, cy + 0.020, z - 0.0083), (mx - 0.013, cy + 0.020, z - 0.0083)], [(0.07, 0.07, 0.08)] * 4)   # ช่องเว้าสีดำ
                                                 # มุมบน 2 จุด ทาสีดำ = ช่องที่ปุ่มโยกวางอยู่
        box(mx - 0.009, cy - 0.016, z - 0.015, mx + 0.009, cy + 0.016, z - 0.008, (0.95, 0.95, 0.93))    # วาดปุ่มโยกสีขาว กว้าง 1.8 ซม. สูง 3.2 ซม. วางในช่องดำ
        zf = z - 0.0153                          # ระยะหน้าสุดของปุ่มนี้
        gquad([(mx - 0.009, cy - 0.016, zf), (mx + 0.009, cy - 0.016, zf),    # ทาครึ่งล่างของปุ่มให้เข้มกว่า: มุมล่าง 2 จุด
               (mx + 0.009, cy, zf), (mx - 0.009, cy, zf)], [rocker_lo] * 4)    # มุมกลางปุ่ม 2 จุด ให้ดูเหมือนปุ่มโยกที่กดเอียง

# =====================================================================
# 5.95) หน้าห้อง: ทางเดินหน้าประตูสตูดิโอ (ป้าย CB 30609 Photo Studio)
#       ใช้แกนเดียวกับห้อง: X = ซ้าย->ขวา, Y = สูง, Z = เหนือ->ใต้ (ยิ่ง Z มาก ยิ่งออกไปทางทางเดิน)
#       ทุกตัวเลขเป็นเมตรจริง ค่าที่มาจากรูปที่วัดไว้จะบอกไว้ที่ท้ายบรรทัด
#       ค่าที่ "ประมาณเอา" (ไม่ได้วัด) จะเขียนว่า [ประมาณ] เพื่อให้กลับมาแก้ได้
# =====================================================================
FRONT_WALL_T = 0.12              # ความหนาผนังประตู 12 ซม. [ประมาณ] (จากผนังในห้องที่ z=D ถึงผนังด้านทางเดิน)  # บรรทัดนี้คือค่าคงที่ความหนาผนัง
FZ = D + FRONT_WALL_T            # ตำแหน่ง z ของผิวผนังด้านทางเดิน (ที่ติดตั้งป้าย ชั้นวางรองเท้า)  # คำนวณจากความลึกห้อง + ความหนาผนัง
CORR_W = 2.40                    # ความกว้างทางเดิน 2.40 ม. [ประมาณ] (วัดจากผนังประตูถึงผนังหน้าต่างฝั่งตรงข้าม)  # ค่ากว้างทางเดิน
ZW = FZ + CORR_W                 # ตำแหน่ง z ของผนังหน้าต่างฝั่งตรงข้ามประตู  # ผนังฝั่งหน้าต่างของทางเดิน
FRONT_GROUPS = 4                 # จำนวนกลุ่มหน้าต่างล่างตามแนวทางเดิน  # ใช้สร้างความยาวทางเดินให้พอดีกับกลุ่มหน้าต่าง
GROUP_W = 2.55                   # กว้างของหน้าต่าง 1 กลุ่ม 2.55 ม. (วัดจากรูป)  # ความกว้างหน้าต่างหนึ่งกลุ่ม
PIER_W = 0.40                    # เสาปูนคั่นระหว่างกลุ่มหน้าต่าง 40 ซม. [ประมาณ] (ใช้ค่าเดียวกับเสากลางผนังหน้าต่างในห้อง)  # ความกว้างเสาคั่น
CORR_X1 = 8.60                   # ปลายทางเดินฝั่งขวา (ฝั่งประตูไม้สีน้ำตาลตามรูปแรก) [ประมาณ]  # ขอบทางเดินด้านตะวันออก
CORR_X0 = CORR_X1 - (1.00 + FRONT_GROUPS * GROUP_W + (FRONT_GROUPS - 1) * PIER_W)   # ปลายทางเดินฝั่งซ้าย คำนวณจากจำนวนกลุ่มหน้าต่าง + เว้นปลายข้างละ 0.5 ม.  # ขอบทางเดินด้านตะวันตก
DOOR_OPEN_H = 2.00                # ความสูงช่องประตูที่เดินผ่านได้ 2.00 ม. (เหนือขึ้นไปเป็นช่องแสง)  # ความสูงช่องประตู
DOOR_A, DOOR_B = 2.85, 4.93      # ขอบซ้าย-ขวาของประตูกระจก (ค่าเดียวกับ door_wall ในห้อง)  # ตำแหน่งประตูกระจก
FRAME_HALF = 0.025               # ครึ่งหนึ่งของความกว้างกรอบประตู (กรอบกว้าง 5 ซม.)  # ครึ่งความกว้างกรอบ
DOOR_TOP = 2.60                  # ระดับขอบบนกรอบประตู (ค่าเดียวกับ door_wall ในห้อง)  # ความสูงขอบบนกรอบประตู
STRIP_Y0, STRIP_Y1 = 2.10, 2.58  # หน้าต่างแถบเหนือผนัง: ขอบล่าง 2.10 ขอบบน 2.58 (สูง 48 ซม. ตรงกับที่วัดจากรูป)  # ช่วงความสูงหน้าต่างแถบ
STRIP_X = ((0.48, 2.78), (5.22, 7.52))   # ตำแหน่งหน้าต่างแถบซ้าย-ขวาของประตู (ตรงกับฝั่งในห้องทุกประการ)  # รายการหน้าต่างแถบ 2 ชุด
BASE_X0 = DOOR_B + FRAME_HALF    # จุดเริ่มบัวผนังสีเทา: ชิดขอบกรอบประตูด้านขวา  # ตำแหน่ง x เริ่มต้นของบัวและชั้นวางรองเท้า
BASE_L = 3.37                    # ความยาวบัวผนังสีเทา 3.37 ม. (วัดจากรูป)  # ความยาวบัวผนัง
BASE_H = 0.12                    # ความสูงบัวผนัง 12 ซม. [ประมาณ จากสัดส่วนในรูป]  # ความสูงบัว
BASE_T = 0.02                    # ความหนาบัว 2 ซม. [ประมาณ]  # ความหนาบัว
PANEL_X0 = BASE_X0 + 1.54        # ตำแหน่งรอยต่อแผ่นผนังแผ่นแรก (วัดสัดส่วนจากรูปบัวผนัง)  # จุดตั้งต้นรอยต่อผนัง
PANEL_W = 1.23                   # ความกว้างแผ่นผนัง 1 แผ่น ~1.23 ม. (ระยะรอยต่อที่เห็นในรูป)  # ระยะห่างรอยต่อผนัง
RACK_X0 = BASE_X0                # ชั้นวางรองเท้าเริ่มชิดกรอบประตู (ตามรูปที่วัด 3.45 ม. นับจากจุดเริ่มบัว)  # ตำแหน่ง x ของชั้นแรก
RACK_LENS = (1.15, 1.15, 1.15)   # ความยาวแต่ละชั้น: ชั้นแรก 0.82 ม. (วัดจริง) อีก 2 ชั้น [ประมาณ] ให้ผลรวม = 3.45 ม. (วัดจริง)  # ความยาวของชั้นวาง 3 ชั้น (ยืดได้ไม่เท่ากัน)
RACK_H, RACK_D, RACK_T = 0.49, 0.15, 0.02   # แผ่นข้างสูง 49 ซม. ลึกจากผนัง 15 ซม. (วัดจากรูป) หนา 2 ซม. [ประมาณ]  # ขนาดแผ่นข้างของชั้นวาง
RACK_RODS = 7                    # จำนวนท่อสแตนเลสต่อ 1 ชั้น (นับจากรูป)  # จำนวนราว
RACK_ROD_R = 0.0075              # รัศมีท่อ 7.5 มม. (เส้นผ่านศูนย์กลาง 1.5 ซม.) [ประมาณ]  # ขนาดท่อ
RACK_ROD_Y0 = 0.05               # ความสูงท่อล่างสุดจากพื้น 5 ซม.  # ท่อล่างสุด
RACK_ROD_PITCH = 0.07            # ระยะห่างระหว่างท่อ 7 ซม. (สอดคล้องกับ 98 ซม. ที่วัดจากป้ายลงมาถึงท่อ)  # ระยะห่างท่อแต่ละเส้น
SIGN_GAP = 0.15                  # ระยะจากกรอบประตูถึงขอบซ้ายป้าย 15 ซม. (วัดจากรูป)  # ช่องห่างระหว่างกรอบประตูกับป้าย
SIGN_W, SIGN_H = 0.27, 0.24      # ป้ายกว้าง 27 ซม. สูง 24 ซม. (วัดจากรูป)  # ขนาดป้าย
SIGN_Y1 = STRIP_Y0 - 0.65        # ขอบบนป้าย อยู่ต่ำกว่าขอบล่างหน้าต่างแถบ 65 ซม. (วัดจากรูป)  # ความสูงขอบบนป้าย
SIGN_Y0 = SIGN_Y1 - SIGN_H       # ขอบล่างป้าย = ขอบบนลบความสูงป้าย  # ความสูงขอบล่างป้าย
SIGN_T = 0.004                   # ความหนาป้าย 4 มม. [ประมาณ]  # ความหนาแผ่นป้าย
SILL_H = 0.83                    # ขอบล่างหน้าต่างฝั่งทางเดินสูงจากพื้น 83 ซม. (วัดจากรูป)  # ความสูงขอบหน้าต่างล่าง
WIN_H = 1.14                     # หน้าต่างล่างสูง 1.14 ม. (วัดจากรูป)  # ความสูงตัวหน้าต่างล่าง
PANES = 6                        # แบ่งหน้าต่าง 1 กลุ่มเป็น 6 บาน (นับจากรูป)  # จำนวนบานต่อกลุ่ม
CLERE_Y0 = SILL_H + WIN_H + 0.62 # ขอบล่างหน้าต่างช่องแสงบน: เหนือหน้าต่างล่าง 62 ซม. (วัดจากรูป)  # ความสูงขอบล่างหน้าต่างช่องแสงบน
CLERE_Y1 = H - 0.10              # ขอบบนหน้าต่างช่องแสงบน [ประมาณ] ต่ำกว่าเพดาน 10 ซม.  # ความสูงขอบบนหน้าต่างช่องแสงบน
FRAME_DARK = (0.30, 0.32, 0.35)  # สีกรอบหน้าต่างเทาเข้ม (ค่าเดียวกับกรอบหน้าต่างในห้อง)  # สีกรอบ
FRONT_START = (CORR_X1 - 0.40, FZ + 1.00)   # จุดที่กล้องไปยืนเมื่อกด F: ปลายทางเดินฝั่งขวา ห่างผนังประตู 1 ม.  # ตำแหน่งเริ่มของกล้องในทางเดิน
FRONT_YAW = -math.pi / 2         # ทิศที่หันตอนไปยืนทางเดิน: หันไปทาง -X (ผนังสตูดิโออยู่ทางขวามือ เหมือนรูปแรก)  # มุมหันของกล้อง
# ช่องเจาะผนังประตู (ทั้งฝั่งในห้องและฝั่งทางเดินใช้ชุดเดียวกัน) แต่ละช่อง = (x ซ้าย, x ขวา, y ล่าง, y บน)
WALL_HOLES = [(DOOR_A, DOOR_B, 0.0, DOOR_OPEN_H),                      # ช่องประตูเดินผ่าน สูง 0 ถึง 2.00 ม.
              (DOOR_A, DOOR_B, DOOR_OPEN_H + 0.05, STRIP_Y1)]          # ช่องแสงเหนือประตู สูง 2.05 ถึง 2.58 ม. (ตรงกับกระจกใน door_wall)
WALL_HOLES += [(a, b, STRIP_Y0, STRIP_Y1) for (a, b) in STRIP_X]       # ต่อท้ายด้วยช่องหน้าต่างแถบซ้ายและขวา สูง 2.10 ถึง 2.58 ม.


def tex_terrazzo():              # ประกาศสูตรสร้างลายพื้นหินขัด (terrazzo) ของทางเดิน
    """พื้นหินขัดสีเทาอ่อนมีเม็ดหินสีเข้มกระจาย ภาพหนึ่งใบ = 1.2 m x 1.2 m (รอยต่อแผ่นสีขาวบางๆ)"""  # คำอธิบายสูตร
    s = 256                      # ขนาดรูป 256 x 256 จุด  # ตั้งความละเอียดของลาย
    rng = np.random.default_rng(5)   # ตัวสุ่มเลข (ใส่ 5 เพื่อให้ได้ลายเดิมทุกครั้ง)  # สร้างตัวสุ่ม
    img = np.ones((s, s, 3)) * np.array([0.80, 0.80, 0.81])   # เริ่มด้วยรูปสีเทาอ่อนทั้งภาพ  # สร้างพื้นสีเทา
    for _ in range(1500):        # วนโรยเม็ดหิน 1,500 เม็ด  # ทำซ้ำเพื่อโรยเม็ดหิน
        x = int(rng.integers(0, s - 3))   # สุ่มตำแหน่งแนวนอนของเม็ดหิน  # ตำแหน่ง x ของเม็ด
        y = int(rng.integers(0, s - 3))   # สุ่มตำแหน่งแนวตั้งของเม็ดหิน  # ตำแหน่ง y ของเม็ด
        w = int(rng.integers(1, 4))       # สุ่มความกว้างเม็ด 1-3 จุด  # ความกว้างเม็ด
        h = int(rng.integers(1, 4))       # สุ่มความสูงเม็ด 1-3 จุด  # ความสูงเม็ด
        img[y:y + h, x:x + w] = rng.uniform(0.35, 0.95)   # ทาเม็ดด้วยสีเทาสุ่มตั้งแต่เข้มถึงขาว  # ลงสีเม็ดหิน
    img += rng.normal(0, 0.01, (s, s, 1))   # โรยจุดสุ่มละเอียดให้พื้นดูมีเนื้อ  # เพิ่มความหยาบ
    img[:, :2] = 0.93            # แถบสว่างที่ขอบซ้าย 2 จุด = รอยต่อแผ่นพื้นสีขาว  # รอยต่อแนวตั้ง
    img[:2, :] = 0.93            # แถบสว่างที่ขอบบน 2 จุด = รอยต่อแผ่นพื้นสีขาว  # รอยต่อแนวนอน
    return (np.clip(img, 0, 1) * 255).astype(np.uint8)   # จำกัดค่า 0-1 แล้วแปลงเป็น 0-255 ที่การ์ดจอต้องการ  # ส่งรูปกลับ


def tex_front_wall():            # ประกาศสูตรสร้างลายผนังสีขาวของทางเดิน
    """ผนังสีขาวนวล มีรอยต่อแผ่นบางๆ (ในรูปผนังทางเดินขาวกว่าผนังเทาในห้อง)"""  # คำอธิบายสูตร
    s = 256                      # ขนาดรูป 256 x 256 จุด  # ความละเอียดของลาย
    rng = np.random.default_rng(6)   # ตัวสุ่ม (เลข 6 = ผลเหมือนเดิมทุกครั้ง)  # สร้างตัวสุ่ม
    img = np.ones((s, s, 3)) * np.array([0.93, 0.94, 0.92])   # พื้นสีขาวนวลอมเขียวนิดๆ  # สร้างพื้นสีผนัง
    img += rng.normal(0, 0.008, (s, s, 1))   # โรยจุดสุ่มจางๆ ให้ผนังไม่เรียบเกินไป  # เพิ่มเนื้อผนัง
    img[:, :2] *= 0.82           # แถบมืดที่ขอบซ้าย = รอยต่อแผ่นผนังแนวตั้ง  # รอยต่อแนวตั้ง
    img[:2, :] *= 0.82           # แถบมืดที่ขอบบน = รอยต่อแผ่นผนังแนวนอน  # รอยต่อแนวนอน
    return (np.clip(img, 0, 1) * 255).astype(np.uint8)   # จำกัดค่าแล้วแปลงเป็น 0-255  # ส่งรูปกลับ


def front_shell(ter, fwall):     # ประกาศสูตรวาดตัวทางเดิน: พื้น เพดาน ผนังประตูด้านนอก ผนังหัวท้าย
    L = CORR_X1 - CORR_X0        # ความยาวทางเดินทั้งหมด  # ใช้คำนวณการปูลาย
    tquad(ter, [(CORR_X0, 0, FZ), (CORR_X1, 0, FZ), (CORR_X1, 0, ZW), (CORR_X0, 0, ZW)],   # วาดพื้นทางเดิน: ระบุ 4 มุมที่ความสูง 0  # พื้นหินขัด
          [(0, 0), (L / 1.2, 0), (L / 1.2, CORR_W / 1.2), (0, CORR_W / 1.2)])   # ปูลายซ้ำตามขนาดจริง (ลาย 1 ใบ = 1.2 ม.)  # ตำแหน่งลายบนพื้น
    gquad([(CORR_X0, H, FZ), (CORR_X1, H, FZ), (CORR_X1, H, ZW), (CORR_X0, H, ZW)],   # วาดเพดานทางเดิน: ระบุ 4 มุมที่ความสูง H  # เพดาน
          [(0.90, 0.91, 0.92)] * 4)   # ทาสีขาวอมเทาเหมือนกันทุกมุม  # สีเพดาน
    for (xa, xb, ya, yb) in wall_pieces(CORR_X0, CORR_X1, 0.0, H, WALL_HOLES):   # ผนังด้านนอกแบ่งเป็นหลายชิ้น เว้นช่องประตู ช่องแสง และหน้าต่างแถบ ให้มองทะลุกระจกเข้าไปในสตูดิโอได้  # รายการชิ้นผนัง
        tquad(fwall, [(xa, ya, FZ), (xb, ya, FZ), (xb, yb, FZ), (xa, yb, FZ)],   # วาดท่อนผนังนี้ที่ระนาบ z = FZ  # ผนังด้านนอก
              [((xa - PANEL_X0) / PANEL_W, ya / 1.2), ((xb - PANEL_X0) / PANEL_W, ya / 1.2),   # ตำแหน่งลาย 2 มุมล่าง (รอยต่อเว้นทุก 1.23 ม. แนวนอน 1.2 ม. แนวตั้ง)  # ลายล่าง
               ((xb - PANEL_X0) / PANEL_W, yb / 1.2), ((xa - PANEL_X0) / PANEL_W, yb / 1.2)])   # ตำแหน่งลาย 2 มุมบน  # ลายบน
    tquad(fwall, [(CORR_X0, 0, ZW), (CORR_X1, 0, ZW), (CORR_X1, H, ZW), (CORR_X0, H, ZW)],   # วาดผนังฝั่งหน้าต่าง (เป็นพื้นผนังก่อนวางหน้าต่างทับ)  # ผนังฝั่งตรงข้าม
          [(CORR_X0 / 1.2, 0), (CORR_X1 / 1.2, 0), (CORR_X1 / 1.2, H / 1.2), (CORR_X0 / 1.2, H / 1.2)])   # ปูลายซ้ำทุก 1.2 ม.  # ตำแหน่งลาย
    tquad(fwall, [(CORR_X0, 0, FZ), (CORR_X0, 0, ZW), (CORR_X0, H, ZW), (CORR_X0, H, FZ)],   # วาดผนังปิดหัวทางเดินฝั่งซ้าย  # ผนังหัวซ้าย
          [(0, 0), (CORR_W / 1.2, 0), (CORR_W / 1.2, H / 1.2), (0, H / 1.2)])   # ปูลายซ้ำทุก 1.2 ม.  # ตำแหน่งลาย
    gquad([(CORR_X1, 0, FZ), (CORR_X1, 0, ZW), (CORR_X1, H, ZW), (CORR_X1, H, FZ)],   # วาดผนังปิดหัวทางเดินฝั่งขวา  # ผนังหัวขวา
          [(0.80, 0.64, 0.42)] * 4)   # สีไม้อ่อนตามรูปแรก (ผนังไม้ที่ปลายทางเดิน)  # สีผนังไม้
    box(CORR_X1 - 0.08, 0.0, FZ, CORR_X1, H, FZ + 0.10, (0.35, 0.17, 0.08))   # วาดเสากรอบไม้สีน้ำตาลเข้มที่มุมปลายทาง สูงสุดถึงเพดาน  # กรอบไม้ปลายทาง


def front_door():                # ประกาศสูตรวาดประตูกระจกบานคู่ด้านทางเดิน
    fr = (0.90, 0.90, 0.90)      # สีกรอบประตูขาวเทา  # ตั้งสีกรอบ
    for x in (DOOR_A, DOOR_B):   # วนวางเสากรอบข้างประตู 2 ต้น (ซ้ายและขวา)  # ตำแหน่งเสากรอบ
        box(x - FRAME_HALF, 0.0, FZ, x + FRAME_HALF, DOOR_TOP, FZ + 0.04, fr)   # วาดเสากรอบกว้าง 5 ซม. ยื่นจากผนัง 4 ซม.  # เสากรอบ
    for x in (3.32, W / 2, 4.46):   # วนวางเสากั้นช่องแสงด้านบน 3 ต้น  # เสากั้นช่องแสง
        box(x - FRAME_HALF, DOOR_OPEN_H, FZ, x + FRAME_HALF, DOOR_TOP, FZ + 0.04, fr)   # วาดเสาสั้นจากคานประตูถึงกรอบบน  # เสาช่องแสง
    box(DOOR_A, DOOR_OPEN_H, FZ, DOOR_B, DOOR_OPEN_H + 0.05, FZ + 0.04, fr)   # วาดคานกรอบความสูง 2.0 ม. แบ่งบานประตูกับช่องแสงด้านบน  # คานกลาง
    box(DOOR_A, DOOR_TOP - 0.04, FZ, DOOR_B, DOOR_TOP, FZ + 0.04, fr)   # วาดกรอบบนสุด  # กรอบบน
    # ส่วนที่ทะลุผนังหนา (ระหว่างผนังห้อง z=D กับผนังทางเดิน z=FZ): ขอบประตูซ้าย-ขวา คานบน และพื้น
    box(DOOR_A, 0.0, D, DOOR_A + FRAME_HALF, DOOR_OPEN_H, FZ, fr)   # วาดขอบประตูด้านซ้ายตามความหนาผนัง  # ขอบซ้าย
    box(DOOR_B - FRAME_HALF, 0.0, D, DOOR_B, DOOR_OPEN_H, FZ, fr)   # วาดขอบประตูด้านขวาตามความหนาผนัง  # ขอบขวา
    box(DOOR_A, DOOR_OPEN_H - 0.02, D, DOOR_B, DOOR_OPEN_H, FZ, fr)   # วาดท้องคานเหนือประตู  # คานบน
    box(DOOR_A, 0.0, D, DOOR_B, 0.015, FZ, (0.55, 0.55, 0.57))   # วาดธรณีประตู (พื้นเตี้ย ๆ ต่อห้องกับทางเดิน)  # ธรณีประตู


def front_strip_windows():       # ประกาศสูตรวาดหน้าต่างแถบเหนือผนังด้านทางเดิน (ตรงกับฝั่งในห้อง)
    for (a, b) in STRIP_X:       # วนทำหน้าต่างแถบทีละชุด (ซ้ายประตู / ขวาประตู)  # ไล่ชุดหน้าต่าง
        for i in range(3):       # วนวางเสากั้น 3 ต้น (ซ้าย กลาง ขวา)  # เสากั้นหน้าต่าง
            x = a + (b - a) * i / 2   # คำนวณตำแหน่งเสาให้ห่างเท่ากัน  # ตำแหน่งเสา
            box(x - 0.025, STRIP_Y0 - 0.02, FZ, x + 0.025, STRIP_Y1 + 0.02, FZ + 0.03, (0.50, 0.52, 0.55))   # วาดเสากั้นสีเทา กว้าง 5 ซม.  # เสา
        box(a, STRIP_Y0 - 0.02, FZ, b, STRIP_Y0 + 0.02, FZ + 0.03, (0.50, 0.52, 0.55))   # วาดกรอบล่างของหน้าต่าง  # กรอบล่าง
        box(a, STRIP_Y1 - 0.02, FZ, b, STRIP_Y1 + 0.02, FZ + 0.03, (0.50, 0.52, 0.55))   # วาดกรอบบนของหน้าต่าง  # กรอบบน


def wall_glass():                # ประกาศสูตรวาดกระจกบานเดียวหนาเท่ากำแพง (12 ซม.) เติมช่องแสงเหนือประตูและหน้าต่างแถบ
    for (xa, xb, ya, yb) in WALL_HOLES[1:]:   # วนทีละช่องเจาะ ข้ามช่องแรกสุด (ช่องประตู) เพราะประตูเลื่อนวาดแยกอยู่แล้ว
        glass_quad([(xa, ya, D), (xb, ya, D), (xb, yb, D), (xa, yb, D)])          # หน้ากระจกฝั่งในห้อง (z = D) ชิดผิวผนังพอดี
        glass_quad([(xa, ya, FZ), (xb, ya, FZ), (xb, yb, FZ), (xa, yb, FZ)])      # หน้ากระจกฝั่งทางเดิน (z = FZ) ห่างจากหน้าแรก 12 ซม. = ความหนากำแพง
        glass_quad([(xa, ya, D), (xa, ya, FZ), (xa, yb, FZ), (xa, yb, D)])        # ขอบกระจกด้านซ้าย (ความหนาของบาน)
        glass_quad([(xb, ya, D), (xb, ya, FZ), (xb, yb, FZ), (xb, yb, D)])        # ขอบกระจกด้านขวา
        glass_quad([(xa, yb, D), (xb, yb, D), (xb, yb, FZ), (xa, yb, FZ)])        # ขอบกระจกด้านบน
        glass_quad([(xa, ya, D), (xb, ya, D), (xb, ya, FZ), (xa, ya, FZ)])        # ขอบกระจกด้านล่าง


def front_baseboard():           # ประกาศสูตรวาดบัวผนังสีเทาเข้ม
    box(BASE_X0, 0.0, FZ, BASE_X0 + BASE_L, BASE_H, FZ + BASE_T, (0.38, 0.40, 0.42))   # วาดบัวยาว 3.37 ม. สูง 12 ซม. หนา 2 ซม. เริ่มชิดกรอบประตู  # บัวผนัง


def front_shoe_racks():          # ประกาศสูตรวาดชั้นวางรองเท้าไม้ + ท่อสแตนเลส 3 ชั้นเรียงติดกัน
    wood = (0.76, 0.54, 0.32)    # สีไม้ของแผ่นข้าง  # ตั้งสีไม้
    edge = (0.80, 0.80, 0.42)    # สีขอบเหลืองเขียวด้านหน้าแผ่นข้าง (ตามรูป)  # ตั้งสีขอบ
    x = RACK_X0                  # ตัวนับตำแหน่ง x เริ่มที่ชั้นแรก  # จุดเริ่มวาง
    for L in RACK_LENS:          # วนทำทีละชั้น (ความยาวไม่เท่ากัน)  # ไล่ชั้นวาง
        xa, xb = x, x + L        # ปลายซ้ายและปลายขวาของชั้นนี้  # ขอบชั้น
        for (px0, px1) in ((xa, xa + RACK_T), (xb - RACK_T, xb)):   # วนทำแผ่นข้าง 2 แผ่น (ซ้ายและขวา)  # ไล่แผ่นข้าง
            box(px0, 0.0, FZ, px1, RACK_H, FZ + RACK_D, wood)   # วาดแผ่นไม้ สูง 49 ซม. ลึก 15 ซม. ติดผนัง  # แผ่นไม้
            box(px0, 0.0, FZ + RACK_D - 0.006, px1, RACK_H, FZ + RACK_D, edge)   # วาดแถบขอบสีเหลืองเขียวที่ขอบหน้าแผ่น กว้าง 6 มม.  # ขอบสี
        for k in range(RACK_RODS):   # วนทำท่อทีละเส้นจากล่างขึ้นบน  # ไล่ท่อ
            y = RACK_ROD_Y0 + k * RACK_ROD_PITCH   # ความสูงของท่อเส้นนี้  # ความสูงท่อ
            zc = FZ + 0.03 + 0.10 * (1 - k / (RACK_RODS - 1))   # ท่อบนชิดผนัง ท่อล่างยื่นออกมาไกลขึ้น (ตามรูปด้านข้าง)  # ระยะท่อจากผนัง
            xcyl(xa + RACK_T, xb - RACK_T, y, zc, RACK_ROD_R, STEEL, 10)   # วาดท่อสแตนเลสทรงกระบอกนอน พาดระหว่างแผ่นข้าง 2 แผ่น  # ท่อสแตนเลส
        x = xb                   # ขยับตัวนับไปที่ปลายชั้นนี้ เพื่อวางชั้นถัดไปติดกัน  # ต่อชั้นถัดไป


SIGN_FACE = [None]               # รหัสเท็กซ์เจอร์หน้าป้าย (สร้างใน build_scene)


def tex_sign():
    """หน้าป้ายสแตนเลสตามรูปจริง: ครึ่งบนเงากระจก (มีแถบเงาสะท้อน) ครึ่งล่างสแตนเลสด้านสีครีมเทา
    ขอบล่างเป็นลอนคลื่น มีแถบเงากระจกโผล่ใต้ลอนคลื่น"""
    w, h = 540, 480
    rng = np.random.default_rng(11)
    xs = np.linspace(0, 1, w)[None, :]
    ys = np.linspace(0, 1, h)[:, None]                       # 0 = ขอบบนป้าย
    split = 0.445                                            # รอยต่อครึ่งบน/ครึ่งล่าง
    wave = 0.90 - 0.03 * np.cos(2 * np.pi * 0.9 * xs)        # เส้นลอนคลื่นขอบล่างของแผ่นครีม
    # ---- ครึ่งบน: กระจกเงา ----
    g = 0.86 - 0.34 * np.exp(-(ys / 0.20) ** 2) - 0.14 * np.clip((xs - 0.45) / 0.55, 0, 1)
    g = g + 0 * xs
    top = np.stack([g * 0.99, g, g * 1.01], axis=2)
    # ---- ครึ่งล่าง: สแตนเลสด้านสีครีมเทา ----
    gb = 0.86 - 0.10 * xs + 0 * ys
    bot = np.stack([gb * 0.97, gb * 0.94, gb * 0.89], axis=2)
    bot += rng.normal(0, 0.008, (h, w, 1))
    # ---- แถบเงากระจกใต้ลอนคลื่น ----
    t = np.clip((ys - wave) / 0.09, 0, 1)
    gs = 0.95 - 0.50 * t ** 0.8 - 0.12 * xs
    strip = np.stack([gs, gs, gs * 1.01], axis=2)
    img = np.where(ys[..., None] < split, top, np.where(ys[..., None] < wave[..., None], bot, strip))
    img = np.where(np.abs(ys - split)[..., None] < 0.004, 0.50, img)     # เส้นรอยต่อกลางป้าย
    img = np.where(np.abs(ys - wave)[..., None] < 0.0035, 0.55, img)     # เส้นขอบลอนคลื่น
    e = 0.012
    edge = (xs < e) | (xs > 1 - e) | (ys < e) | (ys > 1 - e)
    img = np.where(edge[..., None], 0.46, img)                          # ขอบป้ายเข้มบาง ๆ
    img = np.flipud(img)                                                # แถวแรกของรูป = ขอบล่างป้าย (v=0)
    return (np.clip(img, 0, 1) * 255).astype(np.uint8)


def front_sign(code_tex, name_tex):
    x0 = DOOR_B + FRAME_HALF + SIGN_GAP
    x1 = x0 + SIGN_W
    zs = FZ + SIGN_T
    zf = zs + 0.0004
    box(x0, SIGN_Y0, FZ, x1, SIGN_Y1, zs, (0.50, 0.52, 0.55))                  # ตัวป้ายสแตนเลส
    tquad(SIGN_FACE[0], [(x0, SIGN_Y0, zf), (x1, SIGN_Y0, zf), (x1, SIGN_Y1, zf), (x0, SIGN_Y1, zf)],
          [(0, 0), (1, 0), (1, 1), (0, 1)])                                    # หน้าป้ายเงาแบบในรูป
    xm = (x0 + x1) / 2
    _logo_decal(code_tex, xm, SIGN_Y1 - 0.22 * SIGN_H, zf + 0.0006, min(0.046, SIGN_W * 0.78 / code_tex[1]))     # "CB 30609" ครึ่งบน (กว้างไม่เกิน 78% ของป้าย)
    _logo_decal(name_tex, xm, SIGN_Y1 - 0.70 * SIGN_H, zf + 0.0006, min(0.040, SIGN_W * 0.85 / name_tex[1]))     # "Photo Studio" ครึ่งล่าง กึ่งกลางป้าย กว้างไม่เกิน 85% ของป้าย


def front_window_wall():         # ประกาศสูตรวาดหน้าต่างฝั่งตรงข้ามประตู (ผนังหน้าต่างของทางเดิน)
    pier = (0.86, 0.87, 0.88)    # สีขอบหน้าต่างล่างที่ยื่นเป็นชั้น  # ตั้งสีขอบ
    box(CORR_X0, 0.0, ZW - 0.03, CORR_X1, 0.12, ZW, (0.15, 0.16, 0.17))   # วาดบัวหินดำตามแนวผนังหน้าต่างทั้งแนว สูง 12 ซม. (ตามรูป)  # บัวหินดำ
    for k in range(FRONT_GROUPS):   # วนทำหน้าต่างทีละกลุ่ม  # ไล่กลุ่มหน้าต่าง
        xr = CORR_X1 - 0.50 - k * (GROUP_W + PIER_W)   # ขอบขวาของกลุ่มนี้ (เว้นปลายทาง 0.5 ม. แล้วถอยทีละ 2.55 + 0.40 ม.)  # ขอบขวากลุ่ม
        xl = xr - GROUP_W        # ขอบซ้ายของกลุ่มนี้  # ขอบซ้ายกลุ่ม
        zg = ZW - 0.004          # ระนาบกระจก ลอยพ้นผนังเข้ามานิดเดียว กันภาพกระพริบ  # ตำแหน่ง z ของกระจก
        gquad([(xl, SILL_H, zg), (xr, SILL_H, zg), (xr, SILL_H + WIN_H, zg), (xl, SILL_H + WIN_H, zg)],   # วาดกระจกหน้าต่างล่าง สูง 0.83-1.97 ม.  # กระจกหน้าต่างล่าง
              [(0.80, 0.86, 0.90), (0.80, 0.86, 0.90), (0.96, 0.97, 0.98), (0.96, 0.97, 0.98)])   # ไล่สีจากฟ้าอ่อน (ล่าง) ไปขาวสว่าง (บน) แทนอาคารฝั่งตรงข้าม  # สีกระจก
        for i in range(PANES + 1):   # วนวางเสากั้นบาน (6 บานต้องมี 7 เสา)  # เสากั้นบาน
            x = xl + GROUP_W * i / PANES   # ตำแหน่งเสาแต่ละต้น ห่างเท่ากัน  # ตำแหน่งเสา
            box(x - 0.02, SILL_H, ZW - 0.06, x + 0.02, SILL_H + WIN_H, ZW, FRAME_DARK)   # วาดเสากั้นสีเทาเข้ม กว้าง 4 ซม.  # เสากั้น
        box(xl, SILL_H - 0.03, ZW - 0.06, xr, SILL_H + 0.01, ZW, FRAME_DARK)   # วาดกรอบล่างหน้าต่าง  # กรอบล่าง
        box(xl, SILL_H + WIN_H - 0.01, ZW - 0.06, xr, SILL_H + WIN_H + 0.03, ZW, FRAME_DARK)   # วาดกรอบบนหน้าต่าง  # กรอบบน
        box(xl - 0.02, SILL_H - 0.04, ZW - 0.16, xr + 0.02, SILL_H, ZW, pier)   # วาดขอบหน้าต่างล่างที่ยื่นเข้าทางเดิน 16 ซม.  # ขอบหน้าต่าง
        gquad([(xl, CLERE_Y0, zg), (xr, CLERE_Y0, zg), (xr, CLERE_Y1, zg), (xl, CLERE_Y1, zg)],   # วาดกระจกช่องแสงบน (ช่วง 2.59 ถึงใกล้เพดาน)  # กระจกช่องแสงบน
              [(0.70, 0.76, 0.80)] * 4)   # สีฟ้าเทา  # สีกระจกช่องแสง
        for i in range(PANES + 1):   # วนวางเสากั้นช่องแสงบน เรียงตรงกับหน้าต่างล่าง  # เสากั้นช่องแสง
            x = xl + GROUP_W * i / PANES   # ตำแหน่งเสาให้ตรงกับหน้าต่างล่าง  # ตำแหน่งเสา
            box(x - 0.015, CLERE_Y0, ZW - 0.05, x + 0.015, CLERE_Y1, ZW, FRAME_DARK)   # วาดเสากั้นบางกว่า กว้าง 3 ซม.  # เสากั้น
        box(xl, CLERE_Y0 - 0.02, ZW - 0.05, xr, CLERE_Y0 + 0.02, ZW, FRAME_DARK)   # วาดกรอบล่างช่องแสง  # กรอบล่าง
        box(xl, CLERE_Y1 - 0.02, ZW - 0.05, xr, CLERE_Y1 + 0.02, ZW, FRAME_DARK)   # วาดกรอบบนช่องแสง  # กรอบบน


def front_corridor(ter, fwall, sign_code, sign_name):   # ประกาศสูตรรวม: เรียกทุกส่วนของหน้าห้องตามลำดับ
    front_shell(ter, fwall)      # วาดพื้น เพดาน ผนัง  # ตัวทางเดิน
    front_door()                 # วาดประตูกระจก  # ประตู
    front_strip_windows()        # วาดหน้าต่างแถบเหนือผนัง  # หน้าต่างแถบ
    wall_glass()                 # วาดกระจกบานเดียวหนาเท่ากำแพงในช่องแสงและหน้าต่างแถบ  # กระจก
    front_baseboard()            # วาดบัวผนังสีเทา  # บัว
    front_shoe_racks()           # วาดชั้นวางรองเท้า 3 ชั้น  # ชั้นวางรองเท้า
    front_sign(sign_code, sign_name)   # วาดป้าย CB 30609 Photo Studio  # ป้าย
    front_window_wall()          # วาดหน้าต่างฝั่งตรงข้าม  # หน้าต่างฝั่งทางเดิน
    COLLIDERS.append((RACK_X0, FZ, RACK_X0 + sum(RACK_LENS), FZ + RACK_D))   # จดพื้นที่ชั้นวางรองเท้าทั้งแถวเป็นสิ่งกีดขวาง เดินทะลุไม่ได้  # กรอบชน


# =====================================================================
# 5.96) ประตูกระจกบานผลักคู่ (swing door): เดินเข้าใกล้แล้วบานผลักเปิดออกจากตัวเอง
#       ยืนฝั่งห้อง = บานผลักออกไปทางทางเดิน / ยืนฝั่งทางเดิน = บานผลักเข้าห้อง
#       บานมีบานพับที่วงกบข้างซ้ายและข้างขวา ประตูต้องขยับทุกเฟรม จึงวาดแยกจากฉากที่อัดไว้
# =====================================================================
DOOR_STATE = [0.0]                   # ระดับเปิดประตู 0 = ปิดสนิท 1 = เปิดสุด (ใช้ลิสต์เพื่อให้ฟังก์ชันอื่นแก้ค่าได้)
DOOR_DIR = [1.0]                     # ทิศที่บานผลักไป: +1 = ผลักไปทางทางเดิน (+Z)  -1 = ผลักเข้าห้อง (-Z)
DOOR_SENSE = 1.4                     # ระยะที่ประตูรับรู้คน (เมตร) เดินเข้ามาในระยะนี้ประตูจะเปิด
DOOR_SPEED = 1.3                     # ความเร็วเปิด/ปิด (เต็มช่วงใช้ ~0.8 วินาที) ยิ่งมากยิ่งเร็ว
DOOR_MAX_ANGLE = 90.0                # มุมที่บานเปิดสุด (องศา)
DOOR_MID = (DOOR_A + DOOR_B) / 2     # กึ่งกลางประตู (รอยต่อบานคู่)
DOOR_ZC = D + 0.06                   # ระนาบกลางบาน (อยู่กลางความหนาผนัง 12 ซม.) เป็นแนวแกนบานพับ
DOOR_T = 0.03                        # ความหนาบาน 3 ซม.


def update_door(cam, dt):
    near = math.hypot(cam.x - DOOR_MID, cam.z - DOOR_ZC) < DOOR_SENSE   # คนอยู่ในระยะเซนเซอร์ไหม
    cur = DOOR_STATE[0]
    if near and cur <= 0.0:          # ประตูปิดสนิทอยู่ แล้วมีคนเข้าใกล้ -> เลือกทิศผลักให้ออกห่างจากตัวคน
        DOOR_DIR[0] = 1.0 if cam.z < DOOR_ZC else -1.0
    # ล็อกทิศไว้ตลอดตอนที่บานเปิดอยู่ (กันบานสวิงกลับมาโดนคนตอนเดินผ่านกลางประตู)
    target = 1.0 if near else 0.0
    step = DOOR_SPEED * dt
    if cur < target:
        cur = min(target, cur + step)
    elif cur > target:
        cur = max(target, cur - step)
    DOOR_STATE[0] = cur


def draw_auto_door():
    o = DOOR_STATE[0]
    o = o * o * (3 - 2 * o)                              # เปิดนุ่ม ๆ ช้า-เร็ว-ช้า
    theta = DOOR_MAX_ANGLE * o * DOOR_DIR[0]             # มุมเปิด (บวก = ผลักไปทาง +Z)
    leaf = (DOOR_B - DOOR_A) / 2 - FRAME_HALF            # ความกว้างบานเดียว
    fr = (0.90, 0.90, 0.90)
    hz = DOOR_T / 2
    h_top = DOOR_OPEN_H - 0.05
    glass = []                                           # เก็บบานกระจกไว้วาดทีหลังสุด (ต้องวาดหลังของทึบ)
    for side in (-1, 1):                                 # -1 = บานซ้าย (บานพับที่ซ้าย)  +1 = บานขวา (บานพับที่ขวา)
        hinge_x = DOOR_A + FRAME_HALF if side < 0 else DOOR_B - FRAME_HALF
        ang = -theta if side < 0 else theta              # บานซ้ายกับขวาหมุนสวนทิศกัน เพื่อให้ผลักไปทางเดียวกัน
        d = 1.0 if side < 0 else -1.0                    # บานยื่นจากบานพับไปทางกลางประตู (+x สำหรับบานซ้าย, -x สำหรับบานขวา)
        glPushMatrix()
        glTranslatef(hinge_x, 0.0, DOOR_ZC)              # ย้ายแกนหมุนไปที่บานพับ
        glRotatef(ang, 0, 1, 0)                          # หมุนรอบแกนตั้งที่บานพับ
        def seg(x0, x1, y0, y1, col):                    # กล่องในพิกัดบาน (x วัดจากบานพับ ไปทางกลางประตู)
            xa, xb = sorted((d * x0, d * x1))
            box(xa, y0, -hz, xb, y1, hz, col)
        seg(0.0, 0.04, 0.0, h_top, fr)                   # เสากรอบด้านบานพับ
        seg(leaf - 0.04, leaf, 0.0, h_top, fr)           # เสากรอบด้านกลางประตู
        seg(0.0, leaf, 0.0, 0.06, fr)                    # ขอบล่าง
        seg(0.0, leaf, DOOR_OPEN_H - 0.09, h_top, fr)    # ขอบบน
        # มือจับแท่งเหล็ก: ติดทั้งสองหน้าของบาน (ผลักได้ทั้งสองฝั่ง)
        xa, xb = sorted((d * (leaf - 0.09), d * (leaf - 0.07)))
        box(xa, 0.90, hz, xb, 1.20, hz + 0.02, STEEL)      # มือจับฝั่ง +Z
        box(xa, 0.90, -hz - 0.02, xb, 1.20, -hz, STEEL)    # มือจับฝั่ง -Z
        # เก็บมุมกระจก (พิกัดโลก) ตามเมทริกซ์ปัจจุบันไว้วาดทีหลัง
        glass.append((hinge_x, ang, d, leaf))
        glPopMatrix()
    glDepthMask(GL_FALSE)
    glEnable(GL_BLEND)
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
    glColor4f(0.45, 0.62, 0.70, 0.30)
    for (hinge_x, ang, d, leaf) in glass:
        glPushMatrix()
        glTranslatef(hinge_x, 0.0, DOOR_ZC)
        glRotatef(ang, 0, 1, 0)
        x0, x1 = sorted((d * 0.04, d * (leaf - 0.04)))
        glBegin(GL_QUADS)
        glVertex3f(x0, 0.06, 0); glVertex3f(x1, 0.06, 0)
        glVertex3f(x1, DOOR_OPEN_H - 0.09, 0); glVertex3f(x0, DOOR_OPEN_H - 0.09, 0)
        glEnd()
        glPopMatrix()
    glDisable(GL_BLEND)
    glDepthMask(GL_TRUE)


# =====================================================================
# 6) ประกอบทั้งหมดเป็น display list (วาดครั้งเดียว)
# =====================================================================
def build_scene():                              # ฟังก์ชัน: สร้างฉากทั้งห้อง (เรียกใช้ครั้งเดียวตอนเริ่มโปรแกรม)
    COLLIDERS.clear()                           # ล้างรายการ "สิ่งกีดขวาง" เก่าทิ้ง เพื่อเริ่มนับใหม่
    GLASS_QUADS.clear()                         # ล้างสมุดจดกระจกใสเก่าทิ้ง เพื่อเริ่มจดใหม่
    tex = (upload_texture(tex_floor()), upload_texture(tex_wall()), upload_texture(tex_ceiling()))    # สร้างลายพื้นผิวของพื้น ผนัง เพดาน แล้วส่งขึ้นการ์ดจอ เก็บเป็นชุดเดียว
    kat_logo = make_text_tex("KAT VR")      # สร้างเท็กซ์เจอร์โลโก้ก่อนเริ่ม display list
                                            # สร้างรูปโลโก้จากข้อความ "KAT VR"
    jbl_logo = make_text_tex("JBL", (95, 96, 102))    # สร้างรูปโลโก้จากข้อความ "JBL" สีเทา
    ter_tex = upload_texture(tex_terrazzo())   # สร้างลายพื้นหินขัดของทางเดิน แล้วส่งขึ้นการ์ดจอ (ต้องทำก่อนเริ่ม display list)
    fwall_tex = upload_texture(tex_front_wall())   # สร้างลายผนังขาวของทางเดิน แล้วส่งขึ้นการ์ดจอ
    SIGN_FACE[0] = upload_texture(tex_sign())   # หน้าป้ายสแตนเลส (ต้องสร้างก่อน display list)
    sign_code = make_text_tex("CB 30609", (26, 27, 30))   # สร้างรูปตัวอักษรเลขห้องสีเข้มสำหรับป้าย
    sign_name = make_text_tex("Photo Studio", (250, 250, 252))   # สร้างรูปตัวอักษรชื่อห้องสีขาวสำหรับป้าย
    lst = glGenLists(1)                         # ขอ "ที่ว่าง 1 ที่" ในการ์ดจอ เพื่อเก็บภาพห้องที่จะวาดไว้
    glNewList(lst, GL_COMPILE)                  # เริ่ม "อัดวิดีโอคำสั่งวาด" คำสั่งต่อจากนี้จะถูกบันทึกไว้ ยังไม่วาดจริงตอนนี้
    room_shell(tex)                             # วาดเปลือกห้อง (พื้น ผนัง เพดาน)
    ceiling_fixtures()                          # วาดของที่ติดเพดาน (เช่น โคมไฟ)
    window_wall()                               # วาดผนังที่มีหน้าต่าง
    door_wall()                                 # วาดผนังที่มีประตู
    east_wall()                                 # วาดผนังด้านตะวันออก
    west_wall()                                 # วาดผนังด้านตะวันตก
    wall_paper_rolls()                          # วาดม้วนฉากถ่ายภาพ (ม้วนกระดาษพื้นหลัง) ที่ติดผนัง
    training_rows()                             # วาดแถวของที่ใช้ฝึก/จัดวางเรียงเป็นแถว
    black_table()                               # วาดโต๊ะสีดำ
    tv_stand()                                  # วาดทีวีพร้อมที่ตั้ง
    cabinet()                                   # วาดตู้
    c_stands()                                  # วาดขาตั้งไฟแบบ C-stand (ขาตั้งอุปกรณ์สตูดิโอ)
    softboxes()                                 # วาดซอฟต์บ็อกซ์ (กล่องกระจายแสงไฟ)
    office_chair(2.37, BLACK_TABLE_Z - 0.58, facing=-1)    # วาดเก้าอี้สำนักงาน วางที่ x=2.37 หน้าโต๊ะดำ (ถอยออกมา 58 ซม.) หันหน้าไปทางโต๊ะ
    stools()                                    # วาดสตูลบาร์
    corner_stuff()                              # วาดข้าวของที่วางตามมุมห้อง
    kat_vr_station(kat_logo)   # KAT VR มุมตะวันออกเฉียงใต้
                               # วาดเครื่อง KAT VR (อุปกรณ์เล่นเกม VR) พร้อมโลโก้ ที่มุมตะวันออกเฉียงใต้
    jbl_speaker_station(jbl_logo)   # ลำโพง JBL ข้างโต๊ะดำ
                                    # วาดลำโพง JBL (ฟังก์ชันที่เราอธิบายไว้ในไฟล์ก่อนหน้า)
    for fan_x in FAN_XS:                        # วนทีละตำแหน่งพัดลม (ซ้ายและขวาของเสากลาง)
        exhaust_fan(fan_x)                      # วาดพัดลมระบายอากาศส่วนที่นิ่ง ณ ตำแหน่งนั้น (ใบพัดจะวาดแยกให้หมุนได้ทีหลัง)
    wall_wires()                                # วาดสายไฟที่พาดผนัง
    light_switches()     # สวิตช์ไฟข้างสตูลบาร์ตรงประตู
                         # วาดสวิตช์ไฟ (ฟังก์ชันที่เราอธิบายไว้ในไฟล์ก่อนหน้า)
    front_corridor(ter_tex, fwall_tex, sign_code, sign_name)   # วาดหน้าห้อง (ทางเดินหน้าประตู) ก่อนวาดของโปร่งใส
    draw_window_glass()  # วาดกระจกหน้าต่างและกระจกประตูทั้งหมดแบบใส (ต้องวาดหลังของทึบทุกอย่าง จึงอยู่ก่อนกระจกตู้)
    cabinet_glass()      # ของโปร่งใสวาดหลังสุด
                         # วาดกระจกของตู้ โดยวาดเป็นอย่างสุดท้าย เพราะของโปร่งใสต้องวาดทีหลังของอื่น ภาพถึงจะถูกต้อง
    glEndList()                                 # จบการ "อัดวิดีโอ" บันทึกชุดคำสั่งวาดเสร็จแล้ว
    return lst                                  # ส่ง "เลขที่เก็บภาพห้อง" กลับไป เพื่อให้เรียกมาแสดงทีหลังได้ทันที
 
 
# =====================================================================
# 7) กล้อง + การเดิน + การชน
# =====================================================================
class Camera:                                   # แม่แบบ "กล้อง" = ตาของผู้เดินชมห้อง
    def __init__(self):                         # ชุดคำสั่งที่ทำงานอัตโนมัติตอนสร้างกล้องขึ้นมาใหม่
        self.reset()                            # เรียกคำสั่ง "รีเซ็ต" เพื่อตั้งกล้องไว้จุดเริ่มต้น
 
    def reset(self):                            # คำสั่ง: ย้ายกล้องกลับจุดเริ่มต้น (ปุ่ม R)
        self.x, self.z = START_POS              # ตั้งตำแหน่งยืนที่จุดเริ่มต้นของห้อง (ซ้าย-ขวา, หน้า-หลัง)
        self.y = EYE_HEIGHT                     # ตั้งความสูงสายตาเท่าคนยืนปกติ
        self.yaw = START_YAW        # radian, 0 = หัน -Z
                                    # ตั้งทิศที่หันหน้าไปตอนเริ่ม (0 = หันไปทางด้านในห้อง)
        self.pitch = 0.0                        # ตั้งให้มองตรง ไม่ก้มไม่เงย
 
    def forward(self):                          # คำสั่ง: คำนวณ "ทิศที่กำลังเดินไปข้างหน้า"
        return math.sin(self.yaw), -math.cos(self.yaw)    # แปลงมุมที่หันอยู่ให้เป็นทิศทางบนพื้น (ซ้าย-ขวา, หน้า-หลัง)
 
    def right(self):                            # คำสั่ง: คำนวณ "ทิศทางด้านขวามือ" (ใช้เดินก้าวข้างด้วยปุ่ม D)
        return math.cos(self.yaw), math.sin(self.yaw)    # ทิศขวามือจะตั้งฉากกับทิศข้างหน้าเสมอ
 
    def look(self):                             # คำสั่ง: บอกระบบวาดภาพว่า "กล้องอยู่ตรงไหน และมองไปทางไหน"
        cp = math.cos(self.pitch)               # คำนวณว่าการก้ม/เงยทำให้ทิศที่มองเข้าสู่แนวนอนน้อยลงเท่าไร
        fx, fz = self.forward()                 # ดึงทิศข้างหน้าที่คำนวณไว้มาใช้
        gluLookAt(self.x, self.y, self.z,       # ตำแหน่งตาของกล้อง (x, ความสูง, z)
                  self.x + fx * cp, self.y + math.sin(self.pitch), self.z + fz * cp,    # จุดที่กล้องจ้องมอง (ตำแหน่งตา + ทิศที่หัน + มุมก้มเงย)
                  0, 1, 0)                      # บอกว่า "ด้านบนของภาพคือทิศขึ้นฟ้า" (กันภาพเอียง)
 
 
def door_leaf_segments():
    """บานประตูกระจก 2 บานตอนนี้ เป็นเส้นตรง 2 เส้น (x_บานพับ, z_บานพับ, x_ปลายบาน, z_ปลายบาน)
    คำนวณมุมเหมือน draw_auto_door() เป๊ะ เพื่อให้ตัวที่ชนอยู่ตรงกับตัวที่เห็น"""
    o = DOOR_STATE[0]
    o = o * o * (3 - 2 * o)
    theta = DOOR_MAX_ANGLE * o * DOOR_DIR[0]
    leaf = (DOOR_B - DOOR_A) / 2 - FRAME_HALF
    segs = []
    for side in (-1, 1):
        hx = DOOR_A + FRAME_HALF if side < 0 else DOOR_B - FRAME_HALF
        ang = math.radians(-theta if side < 0 else theta)
        d = 1.0 if side < 0 else -1.0
        segs.append((hx, DOOR_ZC, hx + d * leaf * math.cos(ang), DOOR_ZC - d * leaf * math.sin(ang)))
    return segs


def door_clearance(x, z):
    """ระยะห่างจากผิวบานประตูถึงตัวผู้เดิน (ติดลบ = ตัวทะลุบานอยู่)"""
    best = 1e9
    for (ax, az, bx, bz) in door_leaf_segments():
        dx, dz = bx - ax, bz - az
        t = max(0.0, min(1.0, ((x - ax) * dx + (z - az) * dz) / (dx * dx + dz * dz)))
        best = min(best, math.hypot(x - (ax + t * dx), z - (az + t * dz)))
    return best - (PLAYER_RADIUS + DOOR_T / 2)


def blocked(x, z, collide=True):                # ฟังก์ชัน: ตรวจว่า "ตำแหน่งนี้เดินเข้าไปไม่ได้ใช่ไหม" (ตอบ True = ไปไม่ได้)
    r = PLAYER_RADIUS                           # ขนาดตัวของผู้เดิน (คิดเป็นวงกลมรอบตัว) กันตัวชนผนังหรือของจนเข้าไปครึ่งตัว
    if door_clearance(x, z) < 0:                # ชนตัวบานประตูกระจก (ทั้งตอนปิด ตอนกำลังเปิด และตอนเปิดค้าง) เช็กเสมอแม้กด C เพราะบานเป็นส่วนของผนัง
        return True
    if z > D - r:                              # ถ้าตัวอยู่ใกล้ผนังประตู หรือเลยออกไปแล้ว (ตัวห้องกับทางเดินเชื่อมกันที่ประตู)
        if z < FZ + r:                          # ถ้ายังอยู่ในช่วงความหนาผนังประตู (ช่วงที่ต้องผ่านช่องประตูเท่านั้น)
            if x < DOOR_A + FRAME_HALF + r or x > DOOR_B - FRAME_HALF - r:   # ถ้าไม่ได้อยู่ตรงช่องประตู (ชนผนังข้างประตู)
                return True                     # ตอบว่า "ไปไม่ได้" (ชนผนัง)
        if z > D and (x < CORR_X0 + r or x > CORR_X1 - r or z > ZW - r):   # ถ้าอยู่ฝั่งทางเดินแล้วแต่จะเลยขอบทางเดิน (ซ้าย ขวา ผนังหน้าต่าง)
            return True                         # ตอบว่า "ไปไม่ได้" (ชนผนังทางเดิน)
    elif x < r or x > W - r or z < r:           # ถ้าอยู่ในห้องปกติ: ถ้าจะเลยขอบห้อง (ซ้าย ขวา ผนังเหนือ)
        return True                             # ตอบว่า "ไปไม่ได้" (ชนผนังห้อง)
    if not collide:                             # ถ้าปิดโหมดชน (ผู้ใช้กดปุ่ม C) ให้ทะลุของได้
        return False                            # ตอบว่า "ไปได้" (แต่ยังทะลุผนังไม่ได้ เพราะเช็คไปแล้วด้านบน)
    for (x0, z0, x1, z1) in COLLIDERS:          # ไล่ดูกรอบสิ่งกีดขวางของในห้องทีละชิ้น (เช่น โต๊ะ ตู้ ลำโพง)
        if x0 - r < x < x1 + r and z0 - r < z < z1 + r:    # ถ้าตำแหน่งนี้อยู่ในกรอบของสิ่งนั้น (รวมระยะขนาดตัวผู้เดินด้วย)
            return True                         # ตอบว่า "ไปไม่ได้" (ชนของ)
    return False                                # เช็คครบแล้วไม่ชนอะไรเลย = ไปได้
 
 
def move(cam, dx, dz, collide=True):            # ฟังก์ชัน: ขยับกล้อง (dx = ระยะซ้าย-ขวา, dz = ระยะหน้า-หลัง)
    # ถ้าบานประตูหมุนมาโดนตัวอยู่แล้ว (ยืนขวางทางบานที่กำลังเปิด) ให้ก้าวถอยออกมาได้ จะได้ไม่ติดค้าง
    nx = cam.x + dx                             # คำนวณตำแหน่ง x ใหม่ถ้าก้าวไป
    if not blocked(nx, cam.z, collide) or (door_clearance(cam.x, cam.z) < 0 and door_clearance(nx, cam.z) >= door_clearance(cam.x, cam.z)):
        cam.x = nx                              # ก็ก้าวไปตำแหน่งนั้นจริง
    nz = cam.z + dz                             # คำนวณตำแหน่ง z ใหม่ถ้าก้าวไป
    if not blocked(cam.x, nz, collide) or (door_clearance(cam.x, cam.z) < 0 and door_clearance(cam.x, nz) >= door_clearance(cam.x, cam.z)):
        cam.z = nz                              # ก็ก้าวไปตำแหน่งนั้นจริง
                                                # (ตรวจแยกทีละแกน ทำให้เดินไถลไปตามผนังได้ ไม่ติดค้างเวลาเดินชนเฉียง ๆ)
 
 
# =====================================================================
# 8) ข้อความบนจอ (HUD)
# =====================================================================
class Overlay:                                  # แม่แบบ "ป้ายข้อความบนจอ" (HUD = ข้อความที่ลอยทับภาพ)
    def __init__(self):                         # ชุดคำสั่งตอนสร้างป้ายขึ้นมาใหม่
        self.font = pygame.font.Font(None, 24)  # เลือกฟอนต์มาตรฐาน ขนาด 24
        self.tex = glGenTextures(1)             # ขอที่ว่างในการ์ดจอ 1 ที่ เพื่อเก็บภาพข้อความ
        self.size = (1, 1)                      # ขนาดป้ายเริ่มต้น (ยังไม่มีข้อความ จึงเล็กที่สุด)
        self.last = None                        # จำข้อความล่าสุดที่แสดง (ไว้เทียบว่าเปลี่ยนไหม)
 
    def update(self, lines):                    # คำสั่ง: อัปเดตข้อความบนป้าย (lines = รายการข้อความทีละบรรทัด)
        if lines == self.last:                  # ถ้าข้อความเหมือนครั้งก่อนเป๊ะ
            return                              # ไม่ต้องทำอะไร ประหยัดแรงเครื่อง
        self.last = list(lines)                 # จำข้อความชุดใหม่ไว้เทียบรอบหน้า
        surfs = [self.font.render(t, True, (255, 255, 255)) for t in lines]    # แปลงข้อความแต่ละบรรทัดเป็น "รูปตัวอักษรสีขาว"
        w = max(s.get_width() for s in surfs) + 16    # ความกว้างป้าย = ความกว้างบรรทัดที่ยาวสุด + ขอบเว้น 16 จุด
        h = sum(s.get_height() + 2 for s in surfs) + 12    # ความสูงป้าย = ความสูงทุกบรรทัดรวมกัน + ช่องไฟ + ขอบ
        surf = pygame.Surface((w, h), pygame.SRCALPHA)    # สร้างกระดาษเปล่าขนาดป้าย (แบบโปร่งใสได้)
        surf.fill((0, 0, 0, 150))               # ระบายพื้นหลังสีดำกึ่งโปร่งใส เพื่อให้อ่านตัวอักษรขาวง่ายแต่ยังเห็นภาพด้านหลัง
        y = 6                                   # เริ่มเขียนบรรทัดแรกที่ระยะ 6 จุดจากขอบบน
        for s in surfs:                         # ไล่วางข้อความทีละบรรทัด
            surf.blit(s, (8, y))                # แปะรูปข้อความลงบนป้าย (ห่างขอบซ้าย 8 จุด)
            y += s.get_height() + 2             # เลื่อนลงไปบรรทัดถัดไป
        data = pygame.image.tostring(surf, "RGBA", False)    # แปลงรูปป้ายเป็นข้อมูลตัวเลขสี (แดง เขียว น้ำเงิน โปร่งใส) เพื่อส่งขึ้นการ์ดจอ
        glBindTexture(GL_TEXTURE_2D, self.tex)  # เลือกที่ว่างในการ์ดจอของป้ายนี้ เพื่อเตรียมใส่ข้อมูล
        glPixelStorei(GL_UNPACK_ALIGNMENT, 1)   # บอกการ์ดจอว่าข้อมูลภาพเรียงต่อกันแบบไม่มีช่องว่าง
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR)    # ตั้งให้ภาพนุ่มเนียนเวลาถูกย่อ
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR)    # ตั้งให้ภาพนุ่มเนียนเวลาถูกขยาย
        glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, w, h, 0, GL_RGBA, GL_UNSIGNED_BYTE, data)    # ส่งรูปป้ายขึ้นการ์ดจอจริง ๆ
        self.size = (w, h)                      # จำขนาดป้ายไว้ใช้ตอนวาด
 
    def draw(self, sw, sh):                     # คำสั่ง: วาดป้ายลงบนจอ (sw, sh = กว้างและสูงของหน้าต่าง)
        glMatrixMode(GL_PROJECTION)             # เข้าโหมดตั้งค่า "วิธีฉายภาพลงจอ"
        glPushMatrix()                          # เซฟการตั้งค่าเดิมไว้ก่อน (จะได้คืนสภาพทีหลัง)
        glLoadIdentity()                        # ล้างการตั้งค่าให้เป็นค่าเริ่มต้นสะอาด ๆ
        glOrtho(0, sw, sh, 0, -1, 1)            # ตั้งให้วาดแบบ 2 มิติแบนราบ (จุดซ้ายบนคือ 0,0) เหมาะกับการวางข้อความ
        glMatrixMode(GL_MODELVIEW)              # เข้าโหมดตั้งค่า "ตำแหน่งของที่จะวาด"
        glPushMatrix()                          # เซฟการตั้งค่าเดิมไว้ก่อน
        glLoadIdentity()                        # ล้างให้เป็นค่าเริ่มต้น
        glDisable(GL_DEPTH_TEST)                # ปิดการเช็คใกล้-ไกล เพื่อให้ป้ายลอยทับทุกอย่างเสมอ
        glEnable(GL_BLEND)                      # เปิดโหมดผสมสี (เพื่อให้พื้นหลังกึ่งโปร่งใสทำงาน)
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)    # กำหนดสูตรผสมสีแบบมาตรฐานของความโปร่งใส
        glEnable(GL_TEXTURE_2D)                 # เปิดการแปะรูป (เพื่อแปะรูปข้อความลงแผ่น)
        glBindTexture(GL_TEXTURE_2D, self.tex)  # เลือกรูปป้ายข้อความที่จะแปะ
        glColor3f(1, 1, 1)                      # ตั้งสีเป็นขาว เพื่อไม่ให้ไปเปลี่ยนสีรูป
        w, h = self.size                        # ดึงขนาดป้ายที่จำไว้มาใช้
        x, y = 10, 10                           # ตำแหน่งป้าย: ห่างมุมซ้ายบนของจอ 10 จุด
        glBegin(GL_QUADS)                       # เริ่มวาดแผ่นสี่เหลี่ยม
        glTexCoord2f(0, 0); glVertex2f(x, y)    # มุมซ้ายบนของแผ่น ผูกกับมุมซ้ายบนของรูป
        glTexCoord2f(1, 0); glVertex2f(x + w, y)    # มุมขวาบน
        glTexCoord2f(1, 1); glVertex2f(x + w, y + h)    # มุมขวาล่าง
        glTexCoord2f(0, 1); glVertex2f(x, y + h)    # มุมซ้ายล่าง
        glEnd()                                 # จบการวาดแผ่นสี่เหลี่ยม
        glDisable(GL_TEXTURE_2D)                # ปิดการแปะรูป (คืนสภาพเดิม)
        glDisable(GL_BLEND)                     # ปิดโหมดผสมสี (คืนสภาพเดิม)
        glEnable(GL_DEPTH_TEST)                 # เปิดการเช็คใกล้-ไกลกลับ เพื่อให้ภาพ 3 มิติของห้องถูกต้องรอบหน้า
        glPopMatrix()                           # คืนการตั้งค่าตำแหน่งที่เซฟไว้
        glMatrixMode(GL_PROJECTION)             # กลับไปโหมดวิธีฉายภาพ
        glPopMatrix()                           # คืนการตั้งค่าวิธีฉายภาพที่เซฟไว้ (กลับเป็นภาพ 3 มิติปกติ)
        glMatrixMode(GL_MODELVIEW)              # กลับสู่โหมดปกติสำหรับวาดห้อง
 
 
# =====================================================================
# 9) โปรแกรมหลัก
# =====================================================================
BASE_FOV = 70.0              # มุมมองปกติ (องศา)
                             # >> มุมกว้างของภาพ ยิ่งเยอะยิ่งเห็นกว้าง (สายตาคนจริงประมาณ 60-90 องศา)
CROUCH_EYE = 1.00            # ความสูงสายตาตอนย่อตัว (เมตร)
                             # >> ตอนกด Ctrl ย่อตัว สายตาจะลดลงเหลือสูง 1 เมตร
ZOOM_MIN, ZOOM_MAX = 1.5, 8.0    # ขีดจำกัดการซูม: ซูมน้อยสุด 1.5 เท่า มากสุด 8 เท่า
 
 
def set_projection(sw, sh, zoom=1.0):           # ฟังก์ชัน: ตั้งค่ามุมมองกล้อง (รวมถึงการซูม)
    """zoom = 1 ปกติ, 3 = ซูมเข้า 3 เท่า (ลดมุมมอง)"""    # อธิบาย: ซูม = แคบมุมมองลง ภาพจึงดูใหญ่ขึ้น
    fov = math.degrees(2 * math.atan(math.tan(math.radians(BASE_FOV / 2)) / zoom))    # คำนวณมุมมองใหม่จากระดับซูม (สูตรคณิตศาสตร์แปลงมุมมองให้แคบลงตามที่ซูม)
    glMatrixMode(GL_PROJECTION)                 # เข้าโหมดตั้งค่าวิธีฉายภาพ
    glLoadIdentity()                            # ล้างค่าเก่า
    gluPerspective(fov, sw / sh, 0.03, 60)      # ตั้งภาพแบบมีมิติใกล้ใหญ่ไกลเล็ก: มุมมอง, สัดส่วนจอ (กว้าง/สูง), เห็นของที่ใกล้สุด 3 ซม. ไกลสุด 60 เมตร
    glMatrixMode(GL_MODELVIEW)                  # กลับสู่โหมดปกติสำหรับวาดของ
 
 
def setup_gl(sw, sh):                           # ฟังก์ชัน: ตั้งค่าระบบวาดภาพเริ่มต้น
    glViewport(0, 0, sw, sh)                    # กำหนดให้วาดภาพเต็มหน้าต่างทั้งหมด
    glEnable(GL_DEPTH_TEST)                     # เปิดการเช็คใกล้-ไกล (ของที่อยู่ใกล้กว่าจะบังของที่ไกลกว่า)
    glClearColor(0.05, 0.05, 0.06, 1)           # ตั้งสีพื้นหลังตอนล้างจอเป็นดำเกือบสนิท
    set_projection(sw, sh)                      # ตั้งมุมมองกล้องเริ่มต้น (ไม่ซูม)
 
 
def render(cam, scene):                         # ฟังก์ชัน: วาดภาพ 1 เฟรมของห้อง (ถูกเรียกวินาทีละ 60 ครั้ง)
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT)    # ลบภาพเฟรมก่อนหน้าทิ้ง เตรียมกระดานเปล่า
    glLoadIdentity()                            # ล้างตำแหน่งที่ตั้งไว้ กลับเป็นจุดเริ่มต้น
    cam.look()                                  # วางกล้องตามตำแหน่งและทิศที่หันอยู่ตอนนี้
    glCallList(scene)                           # เรียก "ภาพห้องที่อัดไว้" ขึ้นมาแสดงทั้งห้องในคำสั่งเดียว (เร็วมาก)
    ang = (pygame.time.get_ticks() / 1000.0) * FAN_RPS * 360.0 % 360.0   # คำนวณมุมที่ใบพัดหมุนไปตอนนี้ จากเวลาที่ผ่านไป (ใช้มุมเดียวกันทั้งสองตัว)
    for fan_x in FAN_XS:                        # วนทีละตำแหน่งพัดลม (ซ้ายและขวาของเสากลาง)
        fan_blades(ang, fan_x)                  # พัดลมหมุน: วาดใบพัดตัวนั้นที่มุมที่คำนวณไว้
    draw_auto_door()                            # วาดประตูเลื่อนอัตโนมัติ (ขยับตามระยะที่คนเข้าใกล้)
                                                # วาดใบพัดลมโดยคำนวณมุมจากเวลาที่ผ่านไป ทำให้ใบพัดหมุนต่อเนื่อง (วาดแยกเพราะเป็นส่วนเดียวที่ขยับ)
 
 
def main():                                     # ฟังก์ชันหลัก: จุดเริ่มต้นทำงานของโปรแกรมทั้งหมด
    pygame.init()                               # เปิดระบบ pygame (รับคีย์บอร์ด เมาส์ หน้าต่าง)
    SW, SH = 1280, 720                          # ขนาดหน้าต่าง: กว้าง 1280 สูง 720 จุด
    pygame.display.set_mode((SW, SH), DOUBLEBUF | OPENGL)    # เปิดหน้าต่างขนาดนั้น แบบรองรับภาพ 3 มิติ และสลับภาพสองชั้นกันกระพริบ
    pygame.display.set_caption("Studio Walkthrough  (1 unit = 1 m)")    # ตั้งชื่อบนแถบหน้าต่าง (บอกว่า 1 หน่วย = 1 เมตร)
    setup_gl(SW, SH)                            # ตั้งค่าระบบวาดภาพเริ่มต้น
    scene = build_scene()                       # สร้างฉากห้องทั้งหมด (ฟังก์ชันส่วนที่ 6 ด้านบน) เก็บไว้ในตัวแปร scene
    overlay = Overlay()                         # สร้างป้ายข้อความบนจอ
    cam = Camera()                              # สร้างกล้อง (ผู้เดิน) ที่จุดเริ่มต้น
    clock = pygame.time.Clock()                 # สร้างนาฬิกาจับเวลา ไว้คุมให้ภาพวิ่งที่ 60 เฟรมต่อวินาที
    zoom_level = 3.0      # ระดับซูมเมื่อกดค้าง (เลื่อนล้อเมาส์ปรับได้)
                          # ตอนกดซูม จะซูมเข้า 3 เท่า (เป็นค่าเริ่มต้น)
    zoom_cur = 1.0        # ซูมปัจจุบัน (ค่อยๆ เลื่อน ไม่กระตุก)
                          # ซูมที่เห็นอยู่ตอนนี้ (เริ่มที่ 1 = ไม่ซูม)
    zoom_applied = 1.0                          # ค่าซูมที่ระบบวาดภาพถูกตั้งไว้ล่าสุด (ไว้เทียบว่าต้องตั้งใหม่ไหม)
 
    grabbed = True                              # สถานะ "เมาส์ถูกล็อกในหน้าต่าง" (เปิดอยู่)
    collide = True                              # สถานะ "เปิดการชนสิ่งของ" (เปิดอยู่)
    show_help = True                            # สถานะ "แสดงข้อความช่วยเหลือ" (เปิดอยู่)
    shots = 0                                   # ตัวนับจำนวนภาพหน้าจอที่ถ่ายไป
    pygame.mouse.set_visible(False)             # ซ่อนลูกศรเมาส์
    pygame.event.set_grab(True)                 # ล็อกเมาส์ไว้ในหน้าต่าง ไม่ให้เลื่อนออกนอกจอ
    pygame.mouse.get_rel()                      # ล้างค่าการขยับเมาส์ที่ค้างอยู่ (กันภาพหมุนกระชากตอนเริ่ม)
 
    running = True                              # สถานะ "โปรแกรมกำลังทำงาน" (เมื่อเป็น False จะเลิกทำงาน)
    while running:                              # วนทำซ้ำเรื่อย ๆ ตราบที่โปรแกรมยังทำงาน (1 รอบ = 1 เฟรมภาพ)
        dt = min(clock.tick(60) / 1000.0, 0.05)    # วัดเวลาที่ผ่านไปตั้งแต่เฟรมก่อน (วินาที) จำกัดไม่เกิน 0.05 กันกระโดดไกลเวลาเครื่องค้าง
        for e in pygame.event.get():            # ไล่ดูเหตุการณ์ที่เกิดขึ้นทีละอย่าง (กดปุ่ม ปิดหน้าต่าง หมุนล้อเมาส์)
            if e.type == QUIT:                  # ถ้าผู้ใช้กดปิดหน้าต่าง
                running = False                 # สั่งให้โปรแกรมเลิกทำงาน
            elif e.type == KEYDOWN:             # ถ้ามีการกดปุ่มบนคีย์บอร์ด
                if e.key == K_ESCAPE:           # ถ้าปุ่มที่กดคือ Esc
                    running = False             # สั่งให้โปรแกรมเลิกทำงาน
                elif e.key == K_TAB:            # ถ้าปุ่มที่กดคือ Tab (สลับเมาส์ล็อก/ปล่อย)
                    grabbed = not grabbed       # สลับสถานะ: ล็อก <-> ปล่อย
                    pygame.mouse.set_visible(not grabbed)    # ถ้าปล่อยเมาส์ ให้แสดงลูกศรเมาส์ ถ้าล็อกให้ซ่อน
                    pygame.event.set_grab(grabbed)    # ล็อกหรือปล่อยเมาส์ในหน้าต่างตามสถานะใหม่
                    pygame.mouse.get_rel()      # ล้างค่าการขยับเมาส์ที่ค้างอยู่ กันภาพกระชาก
                elif e.key == K_c:              # ถ้าปุ่มที่กดคือ C
                    collide = not collide       # สลับเปิด/ปิดการชนสิ่งของ (ปิด = เดินทะลุของได้)
                elif e.key == K_h:              # ถ้าปุ่มที่กดคือ H
                    show_help = not show_help   # สลับแสดง/ซ่อนข้อความช่วยเหลือ
                elif e.key == K_r:              # ถ้าปุ่มที่กดคือ R
                    cam.reset()                 # ย้ายกล้องกลับจุดเริ่มต้น
                elif e.key == K_f:              # ถ้าปุ่มที่กดคือ F (สลับไปมาระหว่างในห้องกับทางเดินหน้าห้อง)
                    if cam.z > D:               # ถ้าตอนนี้อยู่ในทางเดิน
                        cam.reset()             # ย้ายกลับจุดเริ่มต้นในห้อง
                    else:                       # ถ้าตอนนี้อยู่ในห้อง
                        cam.x, cam.z = FRONT_START   # ย้ายไปยืนที่ปลายทางเดิน
                        cam.yaw = FRONT_YAW     # หันไปตามแนวทางเดิน (ผนังสตูดิโออยู่ทางขวา)
                        cam.pitch = 0.0         # มองตรง ไม่ก้มไม่เงย
                elif e.key == K_F12:            # ถ้าปุ่มที่กดคือ F12 (ถ่ายภาพหน้าจอ)
                    shots += 1                  # เพิ่มเลขลำดับภาพที่ถ่าย
                    data = glReadPixels(0, 0, SW, SH, GL_RGB, GL_UNSIGNED_BYTE)    # อ่านสีของทุกจุดบนหน้าจอตอนนี้
                    img = pygame.image.fromstring(data, (SW, SH), "RGB", True)    # แปลงข้อมูลสีเป็นรูปภาพ (พลิกกลับหัวให้ถูกด้าน)
                    pygame.image.save(img, "screenshot_%d.png" % shots)    # บันทึกเป็นไฟล์ screenshot_1.png, screenshot_2.png ... ในโฟลเดอร์ของโปรแกรม
            elif e.type == MOUSEWHEEL:          # ถ้ามีการเลื่อนล้อเมาส์
                zoom_level = max(ZOOM_MIN, min(ZOOM_MAX, zoom_level * (1.15 ** e.y)))    # ปรับระดับซูม (เลื่อนล้อขึ้น = ซูมมากขึ้น) โดยไม่ให้เกินขีดจำกัดต่ำสุด-สูงสุด
 
        # --- ย่อตัว + ซูม ---
        keys = pygame.key.get_pressed()         # อ่านสถานะปุ่มทั้งหมดบนคีย์บอร์ดว่าตอนนี้ปุ่มไหนถูกกดค้างอยู่
        crouching = bool(keys[K_LCTRL] or keys[K_RCTRL])                       # กด Ctrl ค้าง = ย่อตัว
                                                # ถ้ากด Ctrl ซ้ายหรือขวาค้างอยู่ = กำลังย่อตัว
        zooming = bool(keys[K_z] or pygame.mouse.get_pressed()[2])             # กด Z หรือคลิกขวาค้าง = ซูม
                                                # ถ้ากดปุ่ม Z หรือคลิกเมาส์ขวาค้างอยู่ = กำลังซูม
        zoom_cur += ((zoom_level if zooming else 1.0) - zoom_cur) * min(1.0, dt * 12)    # ค่อย ๆ เลื่อนซูมเข้าหาเป้าหมาย (ซูมตามระดับ หรือกลับเป็น 1) ทีละนิด ภาพจึงนุ่มนวลไม่กระตุก
        if abs(zoom_cur - zoom_applied) > 1e-3:    # ถ้าซูมเปลี่ยนไปจากที่ตั้งไว้ล่าสุดมากพอที่จะสังเกตได้
            set_projection(SW, SH, zoom_cur)    # ตั้งมุมมองกล้องใหม่ตามซูมปัจจุบัน
            zoom_applied = zoom_cur             # จำค่าซูมที่ตั้งล่าสุดไว้
        cam.y += ((CROUCH_EYE if crouching else EYE_HEIGHT) - cam.y) * min(1.0, dt * 10)    # ค่อย ๆ ปรับความสูงสายตาให้ลงต่ำ (ย่อตัว) หรือกลับสูงปกติ อย่างนุ่มนวล
 
        # --- หมุนกล้อง ---
        if grabbed:                             # ถ้าเมาส์ถูกล็อกอยู่ (ใช้เมาส์หันมองได้)
            mx, my = pygame.mouse.get_rel()     # อ่านว่าเมาส์ขยับไปซ้าย-ขวาและขึ้น-ลงเท่าไรตั้งแต่เฟรมก่อน
            sens = 0.12 / zoom_cur                                              # ซูมแล้วหมุนช้าลงให้คุมง่าย
                                                # ความไวในการหมุน (ซูมมากยิ่งหมุนช้าลง เพื่อให้เล็งง่าย)
            cam.yaw += math.radians(mx * sens)  # เมาส์ขยับซ้าย-ขวา = หันซ้าย-ขวา
            cam.pitch -= math.radians(my * sens)    # เมาส์ขยับขึ้น-ลง = เงยหน้า-ก้มหน้า
        keys = pygame.key.get_pressed()         # อ่านสถานะปุ่มคีย์บอร์ดอีกครั้ง
        if keys[K_LEFT]:                        # ถ้ากดลูกศรซ้ายค้าง
            cam.yaw -= 1.8 * dt                 # หันซ้าย (ตามเวลาที่ผ่านไป)
        if keys[K_RIGHT]:                       # ถ้ากดลูกศรขวาค้าง
            cam.yaw += 1.8 * dt                 # หันขวา
        if keys[K_UP]:                          # ถ้ากดลูกศรขึ้นค้าง
            cam.pitch += 1.2 * dt               # เงยหน้าขึ้น
        if keys[K_DOWN]:                        # ถ้ากดลูกศรลงค้าง
            cam.pitch -= 1.2 * dt               # ก้มหน้าลง
        cam.pitch = max(-math.radians(85), min(math.radians(85), cam.pitch))    # จำกัดการก้มเงยไม่เกิน 85 องศา (ไม่ให้หันคอหักจนภาพตลบ)
 
        # --- เดิน WASD ---
        fx, fz = cam.forward()                  # ดึงทิศข้างหน้าของกล้อง
        rx, rz = cam.right()                    # ดึงทิศขวามือของกล้อง
        vx = vz = 0.0                           # เริ่มต้นด้วยความเร็วเป็น 0 (ยังไม่ได้เดิน)
        if keys[K_w]:                           # ถ้ากด W (เดินหน้า)
            vx += fx; vz += fz                  # เพิ่มทิศข้างหน้าเข้าไปในการเดิน
        if keys[K_s]:                           # ถ้ากด S (ถอยหลัง)
            vx -= fx; vz -= fz                  # ลบทิศข้างหน้า = เดินถอย
        if keys[K_d]:                           # ถ้ากด D (ก้าวไปทางขวา)
            vx += rx; vz += rz                  # เพิ่มทิศขวามือ
        if keys[K_a]:                           # ถ้ากด A (ก้าวไปทางซ้าย)
            vx -= rx; vz -= rz                  # ลบทิศขวามือ = ก้าวซ้าย
        n = math.hypot(vx, vz)                  # คำนวณความยาวรวมของทิศที่จะเดิน
        if n > 0:                               # ถ้ามีการกดปุ่มเดินอย่างน้อยหนึ่งปุ่ม
            speed = RUN_SPEED if (keys[K_LSHIFT] or keys[K_RSHIFT]) else WALK_SPEED    # ถ้ากด Shift ค้างให้วิ่ง ถ้าไม่ให้เดินปกติ
            if crouching:                       # ถ้ากำลังย่อตัวอยู่
                speed = WALK_SPEED * 0.5                                        # ย่อตัวเดินช้าลง
                                                # ลดความเร็วลงครึ่งหนึ่ง
            move(cam, vx / n * speed * dt, vz / n * speed * dt, collide)    # ขยับกล้องไปตามทิศและความเร็ว (หารด้วย n เพื่อไม่ให้เดินเฉียงเร็วกว่าเดินตรง)
 
        # --- วาด ---
        update_door(cam, dt)                    # อัปเดตประตู: ถ้าคนเข้าใกล้ให้เปิด ถ้าห่างให้ปิด
        render(cam, scene)                      # วาดภาพห้องเฟรมนี้จากมุมมองของกล้อง
        status = "x=%.2f  z=%.2f  (m)   collision: %s" % (cam.x, cam.z, "ON" if collide else "OFF")    # สร้างข้อความสถานะ: ตำแหน่งปัจจุบัน (เมตร) และสถานะเปิด/ปิดการชน
        if crouching:                           # ถ้ากำลังย่อตัว
            status += "   [crouch]"             # ต่อท้ายข้อความว่า [crouch]
        if zoom_cur > 1.05:                     # ถ้ากำลังซูมอยู่ (มากกว่า 1.05 เท่า)
            status += "   [zoom %.1fx]" % zoom_cur    # ต่อท้ายข้อความบอกระดับซูม
        lines = [status]                        # เริ่มรายการข้อความบนจอด้วยบรรทัดสถานะ
        if show_help:                           # ถ้าเปิดแสดงข้อความช่วยเหลือ
            lines += ["WASD walk | Mouse look | Shift run | Ctrl crouch | C collision",    # เพิ่มบรรทัดบอกปุ่ม: เดิน หันมอง วิ่ง ย่อ เปิดปิดชน
                      "Z / Right-click zoom | Mouse wheel = zoom level",    # บรรทัดบอกวิธีซูม
                      "TAB mouse | R reset | F warp room/corridor | H hide | F12 screenshot | Esc quit"]    # บรรทัดบอก ปล่อยเมาส์ รีเซ็ต ซ่อนข้อความ ถ่ายภาพ ออก
        overlay.update(lines)                   # อัปเดตป้ายข้อความด้วยข้อความล่าสุด
        overlay.draw(SW, SH)                    # วาดป้ายข้อความทับบนภาพห้อง
        pygame.display.flip()                   # แสดงภาพที่วาดเสร็จขึ้นหน้าจอ
 
    pygame.quit()                               # จบลูป: ปิดระบบ pygame
    sys.exit()                                  # ออกจากโปรแกรมทั้งหมด
 
 
if __name__ == "__main__":                      # ถ้าไฟล์นี้ถูกเปิดรันโดยตรง
    main()                                      # เริ่มโปรแกรมหลัก